Object.assign(window.TEM8_DICTIONARY, {"tonight":{"media":{"uk":"media/uk/tonight__gb_1.mp3","us":"media/us/tonight__us_1.mp3"},"oxford":{"phon":"təˈnaɪt","pos":"adverb","senses":[{"en":"on or during the evening or night of today","cn":"在今夜；在今晚","ex":{"en":"Will you have dinner with me tonight?","cn":"今天晚上和我一起吃饭好吗？"}},{"en":"the evening or night of today","cn":"今夜；今晚","ex":{"en":"Here are tonight's football results.","cn":"现在报告今晚足球比赛的结果。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在今晚;在今夜","en":"Tonight is used to refer to the evening of today or the night that follows today.","ex":{"en":"I'm at home tonight","cn":"我今晚在家。"}}]},"examples":[{"en":"Here are tonight's football results.","cn":"现在报告今晚足球比赛的结果。"},{"en":"Will you have dinner with me tonight?","cn":"今天晚上和我一起吃饭好吗？"}]},"tourist":{"media":{"uk":"media/uk/tourist__gb_1.mp3","us":"media/us/tourist__us_1.mp3"},"oxford":{"phon":"ˈtʊərɪst","pos":"noun","senses":[{"en":"a person who is travelling or visiting a place for pleasure","cn":"旅游者；观光者；游客","lab":"British English","ex":{"en":"busloads of foreign tourists","cn":"一车一车的外国观光客"}},{"en":"a member of a sports team that is playing a series of official games in a foreign country","cn":"（在国外参加）巡回比赛的运动队队员","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游客;旅游者;观光者","en":"A tourist is a person who is visiting a place for pleasure and interest, especially when they are on holiday.","ex":{"en":"...foreign tourists","cn":"外国游客"}}]},"examples":[{"en":"Further information is available from the local tourist office.","cn":"进一步详情可向当地的旅游办事处查询。"},{"en":"a popular tourist attraction/destination/resort","cn":"为游客所喜爱的旅游景点/目的地/胜地"}]},"tonic":{"media":{"uk":"media/uk/tonic__gb_1.mp3","us":"media/us/tonic__us_1.mp3"},"oxford":{"phon":"ˈtɒnɪk","pos":"noun","senses":[{"en":"a clear fizzy drink (= with bubbles in it) with a slightly bitter taste, that is often mixed with a strong alcoholic drink, especially gin or vodka","cn":"奎宁水，汤力水（一种味微苦、常加于烈性酒中的有气饮料）","g":"[uncountable, countable]","ex":{"en":"a gin and tonic","cn":"一杯杜松子酒奎宁水"}},{"en":"a medicine that makes you feel stronger and healthier, taken especially when you feel tired","cn":"补药；滋补品","g":"[countable]","ex":{"en":"herbal tonics","cn":"滋补草药"}},{"en":"a liquid that you put on your hair or skin in order to make it healthier","cn":"护发液；护肤液","g":"[countable, uncountable]","ex":{"en":"skin tonic","cn":"护肤液"}},{"en":"anything that makes people feel healthier or happier","cn":"使精神振奋的东西","g":"[countable, usually singular]","lab":"old-fashioned","ex":{"en":"The weekend break was just the tonic I needed.","cn":"周末休息正是我所需要的养精蓄锐的机会。"}},{"en":"the first note of a scale of eight notes","cn":"主音（自然音阶中的第一音）","g":"[countable]","lab":"music"},{"en":"the syllable in a tone unit on which a change in pitch takes place","cn":"语调音节，语调核心（区别音高变化的音节）","g":"[countable]","lab":"phonetics"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"奎宁水(略有苦味的无色汽水，常与杜松子酒等调配饮用)","en":"Tonic or tonic water is a colourless fizzy drink that has a slightly bitter flavour and is often mixed with alcoholic drinks, especially gin.","ex":{"en":"Keeler sipped at his gin and tonic.","cn":"基勒小口抿着他加了奎宁水的杜松子酒。"}},{"pos":"N-MASS 物质名词","cn":"补药;补剂;滋补药","en":"A tonic is a medicine that makes you feel stronger, healthier, and less tired.","ex":{"en":"Britons are spending twice as much on health tonics as they were five years ago","cn":"英国人如今在健康补药上花的钱是 5 年前的两倍。"}},{"pos":"N-COUNT 可数名词","cn":"有兴奋(或激励)作用的事物","en":"A tonic is anything that makes you feel stronger, more cheerful, or more enthusiastic.","ex":{"en":"Seeing Marcus at that moment was a great tonic","cn":"在那一刻见到马库斯是非常令人兴奋的事。"}},{"pos":"N-MASS 物质名词","cn":"护肤液;护发液;生发水","en":"Skin tonic or hair tonic is a liquid that you put on your skin or hair in order to improve it."},{"pos":"N-COUNT 可数名词","cn":"主音","en":"The tonic of a musical scale is its first note."}]},"examples":[{"en":"The weekend break was just the tonic I needed.","cn":"周末休息正是我所需要的养精蓄锐的机会。"},{"en":"a gin and tonic","cn":"一杯杜松子酒奎宁水"}]},"tower":{"media":{"uk":"media/uk/tower__gb_1.mp3","us":"media/us/tower__us_1.mp3"},"oxford":{"phon":"ˈtaʊə(r)","pos":"noun","senses":[{"en":"a tall narrow building or part of a building, especially of a church or castle","cn":"塔；建筑物的塔形部分；（尤指教堂或城堡的）塔楼","ex":{"en":"a bell tower","cn":"钟楼"}},{"en":"a tall structure used for sending television or radio signals","cn":"（电视或无线电信号的）发射塔","ex":{"en":"a television tower","cn":"电视塔"}},{"en":"a tall piece of furniture used for storing things","cn":"高柜；高架子","ex":{"en":"a CD tower","cn":"光盘柜"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"塔;塔楼","en":"A tower is a tall, narrow building, that either stands alone or forms part of another building such as a church or castle.","ex":{"en":"...an eleventh century castle with 120-foot high towers.","cn":"带有 120 英尺高塔的 11 世纪城堡"}},{"pos":"VERB 动词","cn":"(比周围的人或物)高出许多；屹立","en":"Someone or something that towers over surrounding people or things is a lot taller than they are.","ex":{"en":"He stood up and towered over her","cn":"他站起身来，比她高出许多。"}},{"pos":"N-COUNT 可数名词","cn":"(无线电或电视信号的)发射塔","en":"A tower is a tall structure that is used for sending radio or television signals.","ex":{"en":"Troops are still in control of the television and radio tower.","cn":"军队仍然控制着电视和广播发射塔。"}},{"pos":"N-COUNT 可数名词","cn":"同tower block","en":"A tower is the same as a tower block .","ex":{"en":"...his design for a new office tower in Frankfurt.","cn":"他为法兰克福一栋新写字楼所作的设计"}},{"pos":"N-COUNT 可数名词","cn":"立式机箱","en":"A tower is a tall box that contains the main parts of a computer, such as the hard disk and the drives."},{"pos":"PHRASE 短语","cn":"(在危难时)可依靠的人，主心骨，支柱","en":"If you refer to someone as a tower of strength, you appreciate them because they give you a lot of help, support, and encouragement when you have problems or are in a difficult situation.","ex":{"en":"Pat was a tower of strength to our whole family.","cn":"帕特是我们全家人的主心骨。"}}]},"examples":[{"en":"He towered over his classmates.","cn":"他的个儿比班里其他同学高出一大截。"},{"en":"She towers over other dancers of her generation.","cn":"她远远超过同时代的舞蹈演员。"}]},"too":{"media":{"uk":"media/uk/too__gb_1.mp3","us":"media/us/too__us_1.mp3"},"oxford":{"phon":"tuː","pos":"adverb","senses":[{"en":"used before adjectives and adverbs to say that something is more than is good, necessary, possible, etc.","cn":"（用于形容词和副词前）太，过于，过度","ex":{"en":"He's far too young to go on his own.","cn":"他年纪太小，不能独自一人去。"}},{"en":"also; as well","cn":"也；又；还","lab":"British English","ex":{"en":"Can I come too?","cn":"我也可以来吗？"}},{"en":"very","cn":"非常；极其","ex":{"en":"I'm not too sure if this is right.","cn":"这是否正确，我没有太大把握。"}},{"en":"used to comment on something that makes a situation worse","cn":"（评说某事物使情况更糟）而且，还","ex":{"en":"She broke her leg last week—and on her birthday too!","cn":"她上星期把腿摔断了，而且还是在她生日那一天！"}},{"en":"used to emphasize something, especially your anger, surprise or agreement with something","cn":"（用以强调生气、惊奇或同意等）","ex":{"en":"‘He did apologize eventually.’ ‘I should think so too!’","cn":"“他终于道歉了。”“我想他应该如此！”"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"(表示同样适用)也","en":"You use too after mentioning another person, thing, or aspect that a previous statement applies to or includes.","ex":{"en":"'Nice to talk to you.' — 'Nice to talk to you too.'","cn":"“和你谈话很高兴。”——“我也一样。”"}},{"pos":"ADV 副词","cn":"(用于补充性信息或评论之后，表示强调)而且，还","en":"You use too after adding a piece of information or a comment to a statement, in order to emphasize that it is surprising or important.","ex":{"en":"We did learn to read, and quickly too","cn":"我们确实学会了阅读，而且学得很快。"}},{"pos":"ADV 副词","cn":"(用于句末，表示强调)而且","en":"You use too at the end of a sentence to emphasize an opinion that you have added after a statement made by you or by another person.","ex":{"en":"'That money's mine.' — 'Of course it is, and quite right too.'","cn":"“那笔钱是我的。”——“当然是你的，而且也理应如此。”"}},{"pos":"ADV 副词","cn":"(幽默或孩子气地坚持己见)确实地，无可否认地","en":"You use too in order to emphasize in a humorous or childish way that you disagree with what someone else has said or that you refuse to obey them.","ex":{"en":"'I'm getting a bike for my birthday.' — 'You are not.' – 'I am too.'","cn":"“我过生日想要一辆自行车。”——“不行。”——“我就要。”"}},{"pos":"ADV 副词","cn":"太;过于","en":"You use too in order to indicate that there is a greater amount or degree of something than is desirable, necessary, or acceptable.","ex":{"en":"Leather jeans that are too big will make you look larger","cn":"过于肥大的皮裤会让你看起来块头更大。"}},{"pos":"ADV 副词","cn":"(与否定词连用，表示缓和语气、礼貌或谨慎)太，十分","en":"You use too with a negative to make what you are saying sound less forceful or more polite or cautious.","ex":{"en":"Americans are never too keen to leave their beloved country…","cn":"美国人从不急于离开他们热爱的国家。"}},{"pos":"ADV 副词","cn":"(表示感谢，较为正式)极其，非常","en":"You use too when you want to emphasize in a fairly formal way your thanks to someone for something that they have done for you.","ex":{"en":"'I'll try and get you a cake.' — 'Oh Ann you're too kind.'","cn":"“我会设法为你弄来一个蛋糕。”——“噢，安，你真是太好了。”"}},{"pos":"PHRASE 短语","cn":"太;极其","en":"You use all too or only too to emphasize that something happens to a greater extent or degree than is pleasant or desirable.","ex":{"en":"She remembered it all too well","cn":"她记得太清楚了。"}},{"pos":"PHRASE 短语","cn":"为时已晚","en":"If you describe a situation as too little too late, you are blaming someone for not doing enough to prevent a problem and for taking action only after the problem had become very bad.","ex":{"en":"They think this is too little too late…","cn":"他们认为这已经为时已晚了。"}},{"pos":"","cn":"","en":"too bad→see: ; too clever by half→see: ; none too→see: ;"}]},"examples":[{"en":"She broke her leg last week — and on her birthday too!","cn":"她上星期把腿摔断了，而且还是在她生日那一天！"},{"en":"‘He did apologize eventually.’ ‘I should think so too!’ “","cn":"他终于道歉了。” “我想他应该如此！”"}]},"torture":{"oxford":{"phon":"ˈtɔːtʃə(r)","pos":"noun","senses":[{"en":"the act of causing somebody severe pain in order to punish them or make them say or do something","cn":"拷打；拷问；酷刑","ex":{"en":"Many of the refugees have suffered torture.","cn":"许多难民都遭受过拷打。"}},{"en":"mental or physical pain; something that causes this","cn":"（精神上或肉体上的）折磨，痛苦；折磨人的事物","lab":"informal","ex":{"en":"The interview was sheer torture from start to finish.","cn":"这次面试从头至尾使人备受煎熬。"}},{"en":"to hurt somebody physically or mentally in order to punish them or make them tell you something","cn":"拷打；拷问；严刑逼供","ex":{"en":"Many of the rebels were captured and tortured by secret police.","cn":"反叛者中许多人被捕并遭到秘密警察的酷刑折磨。"},"pos":"verb"},{"en":"to make somebody feel extremely unhappy or anxious","cn":"使痛苦；使苦恼；使焦急；使受煎熬","ex":{"en":"He spent his life tortured by the memories of his childhood.","cn":"童年的记忆使他痛苦了一辈子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拷打;拷问;虐待","en":"If someone is tortured, another person deliberately causes them great pain over a period of time, in order to punish them or to make them reveal information.","ex":{"en":"French police are convinced that she was tortured and killed","cn":"法国警方确信她是被拷打致死。"}},{"pos":"VERB 动词","cn":"折磨;使痛苦;使苦恼","en":"To torture someone means to cause them to suffer mental pain or anxiety.","ex":{"en":"He would not torture her further by trying to argue with her","cn":"他不愿与她争辩，让她更痛苦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"折磨;痛苦;苦恼;引起痛苦(或苦恼)的事物","en":"If you say that something is torture or a torture, you mean that it causes you great mental or physical suffering.","ex":{"en":"Waiting for the result was torture","cn":"等待结果的过程是一种折磨。"}}]},"media":{"uk":"media/uk/torture__gb_1.mp3","us":"media/us/torture__us_1.mp3"},"examples":[{"en":"Many of the rebels were captured and tortured by secret police.","cn":"反叛者中许多人被捕并遭受到秘密警察的酷刑。"},{"en":"I heard stories of gruesome tortures in prisons.","cn":"我听说过监狱里令人毛骨悚然的刑讯。"}]},"topics":{"lemma":"topic","media":{"uk":"media/uk/topic__gb_1.mp3","us":"media/us/topic__us_1.mp3"}},"torn":{"lemma":"tear","media":{"uk":"media/uk/torn__gb_1.mp3","us":"media/us/torn__us_1.mp3"}},"tops":{"lemma":"top","media":{"uk":"media/uk/top__gb_1.mp3","us":"media/us/top__us_1.mp3"}},"tourism":{"media":{"uk":"media/uk/tourism__gb_1.mp3","us":"media/us/tourism__us_1.mp3"},"oxford":{"phon":"ˈtʊərɪzəm","pos":"noun","senses":[{"en":"the business activity connected with providing accommodation, services and entertainment for people who are visiting a place for pleasure","cn":"旅游业；观光业","lab":"British English","ex":{"en":"The area is heavily dependent on tourism.","cn":"这个地区非常依赖旅游业。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"旅游业","en":"Tourism is the business of providing services for people on holiday, for example hotels, restaurants, and trips.","ex":{"en":"Tourism is vital for the Spanish economy.","cn":"旅游业对西班牙经济至关重要。"}}]},"examples":[{"en":"The area is heavily dependent on tourism.","cn":"这个地区非常依赖旅游业。"},{"en":"the tourism industry","cn":"旅游业"}]},"tongs":{"media":{"img":["media/ldoce/img/tongs.jpg","media/pic/colander_kitchenutensils_comp.jpg"],"uk":"media/uk/tongs__gb_1.mp3","us":"media/us/tongs__us_2.mp3"},"oxford":{"phon":"tɒŋz","pos":"noun","senses":[{"en":"a tool with two long parts that are joined at one end, used for picking up and holding things","cn":"夹剪；夹具；钳子；烧瓶钳","ex":{"en":"a pair of tongs","cn":"一把夹剪"}},{"en":"a tool that is heated and used to curl hair","cn":"烫发钳；卷发钳","g":"[countable]","lab":"both British English"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"钳子;夹具","en":"Tongs are a tool that you use to grip and pick up objects that you do not want to touch. They consist of two long narrow pieces of metal joined together at one end. hammer and tongs→see: ;","ex":{"en":"The waiter lifted rolls from a basket with a pair of silver tongs.","cn":"侍者用一把银钳从篮子里夹起面包卷。"}}]},"examples":[{"en":"a pair of tongs","cn":"一把夹剪"}]},"toastmaster":{"oxford":{"phon":"ˈtəʊstmɑːstə(r)","pos":"noun","senses":[{"en":"a person who introduces the speakers at a formal dinner and calls for people to drink something together in honour of particular people (= proposes toasts)","cn":"宴会主持人；致祝酒词的人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(特别仪式、正式宴会上的)主持人，致祝酒词者","en":"At a special ceremony or formal dinner, the toastmaster is the person who proposes toasts and introduces the speakers."}]},"media":{"uk":"media/uk/toastmaster__gb_1.mp3","us":"media/us/toastmaster__us_1.mp3"}},"ton":{"oxford":{"phon":"tʌn","pos":"noun","senses":[{"en":"a unit for measuring weight, in the UK 2 240 pounds (long ton) and in the US 2 000 pounds (short ton)","cn":"吨（英国为 2 240 磅，即长吨；美国为 2 000 磅，即短吨）","g":"[countable]","lab":"informal","ex":{"en":"What have you got in this bag? It weighs a ton (= is very heavy).","cn":"你这袋子里装的是什么？重死了！"}},{"en":"a unit for measuring the size of a ship. 1 ton is equal to 100 cubic feet.","cn":"注册吨，吨位（船舶大小的计量单位，1 吨等于 100 立方英尺）","g":"[countable]"},{"en":"a lot","cn":"大量；许多","g":"[plural]","lab":"informal","ex":{"en":"They've got tons of money.","cn":"他们腰缠万贯。"}},{"en":"100, especially when connected with a speed of 100 miles per hour","cn":"100；（尤指）每小时 100 英里的速度","lab":"British English, informal，，","ex":{"en":"He was caught doing a ton.","cn":"他被发现以每小时 100 英里的速度行车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"吨(在英国等于2,240 磅;在美国等于 2,000 磅)","en":"A ton is a unit of weight that is equal to 2240 pounds in Britain and to 2000 pounds in the United States.","ex":{"en":"Hundreds of tons of oil spilled into the sea","cn":"数百吨石油溢出流入大海。"}},{"pos":"N-COUNT 可数名词","cn":"同 tonne","en":"A ton is the same as a tonne ."},{"pos":"PHRASE 短语","cn":"对…大发雷霆;怒斥","en":"If someone comes down on you like a ton of bricks, they are extremely angry with you and tell you off because of something wrong that you have done.","ex":{"en":"If you do something awful they all come down on you like a ton of bricks.","cn":"如果你做了错事，他们全都会对你大发雷霆。"}},{"pos":"PHRASE 短语","cn":"非常重;沉得要命","en":"If you say that something weighs a ton, you mean that it is extremely heavy."}]},"media":{"uk":"media/uk/ton__gb_1.mp3","us":"media/us/ton__us_1.mp3"},"examples":[{"en":"He was caught doing a ton.","cn":"他被发现以每小时 100 英里的速度行车。"},{"en":"( informal ) What have you got in this bag? It weighs a ton!","cn":"你这口袋里装的是什么？重死了！"}]},"today":{"media":{"uk":"media/uk/today__gb_1.mp3","us":"media/us/today__us_1.mp3"},"oxford":{"phon":"təˈdeɪ","pos":"adverb","senses":[{"en":"on this day","cn":"在今天；在今日","ex":{"en":"I've got a piano lesson later today.","cn":"今天晚些时候我有一堂钢琴课。"}},{"en":"at the present period","cn":"现在；当今；当代","ex":{"en":"Young people today face a very difficult future at work.","cn":"如今的年轻人面临着充满困难的工作前景。"}},{"en":"this day","cn":"今天；今日","ex":{"en":"Today is her tenth birthday.","cn":"今天是她的十岁生日。"},"pos":"noun"},{"en":"the present period of time","cn":"现在；当今；当代","ex":{"en":"The film is about growing up in today's world.","cn":"这部电影的主题是在当今世界的成长。"},"pos":"noun"},{"en":"a popular BBC radio news programme, broadcast on Radio 4 in the early morning from Monday to Saturday. Many people listen to it while they are getting up and having breakfast. It consists mainly of discussions about matters in the news, especially relating to politics. It was first broadcast in 1957.","cn":"今天：一个受欢迎的BBC广播新闻节目，周一至周六清晨在4号电台播出。很多人在起床和吃早餐时会听。它主要由对新闻事件的讨论组成，尤其是与政治有关的讨论。它于1957年首次播出。","pos":""},{"en":"a US national television news programme broadcast daily in the early morning on NBC. It consists of a mixture of news, interviews, special features and informal discussion. It was first broadcast in 1952.","cn":"今天：美国国家电视新闻节目，每天清晨在NBC播出。它由新闻，采访，专题报道和非正式讨论组成。它于1952年首次播出。","pos":""}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在今天;在今日","en":"You use today to refer to the day on which you are speaking or writing.","ex":{"en":"How are you feeling today?","cn":"你今天感觉怎么样？"}},{"pos":"ADV 副词","cn":"当今;现今;在当代","en":"You can refer to the present period of history as today .","ex":{"en":"The United States is in a serious recession today…","cn":"当今美国正处于严重的衰退时期。"}}]},"examples":[{"en":"Young people today face a very difficult future at work.","cn":"如今的年轻人面临着充满困难的工作前景。"},{"en":"I've got a piano lesson later today.","cn":"今天晚些时候我有一堂钢琴课。"}]},"took":{"lemma":"take","media":{"uk":"media/uk/took__gb_1.mp3","us":"media/us/took__us_1.mp3"}},"tombs":{"lemma":"tomb"},"tolerant":{"media":{"uk":"media/uk/tolerant__gb_1.mp3","us":"media/us/tolerant__us_1.mp3"},"oxford":{"phon":"ˈtɒlərənt","pos":"adjective","senses":[{"en":"able to accept what other people say or do even if you do not agree with it","cn":"忍受的；容忍的；宽容的","ex":{"en":"He has a very tolerant attitude towards other religions.","cn":"他对其他宗教持非常包容的态度。"}},{"en":"able to survive or operate in difficult conditions","cn":"能在困难条件下生存（或操作）的；能耐…的","ex":{"en":"The plants are tolerant of frost.","cn":"这些植物耐霜。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宽容的;容忍的","en":"If you describe someone as tolerant, you approve of the fact that they allow other people to say and do as they like, even if they do not agree with or like it.","ex":{"en":"They need to be tolerant of different points of view","cn":"他们需要容忍不同的观点。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（植物、动物、机器）能耐…的，有耐受性的","en":"If a plant, animal, or machine is tolerant of particular conditions or types of treatment, it is able to bear them without being damaged or hurt.","ex":{"en":"...plants which are more tolerant of dry conditions","cn":"更耐旱的植物"}}]},"examples":[{"en":"He has a very tolerant attitude towards other religions.","cn":"他对其他宗教持非常包容的态度。"},{"en":"The plants are tolerant of frost.","cn":"这些植物耐霜。"}]},"topic":{"media":{"uk":"media/uk/topic__gb_1.mp3","us":"media/us/topic__us_1.mp3"},"oxford":{"phon":"ˈtɒpɪk","pos":"noun","senses":[{"en":"a subject that you talk, write or learn about","cn":"话题；题目；标题","ex":{"en":"The main topic of conversation was Tom's new girlfriend.","cn":"交谈的主要话题是汤姆的新女友。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"题目;话题；论题","en":"A topic is a particular subject that you discuss or write about.","ex":{"en":"The weather is a constant topic of conversation in Britain…","cn":"在英国，天气是交谈中永恒的话题。"}}]},"examples":[{"en":"The article covered a wide range of topics.","cn":"这篇文章讨论了一系列广泛的论题。"},{"en":"The main topic of conversation was Tom's new girlfriend.","cn":"交谈的主要话题是汤姆的新女友。"}]},"toys":{"lemma":"toy","media":{"img":["media/pic/toys_comp.jpg","media/thumb/teddybear.jpg"],"uk":"media/uk/toy__gb_1.mp3","us":"media/us/toy__us_1.mp3"}},"top-notch":{"oxford":{"phon":"ˌtɒp ˈnɒtʃ","pos":"adjective","senses":[{"en":"excellent; of the highest quality","cn":"最好的；卓越的；第一流的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一流的;顶尖的","en":"If you describe someone or something as top-notch, you mean that they are of a very high standard or quality."}]},"media":{"uk":"media/uk/top_notch_1_gb_1.mp3","us":"media/us/top_notch_1_us_1.mp3"},"examples":[{"en":"I was lucky and got myself a job with a top-notch company.","cn":"我很幸运﹐在一家一流的公司找到了一份工作。"}]},"tongue":{"media":{"uk":"media/uk/tongue__gb_1.mp3","us":"media/us/tongue__us_1.mp3"},"oxford":{"phon":"tʌŋ","pos":"noun","senses":[{"en":"the soft part in the mouth that moves around, used for tasting, swallowing, speaking, etc.","cn":"舌；舌头","g":"[countable]","ex":{"en":"He clicked his tongue to attract their attention.","cn":"他咂嘴发出啧啧声以吸引他们的注意。"}},{"en":"the tongue of some animals, cooked and eaten","cn":"口条","g":"[uncountable, countable]","ex":{"en":"a slice of ox tongue","cn":"一片牛口条"}},{"en":"a language","cn":"语言","g":"[countable]","lab":"formal or literary","ex":{"en":"Even when we speak the same tongue we do not always understand one another.","cn":"即使我们说同一种语言，我们也并不总是能理解对方。"}},{"en":"a particular way of speaking","cn":"讲话方式；言谈","g":"[singular]","lab":"formal","ex":{"en":"He has a sharp tongue.","cn":"他说话尖酸刻薄。"}},{"en":"speaking in the way mentioned","cn":"有…说话方式的；说话…的","ex":{"en":"sharp-tongued","cn":"说话尖刻的"}},{"en":"a long, narrow piece of leather under the laces on a shoe","cn":"鞋舌","g":"[countable]"},{"en":"something that is long and narrow and like a tongue in shape","cn":"舌状物","g":"[countable]","lab":"literary","ex":{"en":"a tongue of flame","cn":"火舌"}},{"en":"to stop the flow of air into a wind instrument with your tongue in order to make a note","cn":"吹奏（管乐器）","pos":"verb"},{"en":"to lick something with your tongue","cn":"舔","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"舌;舌头","en":"Your tongue is the soft movable part inside your mouth which you use for tasting, eating, and speaking.","ex":{"en":"I walked over to the mirror and stuck my tongue out","cn":"我走到镜子前面伸出舌头。"}},{"pos":"N-COUNT 可数名词","cn":"说话能力;说话方式","en":"You can use tongue to refer to the kind of things that a person says.","ex":{"en":"…her sharp wit and quick tongue…","cn":"她敏捷的才思和伶俐的口齿"}},{"pos":"N-COUNT 可数名词","cn":"语言","en":"A tongue is a language.","ex":{"en":"The French feel passionately about their native tongue.","cn":"法国人对他们的母语非常热爱。"}},{"pos":"N-VAR 可变名词","cn":"(烹制后通常作为冷盘的)牛舌，羊舌","en":"Tongue is the cooked tongue of an ox or sheep. It is usually eaten cold."},{"pos":"N-COUNT 可数名词","cn":"鞋舌","en":"The tongue of a shoe or boot is the piece of leather which is underneath the laces."},{"pos":"N-COUNT 可数名词","cn":"舌状物;火舌;伸入水中的狭长陆地","en":"A tongue of something such as fire or land is a long thin piece of it.","ex":{"en":"A yellow tongue of flame shot upwards.","cn":"一条黄色的火舌直冲上天。"}},{"pos":"PHRASE 短语","cn":"无诚意的;虚情假意的","en":"A tongue-in-cheek remark or attitude is not serious, although it may seem to be.","ex":{"en":"...a lighthearted, tongue-in-cheek approach","cn":"漫不经心、虚情假意的态度"}},{"pos":"PHRASE 短语","cn":"一言不发;保持缄默","en":"If you hold your tongue, you do not say anything even though you might want to or be expected to, because it is the wrong time to say it.","ex":{"en":"Douglas held his tongue, preferring not to speak out on a politically sensitive issue.","cn":"道格拉斯沉默不语，不愿谈论政治敏感问题。"}},{"pos":"PHRASE 短语","cn":"正确发出(难读单词或短语)的音","en":"If you say that you can not get your tongue round or around a particular word or phrase, you mean that you find it very difficult to pronounce."},{"pos":"PHRASE 短语","cn":"口误","en":"If you describe something you said as a slip of the tongue, you mean that you said it by mistake.","ex":{"en":"At one stage he referred to Anna as John's fiancée, but later said that was a slip of the tongue.","cn":"曾有那么一段时间他把安娜称作约翰的未婚妻，但后来又说那是口误。"}},{"pos":"","cn":"","en":"to bite your tongue→see: ;"}]},"examples":[{"en":"He clicked his tongue to attract their attention.","cn":"他咂嘴发出啧啧声以吸引他们的注意。"},{"en":"It's very rude to stick your tongue out at people.","cn":"向别人吐舌头是非常不礼貌的。"}]},"to":{"media":{"uk":"media/uk/to__gb_1.mp3","us":"media/us/to__us_1.mp3"},"oxford":{"phon":"tə","pos":"preposition","senses":[{"en":"in the direction of something; towards something","cn":"向，朝，往，对着（某方向或某处）","ex":{"en":"I walked to the office.","cn":"我朝办公室走去。"}},{"en":"as far as something","cn":"到，达（某处）","ex":{"en":"The meadows lead down to the river.","cn":"牧场一直延伸到河边。"}},{"en":"located in the direction mentioned from something","cn":"位于…方向","ex":{"en":"Place the cursor to the left of the first word.","cn":"把光标置于第一个单词的左边。"}},{"en":"used to show the person or thing that receives something","cn":"（引出接受者）给，予，向","lab":"formal","ex":{"en":"He gave it to his sister.","cn":"他把那给了他的妹妹。"}},{"en":"used to show the end or limit of a range or period of time","cn":"（表示范围或一段时间的结尾或界限）到，至","ex":{"en":"a drop in profits from $105 million to around $75 million","cn":"利润从 1.05 亿美元降到 7 500 万美元左右"}},{"en":"before the start of something","cn":"在…开始之前；离；差","lab":"especially British English","ex":{"en":"How long is it to lunch?","cn":"离吃午饭还有多久？"}},{"en":"reaching a particular state","cn":"到，达（某种状态）","ex":{"en":"The vegetables were cooked to perfection.","cn":"这些蔬菜烧的火候恰到好处。"}},{"en":"used to show the person or thing that is affected by an action","cn":"（引出受事者或受体）对于，关于","ex":{"en":"She is devoted to her family.","cn":"她深深爱着自己的家庭。"}},{"en":"used to show that two things are attached or connected","cn":"（表示两件事物相接或相连）","ex":{"en":"Attach this rope to the front of the car.","cn":"把这绳子系在小轿车的前面。"}},{"en":"used to show a relationship between one person or thing and another","cn":"（表示两人或事物之间的关系）属于，归于，关于，对于","ex":{"en":"She's married to an Italian.","cn":"她嫁给了一个意大利人。"}},{"en":"directed towards; in connection with","cn":"指向；关于","ex":{"en":"It was a threat to world peace.","cn":"这是对世界和平的威胁。"}},{"en":"used to introduce the second part of a comparison or ratio","cn":"（引出比较或比率的第二部分）比","ex":{"en":"I prefer walking to climbing.","cn":"我喜欢散步多于喜欢爬山。"}},{"en":"used to show a quantity or rate","cn":"（表示数量或比率）等于，每，一","ex":{"en":"There are 2.54 centimetres to an inch.","cn":"一英寸等于 2.54 厘米。"}},{"en":"in honour of somebody/something","cn":"向…表示敬意","ex":{"en":"a monument to the soldiers who died in the war","cn":"阵亡将士纪念碑"}},{"en":"used to show somebody’s attitude or reaction to something","cn":"（表示态度或反应）适合，符合，致使","ex":{"en":"His music isn't really to my taste.","cn":"他的音乐不太合我的口味。"}},{"en":"used to show what somebody’s opinion or feeling about something is","cn":"（表示看法或感觉）按…的看法，据…认为","ex":{"en":"It sounded like crying to me.","cn":"在我听来这像哭。"}},{"en":"while something else is happening or being done","cn":"伴随；随同","ex":{"en":"He left the stage to prolonged applause.","cn":"他在经久不息的掌声中退下了舞台。"}},{"en":"used after verbs of movement to mean ‘with the intention of giving something’","cn":"（用于表示动作的动词之后）为了给，以提供","ex":{"en":"People rushed to her rescue and picked her up.","cn":"人们冲上前来把她救起。"}},{"en":"used to show purpose or intention","cn":"（表示目的或意图）","ex":{"en":"I set out to buy food.","cn":"我动身去买吃的。"},"pos":"infinitive marker"},{"en":"used to show the result of something","cn":"（表示结果）","ex":{"en":"She managed to escape.","cn":"她设法逃走了。"},"pos":"infinitive marker"},{"en":"used to show the cause of something","cn":"（表示原因）","ex":{"en":"I'm sorry to hear that.","cn":"我听到这消息很难过。"},"pos":"infinitive marker"},{"en":"used to show an action that you want or are advised to do","cn":"（表示想做或让做的事情）","ex":{"en":"I'd love to go to France this summer.","cn":"今年夏天我想去法国。"},"pos":"infinitive marker"},{"en":"used to show something that is known or reported about a particular person or thing","cn":"（表示已知或转述的事情）","ex":{"en":"The house was said to be haunted.","cn":"据说这座房子里闹鬼。"},"pos":"infinitive marker"},{"en":"used to show that one action immediately follows another","cn":"（表示一个动作紧跟另一动作）","ex":{"en":"I reached the station only to find that my train had already left.","cn":"我到了车站，却发现我要搭乘的火车已经开走了。"},"pos":"infinitive marker"},{"en":"used to show that you must or should do something","cn":"必须；一定；应该","ex":{"en":"You are not to talk during the exam.","cn":"考试期间不许说话。"},"pos":"infinitive marker"},{"en":"in or into a closed position","cn":"关着；关闭；关上","ex":{"en":"Push the door to.","cn":"推门关上。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(表示方向、目的地)向，朝，往，到","en":"You use to when indicating the place that someone or something visits, moves towards, or points at.","ex":{"en":"Two friends and I drove to Florida during college spring break","cn":"我和两个朋友在大学春假期间开车去了佛罗里达。"}},{"pos":"PREP 介词","cn":"去(参加)","en":"If you go to an event, you go where it is taking place.","ex":{"en":"We went to a party at the leisure centre","cn":"我们去休闲活动中心参加了一个聚会。"}},{"pos":"PREP 介词","cn":"(表示捆、系、拴等)连接，附着","en":"If something is attached to something larger or fixed to it, the two things are joined together.","ex":{"en":"There was a piece of cloth tied to the dog's collar","cn":"狗项圈上系着一条布。"}},{"pos":"PREP 介词","cn":"(表示位置)在，位于","en":"You use to when indicating the position of something. For example, if something is to your left, it is nearer your left side than your right side.","ex":{"en":"Hemingway's studio is to the right","cn":"海明威的工作室在右面。"}},{"pos":"PREP 介词","cn":"给，予","en":"When you give something to someone, they receive it.","ex":{"en":"He picked up the knife and gave it to me","cn":"他捡起刀子递给我。"}},{"pos":"PREP 介词","cn":"(表示动作或情感的对象)对，于","en":"You use to to indicate who or what an action or a feeling is directed towards.","ex":{"en":"Marcus has been most unkind to me today","cn":"马库斯今天对我非常无礼。"}},{"pos":"PREP 介词","cn":"(与某些名词、形容词连用，表示关联)对于，关于","en":"You use to with certain nouns and adjectives to show that a following noun is related to them.","ex":{"en":"He is a witty man, and an inspiration to all of us","cn":"他机智风趣，鼓舞激励着我们所有人。"}},{"pos":"PREP 介词","cn":"对…(说);向…(说)","en":"If you say something to someone, you want that person to listen and understand what you are saying.","ex":{"en":"I'm going to have to explain to them that I can't pay them.","cn":"我将不得不向他们解释我不能付钱给他们。"}},{"pos":"PREP 介词","cn":"(表示反应或态度)致使，致","en":"You use to when indicating someone's reaction to something or their feelings about a situation or event. For example, if you say that something happens to someone's surprise you mean that they are surprised when it happens.","ex":{"en":"To his surprise, the bedroom door was locked…","cn":"令他吃惊的是，卧室门锁上了。"}},{"pos":"PREP 介词","cn":"据…认为","en":"You use to when indicating the person whose opinion you are stating.","ex":{"en":"It was clear to me that he respected his boss","cn":"在我看来他显然很尊重他的上司。"}},{"pos":"PREP 介词","cn":"(表示变化)倾向于，趋于，至","en":"You use to when indicating what something or someone is becoming, or the state or situation that they are progressing towards.","ex":{"en":"The shouts changed to screams of terror.","cn":"喊叫声变成了惊恐的尖叫声。"}},{"pos":"PREP 介词","cn":"(表示雇佣关系)为","en":"To can be used as a way of introducing the person or organization you are employed by, when you perform some service for them.","ex":{"en":"Rickman worked as a dresser to Nigel Hawthorne","cn":"里克曼曾是奈杰尔·霍索恩的服装师。"}},{"pos":"PREP 介词","cn":"(表示时间、数量的界限)达到","en":"You use to to indicate that something happens until the time or amount mentioned is reached.","ex":{"en":"Every vehicle was banned from coming into Mexico City one day a week from Monday to Friday…","cn":"每周一到周五期间都会有一天禁止所有车辆进入墨西哥城。"}},{"pos":"PREP 介词","cn":"(用于列举时)(从…)到…","en":"You use to when indicating the last thing in a range of things, usually when you are giving two extreme examples of something.","ex":{"en":"I read everything from fiction to history.","cn":"从小说到历史，我什么书都读。"}},{"pos":"PREP 介词","cn":"(表示处所、工作变动)(从…)到…","en":"If someone goes from place to place or from job to job, they go to several places, or work in several jobs, and spend only a short time in each one.","ex":{"en":"Larry and Andy had drifted from place to place, worked at this and that.","cn":"拉里和安迪从一处漂泊到另一处，干点这个又干点那个。"}},{"pos":"PHRASE 短语","cn":"来回地;往复地","en":"If someone moves to and fro, they move repeatedly from one place to another and back again, or from side to side.","ex":{"en":"She stood up and began to pace to and fro","cn":"她站起身，开始来回踱步。"}},{"pos":"PREP 介词","cn":"(表示时间)在…之前，(差…)不到…","en":"You use to when you are stating a time which is less than thirty minutes before an hour. For example, if it is 'five to eight', it is five minutes before eight o'clock.","ex":{"en":"At twenty to six I was waiting by the entrance to the station","cn":"5 点 40 分我正在车站入口处等着。"}},{"pos":"PREP 介词","cn":"(表示比率)每","en":"You use to when giving ratios and rates.","ex":{"en":"...engines that can run at 60 miles to the gallon.","cn":"每加仑油跑 60 英里的发动机"}},{"pos":"PREP 介词","cn":"伴随;随同","en":"You use to when indicating that two things happen at the same time. For example, if something is done to music, it is done at the same time as music is being played.","ex":{"en":"Romeo left the stage, to enthusiastic applause","cn":"罗密欧在热烈的掌声中离开了舞台。"}},{"pos":"CONVENTION 惯用语","cn":"不费事;很简单","en":"If you say 'There's nothing to it', 'There's not much to it', or 'That's all there is to it', you are emphasizing how simple you think something is.","ex":{"en":"Once they have tried growing orchids, they will see there is really nothing to it.","cn":"一旦他们试着种植兰花，就会发现那并不是什么难事。"}},{"pos":"ADV 副词","cn":"(门)关着，虚掩着","en":"If you push or shut a door to, you close it but may not shut it completely.","ex":{"en":"He slipped out, pulling the door to.","cn":"他溜了出去，虚掩上门。"}},{"pos":"to inf","cn":"(用于动词原形前构成不定式;不定式用于某些动词、名词、形容词以及 how，which, where 等词之后)。","en":"You use to before the base form of a verb to form the to-infinitive. You use the to-infinitive after certain verbs, nouns, and adjectives, and after words such as 'how', 'which', and 'where'.","ex":{"en":"The management wanted to know what I was doing there","cn":"管理层想知道我在那里做什么。"}},{"pos":"to inf","cn":"(用于动词原形前，表示动作的目的或意图)","en":"You use to before the base form of a verb to indicate the purpose or intention of an action. in order to→see: ;","ex":{"en":"...using the experience of big companies to help small businesses","cn":"利用大公司的经验帮助小企业"}},{"pos":"to inf","cn":"(用于动词原形前，表示对自己要说的话加以说明)","en":"You use to before the base form of a verb when you are commenting on a statement that you are making, for example when saying that you are being honest or brief, or that you are summing up or giving an example.","ex":{"en":"I'm disappointed, to be honest","cn":"说实话，我很失望。"}},{"pos":"to inf","cn":"(用于感叹句中的动词原形前，强调某一强烈情感)","en":"You use to before the base form of a verb in exclamations when you are emphasizing a very strong emotion, such as a desire or wish, or a regret or disappointment.","ex":{"en":"Oh, to think of his poor wife, standing there helpless…","cn":"噢！想想他可怜的妻子，无助地站在那里。"}},{"pos":"to inf","cn":"(用于动词原形前，表示某一动作之后的情形)","en":"You use to before the base form of a verb when indicating what situation follows a particular action.","ex":{"en":"He made his way to the kitchen to find Francis cooking…","cn":"他走到厨房，发现弗朗西斯正在做菜。"}},{"pos":"","cn":"(与 too, enough 连用)","en":"You use to with 'too' and 'enough' in expressions like too much to and old enough to . →see: ;"}]},"examples":[{"en":"a drop in profits from $105 million to around $75 million","cn":"利润从 1.05 亿元降到 7 500 万元左右"},{"en":"I reached the station only to find that my train had already left.","cn":"我到了车站，却发现我要搭乘的火车已经开走了。"}]},"total":{"media":{"uk":"media/uk/total__gb_1.mp3","us":"media/us/total__us_1.mp3"},"oxford":{"phon":"ˈtəʊtl","pos":"adjective","senses":[{"en":"being the amount or number after everyone or everything is counted or added together","cn":"总的；总计的；全体的；全部的","ex":{"en":"Their total cost was $18 000.","cn":"它们总共花了 18 000 美元。"}},{"en":"used when you are emphasizing something, to mean ‘to the greatest degree possible’","cn":"（用以强调）完全的，彻底的","ex":{"en":"The room was in total darkness.","cn":"房间里一片漆黑。"}},{"en":"the amount you get when you add several numbers or amounts together; the final number of people or things when they have all been counted","cn":"总数；总额；合计；总计","ex":{"en":"You got 47 points on the written examination and 18 on the oral, making a total of 65.","cn":"你笔试得了 47 分，口试得了 18 分，总分 65 分。"},"pos":"noun"},{"en":"to reach a particular total","cn":"总数达；共计","ex":{"en":"Imports totalled $1.5 billion last year.","cn":"去年的进口总额达 15 亿美元。"},"pos":"verb"},{"en":"to add up the numbers of something/somebody and get a total","cn":"把…加起来；计算…的总和","ex":{"en":"Each student's points were totalled and entered in a list.","cn":"每个学生的总分都已计算出来并列入表中。"},"pos":"verb"},{"en":"to damage a car very badly, so that it is not worth repairing it","cn":"彻底毁坏（汽车）","lab":"especially North American English, informal，，","ex":{"en":"She never forgave him for totaling her car.","cn":"她永远不能原谅他彻底毁坏了她的汽车。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总数;总额;合计","en":"A total is the number that you get when you add several numbers together or when you count how many things there are in a group.","ex":{"en":"The companies have a total of 1,776 employees.","cn":"这些公司总计有 1,776 名员工。"}},{"pos":"ADJ 形容词","cn":"总的;总计的;全部的","en":"The total number or cost of something is the number or cost that you get when you add together or count all the parts in it.","ex":{"en":"They said that the total number of cows dying from BSE would be twenty thousand…","cn":"他们说患疯牛病死亡的牛的总数将达 2 万头。"}},{"pos":"PHRASE 短语","cn":"总共;总计","en":"If there are a number of things in total, there are that number when you count or add them all together.","ex":{"en":"I was with my husband for eight years in total","cn":"我和丈夫在一起的时间总共有 8 年。"}},{"pos":"VERB 动词","cn":"总数达;共计","en":"If several numbers or things total a certain figure, that figure is the total of all the numbers or all the things.","ex":{"en":"The unit's exports will total $85 million this year","cn":"该部门今年的出口总额将达 8,500 万美元。"}},{"pos":"VERB 动词","cn":"计算…的总和;把…加起来","en":"When you total a set of numbers or objects, you add them all together.","ex":{"en":"They haven't totalled the exact figures.","cn":"他们还没有对确切数据进行总计。"}},{"pos":"ADJ 形容词","cn":"完全的;彻底的;绝对的","en":"You can use total to emphasize that something is as great in extent, degree, or amount as it possibly can be.","ex":{"en":"You were a total failure if you hadn't married by the time you were about twenty-three…","cn":"如果到了 23 岁左右还没结婚，你就是个彻底的失败者。"}}]},"examples":[{"en":"You got 47 points on the written examination and 18 on the oral, making a total of 65.","cn":"你笔试得了 47 分，口试得了 18 分，总分 65 分。"},{"en":"This brought the total number of accidents so far this year to 113.","cn":"这使得今年迄今为止发生事故的总数达到 113 起。"}]},"town":{"media":{"uk":"media/uk/town__gb_1.mp3","us":"media/us/town__us_1.mp3"},"oxford":{"phon":"taʊn","pos":"noun","senses":[{"en":"a place with many houses, shops, etc. where people live and work. It is larger than a village but smaller than a city.","cn":"镇；市镇；集镇","g":"[countable, uncountable]","ex":{"en":"The nearest town is ten miles away.","cn":"最近的集镇离这里有十英里远。"}},{"en":"the people who live in a particular town","cn":"（某一市镇的）居民，市民","g":"[singular]","ex":{"en":"The whole town is talking about it.","cn":"全镇的人都在议论这件事。"}},{"en":"the area of a town where most of the shops and businesses are","cn":"（城镇的）商业区","g":"[uncountable]","ex":{"en":"We are only five minutes from the centre of town.","cn":"我们距市中心仅五分钟路程。"}},{"en":"a particular town where somebody lives and works or one that has just been referred to","cn":"（生活、工作或刚提到的）城镇","g":"[uncountable]","lab":"especially North American English","ex":{"en":"I'll be in town next week if you want to meet.","cn":"如果你想见面的话，我下个星期在城里。"}},{"en":"life in towns or cities as opposed to life in the country","cn":"城市生活（与乡村生活相对）","g":"[singular, uncountable]","lab":"especially North American English","ex":{"en":"Pollution is just one of the disadvantages of living in the town.","cn":"污染只是生活在城里的不利条件之一。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"镇;市镇；城镇","en":"A town is a place with many streets and buildings, where people live and work. Towns are larger than villages and smaller than cities. Many places that are called towns in Britain would be called cities in the United States.","ex":{"en":"...Saturday night in the small town of Braintree, Essex","cn":"埃塞克斯郡布伦特里小镇的周六之夜"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自己居住的城镇","en":"You use town in order to refer to the town where you live.","ex":{"en":"He admits he doesn't even know when his brother is in town","cn":"他承认自己甚至不知道弟弟什么时候来了本市。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"市中心;(城镇的)商业中心；闹市区","en":"You use town in order to refer to the central area of a town where most of the shops and offices are.","ex":{"en":"I walked around town","cn":"我在市中心逛了逛。"}},{"pos":"N-SING 单数名词","cn":"(与农村相对的)城市，都会","en":"If you refer to the town, you are referring to town and city areas in general, as opposed to country areas.","ex":{"en":"More people are going to want to escape from the town into the country…","cn":"更多的人将会想要逃离城市到乡村去。"}},{"pos":"PHRASE 短语","cn":"满腔热情地干;拼命地干","en":"If you say that someone goes to town on something, you mean that they deal with it with a lot of enthusiasm or intensity.","ex":{"en":"We really went to town on it, turning it into a full, three-day show","cn":"我们下了真功夫，把它办成了一场内容丰富、为时三天的展览。"}},{"pos":"PHRASE 短语","cn":"社交忙人;花花公子/时髦女郎","en":"If you describe someone as a man about town or a woman about town, you mean that they are sophisticated, like to go out and spend money, and have a busy social life.","ex":{"en":"He was known as a tall, handsome man about town…","cn":"他以高大英俊的花花公子形象为人所知。"}},{"pos":"PHRASE 短语","cn":"(夜晚)在闹市区玩乐","en":"If you go out on the town or go for a night on the town, you enjoy yourself by going to a town centre in the evening and spending a long time there visiting several places of entertainment.","ex":{"en":"My idea of luxury used to be going out on the town and coming back in the early hours of the morning","cn":"我过去对奢侈的概念是夜晚在闹市通宵玩乐到清晨才回来。"}}]},"examples":[{"en":"We spent a month in the French town of Le Puy.","cn":"我们在一个叫勒皮的法国小镇里待了一个月。"},{"en":"I'll be in town next week if you want to meet.","cn":"如果你想见面的话，我下个星期在城里。"}]},"togetherness":{"media":{"uk":"media/uk/togetherness__gb_1.mp3","us":"media/us/togetherness__us_1.mp3"},"oxford":{"phon":"təˈɡeðənəs","pos":"noun","senses":[{"en":"the happy feeling you have when you are with people you like, especially family and friends","cn":"（尤指家庭或朋友的）和睦相处，亲密无间，团结友爱","ex":{"en":"By the end of the week, there was a tremendous feeling of togetherness in the group.","cn":"到一周结束时，团队成员之间洋溢着一种亲密无间的感情。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"亲密无间;友爱情谊","en":"Togetherness is a happy feeling of affection and closeness to other people, especially your friends and family.","ex":{"en":"Nothing can ever take the place of real love and family togetherness.","cn":"什么都不能取代真爱与家庭和睦。"}}]},"examples":[{"en":"the togetherness we felt at college","cn":"我们在大学里感到的团结友爱"}]},"tool":{"media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/hammer.jpg","media/ldoce/img/tool_box.jpg"],"uk":"media/uk/tool__gb_1.mp3","us":"media/us/tool__us_1.mp3"},"oxford":{"phon":"tuːl","pos":"noun","senses":[{"en":"an instrument such as a hammer, screwdriver, saw, etc. that you hold in your hand and use for making things, repairing things, etc.","cn":"工具","ex":{"en":"garden tools","cn":"园艺工具"}},{"en":"a thing that helps you to do your job or to achieve something","cn":"（有助于做工或完成某事的）用具，器具，手段，方法","ex":{"en":"research tools like questionnaires","cn":"问卷之类的研究手段"}},{"en":"a person who is used or controlled by another person or group","cn":"受人利用的人；工具","ex":{"en":"The prime minister was an unwitting tool of the president.","cn":"首相不知不觉被总统利用了。"}},{"en":"a penis","cn":"鸡巴；屌","lab":"taboo, slang，，"},{"en":"to drive around in a vehicle","cn":"驱车兜风；驾车到处跑","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工具;器具;用具","en":"A tool is any instrument or simple piece of equipment that you hold in your hands and use to do a particular kind of work. For example, spades, hammers, and knives are all tools.","ex":{"en":"I find the best tool for the purpose is a pair of shears.","cn":"我发现做这件事最得力的工具是一把大剪刀。"}},{"pos":"N-COUNT 可数名词","cn":"手段;方法","en":"You can refer to anything that you use for a particular purpose as a particular type of tool .","ex":{"en":"Writing is a good tool for discharging overwhelming feelings…","cn":"写作是宣泄强烈感情的好方法。"}},{"pos":"N-COUNT 可数名词","cn":"受人利用的人;工具;傀儡","en":"If you describe someone as a tool of a particular person, group, or system, you mean that they are controlled and used by that person, group, or system, especially to do unpleasant or dishonest things.","ex":{"en":"He became the tool of the security services.","cn":"他成了安全部门的工具。"}},{"pos":"PHRASE 短语","cn":"(因罢工或抗议而突然)停工，放下工具","en":"If you say that workers down tools, you mean that they stop working suddenly in order to strike or to make a protest of some kind."},{"pos":"PHRASE 短语","cn":"(技能、工具和设备等)从事某行当的工具","en":"The tools of your trade or the tools of the trade are the skills, instruments, and other equipment that you need in order to do your job properly.","ex":{"en":"They're here to learn the tools of their trade from their American colleagues","cn":"他们来这里向美国同事学习行业技术和技能。"}}]},"examples":[{"en":"Some of them carried the guns which were the tools of their trade (= the things they needed to do their job).","cn":"他们有些人携带着喷枪，那是干他们那一行的器具。"},{"en":"The factory is not tooled up to produce this type of engine.","cn":"这家工厂还没有装置生产这类发动机的设备。"}]},"toggle":{"oxford":{"phon":"ˈtɒɡl","pos":"noun","senses":[{"en":"a short piece of wood, plastic, etc. that is put through a loop of thread to fasten something, such as a coat or bag, instead of a button","cn":"（大衣或口袋等上木质或塑料的）栓扣钉，棒形纽扣，套索扣"},{"en":"a key on a computer that you press to change from one style or operation to another, and back again","cn":"转换键；切换键","lab":"computing"},{"en":"to press a key or set of keys on a computer keyboard in order to turn a feature on or off, or to move from one program, etc. to another","cn":"（两种状态之间）切换，转换","ex":{"en":"He toggled between the two windows.","cn":"他在两个窗口之间来回切换。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(木质或塑料的)棒形纽扣","en":"A toggle is a small piece of wood or plastic which is sewn to something such as a coat or bag, and which is pushed through a loop or hole to fasten it."}]},"media":{"img":["media/pic/fasteners_clothes_comp.jpg","media/thumb/toggle.jpg"],"uk":"media/uk/toggle__gb_1.mp3","us":"media/us/toggle__us_1.mp3"},"examples":[{"en":"This key toggles various views of the data.","cn":"按此键可切换数据的各种视图。"},{"en":"He toggled between the two windows.","cn":"他在两个窗口之间来回切换。"}]},"together":{"media":{"uk":"media/uk/together__gb_1.mp3","us":"media/us/together__us_1.mp3"},"oxford":{"phon":"təˈɡeðə(r)","pos":"adverb","senses":[{"en":"with or near to somebody/something else; with each other","cn":"在一起；共同","ex":{"en":"We grew up together.","cn":"我们是在一块儿长大的。"}},{"en":"so that two or more things touch or are joined to or combined with each other","cn":"以使接触（或相结合）；到一起","ex":{"en":"He rubbed his hands together in satisfaction.","cn":"他满意地擦搓着双手。"}},{"en":"in a close relationship, for example a marriage","cn":"关系密切；有婚姻关系","ex":{"en":"They split up after ten years together.","cn":"他们在一起生活了十年之后分手了。"}},{"en":"at the same time","cn":"同时；一起；一齐","lab":"informal","ex":{"en":"They both spoke together.","cn":"他们两人同时发言。"}},{"en":"in or into agreement","cn":"一致；协调","ex":{"en":"After the meeting the two sides in the dispute were no closer together.","cn":"会面之后，争论的双方立场差距依然如故。"}},{"en":"for hours, days, etc. without stopping","cn":"接连…地；连续…地；…不间断地","lab":"formal","ex":{"en":"She sat for hours together just staring into space.","cn":"她连续几个小时坐在那里怔怔地望着前面。"}},{"en":"well organized and confident","cn":"自信而妥实的","ex":{"en":"He's incredibly together for someone so young.","cn":"他这个人年纪轻轻，办事如此稳当，真是了不起。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"一起；共同","en":"If people do something together, they do it with each other.","ex":{"en":"We went on long bicycle rides together","cn":"我们一起骑自行车长途旅行。"}},{"pos":"ADV 副词","cn":"(接触、结合)到一起","en":"If things are joined together, they are joined with each other so that they touch or form one whole.","ex":{"en":"Mix the ingredients together thoroughly","cn":"把配料充分混合。"}},{"pos":"ADV 副词","cn":"(位置)在一起，紧挨地","en":"If things or people are situated together, they are in the same place and very near to each other.","ex":{"en":"The trees grew close together","cn":"树木密密地长在一起。"}},{"pos":"ADV 副词","cn":"(团结)在一起","en":"If a group of people are held or kept together, they are united with each other in some way.","ex":{"en":"He has done enough to pull the party together","cn":"他为使政党内部团结一致已经做得够多了。"}},{"pos":"ADJ 形容词","cn":"(两人)结婚的，有性关系(或恋爱关系)的","en":"If two people are together, they are married or having a sexual relationship with each other.","ex":{"en":"We were together for five years","cn":"我们共同生活了 5 年。"}},{"pos":"ADV 副词","cn":"同时;一齐","en":"If two things happen or are done together, they happen or are done at the same time.","ex":{"en":"Three horses crossed the finish line together","cn":"3 匹马同时越过终点线。"}},{"pos":"ADV 副词","cn":"合计地;总合地","en":"You use together when you are adding two or more amounts or things to each other in order to consider a total amount or effect.","ex":{"en":"The two main right-wing opposition parties together won 29.8 per cent…","cn":"两大右翼反对党合计赢得 29.8% 的选票。"}},{"pos":"PHR-RECIP 相互短语","cn":"相配;不可分割","en":"If you say that two things go together, or that one thing goes together with another, you mean that they go well with each other or cannot be separated from each other.","ex":{"en":"I can see that some colours go together and some don't","cn":"我看得出有些颜色很相配，有些就不行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的;精干的;清醒的","en":"If you describe someone as together, you admire them because they are very confident, organized, and know what they want.","ex":{"en":"She was very headstrong, and very together","cn":"她非常倔强，又非常精干。"}},{"pos":"PREP-PHRASE 短语介词","cn":"连同…一起;还有;加之","en":"You use together with to mention someone or something else that is also involved in an action or situation.","ex":{"en":"Every month we'll deliver the very best articles, together with the latest fashion and beauty news","cn":"每个月我们都登载最好的文章，还有最新的时尚美容资讯。"}},{"pos":"","cn":"","en":"to get your act together→see: ; to put your heads together→see: ; put together→see: ;"}]},"examples":[{"en":"Together with the Johnsons, there were 12 of us in the villa.","cn":"包括约翰逊一家在内，别墅里总共有我们 12 个人。"},{"en":"I sent my order, together with a cheque for £40.","cn":"我把订单连同一张 40 英镑的支票一起寄出去。"}]},"topping":{"media":{"uk":"media/uk/topping__gb_1.mp3","us":"media/us/topping__us_1.mp3"},"oxford":{"phon":"ˈtɒpɪŋ","pos":"noun","senses":[{"en":"a layer of food that you put on top of a dish, cake, etc. to add taste or to make it look nice","cn":"（菜肴、蛋糕等上的）浇汁，浇料，配料，佐料","ex":{"en":"baked vegetables with a cheese topping","cn":"烤蔬菜配奶酪"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(菜肴、糕点等上层的)浇头，装饰配料","en":"A topping is food, such as cream or cheese, that is poured or put on top of other food in order to decorate it or add to its flavour."}]},"examples":[{"en":"a pizza with extra toppings","cn":"顶上多加一层配料的比萨饼"}],"base":"top"},"tone":{"media":{"uk":"media/uk/tone__gb_1.mp3","us":"media/us/tone__us_1.mp3"},"oxford":{"phon":"təʊn","pos":"noun","senses":[{"en":"the quality of somebody’s voice, especially expressing a particular emotion","cn":"语气；口气；腔调；口吻","g":"[countable]","sc":"of voice","ex":{"en":"speaking in hushed/low/clipped/measured, etc. tones","cn":"以压低、低沉、短促、缓慢谨慎等的语调讲话"}},{"en":"the general character and attitude of something such as a piece of writing, or the atmosphere of an event","cn":"风格；特色；气氛；情调","g":"[singular]","sc":"character/atmosphere","ex":{"en":"The overall tone of the book is gently nostalgic.","cn":"这本书整体格调是温情的怀旧。"}},{"en":"the quality of a sound, especially the sound of a musical instrument or one produced by electronic equipment","cn":"（尤指乐器或电子音响设备的）音质，音色","g":"[countable]","sc":"of sound","ex":{"en":"the full rich tone of the trumpet","cn":"小号饱满嘹亮的音色"}},{"en":"a shade of a colour","cn":"色调；明暗；影调","g":"[countable]","sc":"colour","ex":{"en":"a carpet in warm tones of brown and orange","cn":"棕色和橘黄色的暖色调地毯"}},{"en":"how strong and tight your muscles or skin are","cn":"（肌肉）结实度，健壮度；（皮肤）紧致性","g":"[uncountable]","sc":"of muscles/skin","ex":{"en":"how to improve your muscle/skin tone","cn":"如何使肌肉结实／皮肤紧致"}},{"en":"a sound heard on a phone line","cn":"（打电话时听到的）声音信号","g":"[countable]","lab":"British English","sc":"on phone","ex":{"en":"the dialling tone","cn":"拨号音"}},{"en":"one of the five longer intervals in a musical scale, for example the interval between C and D or between E and F♯","cn":"全音","g":"[countable]","lab":"British English","sc":"in music"},{"en":"the pitch (= how high or low a sound is) of a syllable in speaking","cn":"（说话的）声调，音调","g":"[countable]","sc":"phonetics","ex":{"en":"a rising/falling tone","cn":"升调；降调"}},{"en":"a particular pitch pattern on a syllable in languages such as Chinese, that can be used to recognize the difference in meanings","cn":"（字的）声调；字调","sc":"phonetics"},{"en":"having the type of tone mentioned","cn":"有…音调的（或音质的、色调的）","sc":"-toned","ex":{"en":"a bright-toned soprano","cn":"声音嘹亮的女高音"}},{"en":"to make your muscles, skin, etc. tighter and stronger","cn":"使更健壮；使更结实；使更紧致","g":"[transitive]","sc":"muscles/skin","ex":{"en":"Massage will help to tone up loose skin under the chin.","cn":"按摩有助于使颏下松弛的皮肤紧起来。"},"pos":"verb"},{"en":"to match the colour of something","cn":"与…协调；与…相配","g":"[intransitive]","lab":"British English","sc":"colour","ex":{"en":"The beige of his jacket toned (in) with the cream shirt.","cn":"他那夹克的米黄色与乳白色的衬衫非常协调。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音质;音色;音调","en":"The tone of a sound is its particular quality.","ex":{"en":"Cross could hear him speaking in low tones to Sarah.","cn":"克罗斯听得到他对萨拉低声说话。"}},{"pos":"N-COUNT 可数名词","cn":"语气；口气；腔调","en":"Someone's tone is a quality in their voice which shows what they are feeling or thinking.","ex":{"en":"I still didn't like his tone of voice","cn":"我还是不喜欢他说话的语气。"}},{"pos":"N-SING 单数名词","cn":"(演讲、文章的)语气，调子，基调","en":"The tone of a speech or piece of writing is its style and the opinions or ideas expressed in it.","ex":{"en":"The spokesman said the tone of the letter was very friendly","cn":"发言人说信函的语气非常友好。"}},{"pos":"N-SING 单数名词","cn":"气氛;氛围;格调","en":"The tone of a place or an event is its general atmosphere.","ex":{"en":"The high tone of the occasion was assured by the presence of a dozen wealthy patrons…","cn":"十几位富有资助人的出席确保了仪式的高格调。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（身体的）强健状况；(尤指肌肉的)紧实度，结实度","en":"The tone of someone's body, especially their muscles, is its degree of firmness and strength.","ex":{"en":"...stretch exercises that aim to improve muscle tone","cn":"旨在提高肌肉结实度的伸展锻炼"}},{"pos":"VERB 动词","cn":"使结实；使强健","en":"Something that tones your body makes it firm and strong.","ex":{"en":"This movement lengthens your spine and tones the spinal nerves","cn":"这一动作舒展脊椎，使脊神经更加强健。"}},{"pos":"N-VAR 可变名词","cn":"色调;明暗","en":"A tone is one of the lighter, darker, or brighter shades of the same colour.","ex":{"en":"Each brick also varies slightly in tone, texture and size","cn":"每块砖在色调、质地与大小上也都略有不同。"}},{"pos":"VERB 动词","cn":"(与…)协调(或相配)","en":"If one thing tones with another, the two things look nice together because their colours are similar in quality or brightness.","ex":{"en":"Princess Margaret toned with her in a turquoise print dress.","cn":"玛格丽特公主那条青绿色的印花裙子与她很相配。"}},{"pos":"N-SING 单数名词","cn":"电话提示音","en":"A tone is one of the sounds that you hear when you are using a telephone, for example the sound that tells you that a number is engaged or busy, or no longer exists."},{"pos":"N-COUNT 可数名词","cn":"音;全音","en":"A tone is a difference in pitch between two musical notes equal to two semitones."},{"pos":"PHRASE 短语","cn":"降低格调","en":"If you say that something lowers the tone of a place or event, you mean that it is not appropriate and makes the place or event seem less respectable.","ex":{"en":"Councillors say plastic-framed windows lower the tone of the neighbourhood.","cn":"市政会委员说塑料框架的窗户让这个社区掉份儿了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"使(颜色)柔和；使(味道)变淡;调和","en":"If you tone down a colour or a flavour, you make it less bright or strong.","ex":{"en":"When Ken Hom wrote his first book for the BBC he was asked to tone down the spices and garlic in his recipes.","cn":"当肯·霍姆为英国广播公司写第一本书的时候，他被要求在菜谱里少用些香料和大蒜。"}},{"pos":"","cn":"","en":"相关词组：tone down tone in tone up"}]},"examples":[{"en":"There's no need to take that tone with me — it's not my fault we're late.","cn":"不必那样跟我拿腔拿调的。我们来晚了，可不是我的错。"},{"en":"She set the tone for the meeting with a firm statement of company policy.","cn":"她坚定地说明了公司的方针，为会议定下了调子。"}]},"toes":{"lemma":"toe","media":{"uk":"media/uk/to__gb_1.mp3","us":"media/us/to__us_1.mp3"}},"tomatoes":{"lemma":"tomato","media":{"img":["media/ldoce/img/tomatoes.jpg"]}},"tomato":{"oxford":{"phon":"təˈmɑːtəʊ","pos":"noun","senses":[{"en":"a soft fruit with a lot of juice and shiny red skin that is eaten as a vegetable either raw or cooked","cn":"番茄；西红柿","ex":{"en":"a bacon, lettuce, and tomato sandwich","cn":"熏肉生菜番茄三明治"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"番茄;西红柿","en":"Tomatoes are small, soft, red fruit that you can eat raw in salads or cooked as a vegetable."}]},"media":{"img":["media/pic/salad_vegetables_comp.jpg","media/thumb/tomato.jpg"],"uk":"media/uk/tomato__gb_1.mp3","us":"media/us/tomato__us_1.mp3"},"examples":[{"en":"a bacon, lettuce and tomato sandwich","cn":"熏肉生菜番茄三明治"},{"en":"tomato plants","cn":"番茄植株"}]},"touching":{"media":{"uk":"media/uk/touching__gb_1.mp3","us":"media/us/touching__us_1.mp3"},"oxford":{"phon":"ˈtʌtʃɪŋ","pos":"adjective","senses":[{"en":"causing feelings of sympathy; making you feel sad or emotional","cn":"令人同情的；感人的；动人的","ex":{"en":"It was a touching story that moved many of us to tears.","cn":"那是一个让我们许多人落泪的动人故事。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"动人的;感人的;令人同情的","en":"If something is touching, it causes feelings of sadness or sympathy.","ex":{"en":"Her story is the touching tale of a wife who stood by the husband she loved","cn":"她的经历是一个妻子坚定地支持她深爱着的丈夫的感人故事。"}}]},"examples":[{"en":"It was a touching story that moved many of us to tears.","cn":"那是一个让我们许多人落泪的动人故事。"},{"en":"a touching reunion of father and son","cn":"感人的父子团聚"}],"base":"touch"},"toast":{"oxford":{"phon":"təʊst","pos":"noun","senses":[{"en":"slices of bread that have been made brown and dry by heating them on both sides in a toaster or under a grill","cn":"烤面包片；吐司","g":"[uncountable]","ex":{"en":"cheese on toast","cn":"烤面包片加奶酪"}},{"en":"the act of a group of people wishing somebody happiness, success, etc. by drinking a glass of something at the same time","cn":"为…举杯敬酒；为…干杯","g":"[countable]","ex":{"en":"I'd like to propose a toast to the bride and groom.","cn":"我提议为新娘新郎干杯。"}},{"en":"a person who is praised by a lot of people in a particular place because of something that they have done well","cn":"（在某领域）广受赞誉的人，有口皆碑的人","g":"[singular]","ex":{"en":"The performance made her the toast of the festival.","cn":"她的演出使她在会演中备受推崇。"}},{"en":"to lift a glass of something in the air and drink it at the same time as other people in order to wish somebody/something success, happiness, etc.","cn":"干杯；祝酒；敬酒","g":"[transitive]","ex":{"en":"The happy couple were toasted in champagne.","cn":"人们举起香槟酒为这对幸福的伉俪干杯。"},"pos":"verb"},{"en":"to make something, especially bread, turn brown by heating it in a toaster or close to heat; to turn brown in this way","cn":"烤（尤指面包）；把…烤得焦黄","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"Toast the bread lightly on both sides.","cn":"把面包两面都微微烘烤一下。"},"pos":"verb"},{"en":"to warm a part of your body by placing it near a fire","cn":"烤火；取暖；使暖和","g":"[transitive]","ex":{"en":"He sat toasting his feet in front of the fire.","cn":"他坐在火前烤脚。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"吐司;烤面包片","en":"Toast is bread which has been cut into slices and made brown and crisp by cooking at a high temperature.","ex":{"en":"...a piece of toast.","cn":"一片吐司"}},{"pos":"VERB 动词","cn":"烤，烘(面包等)","en":"When you toast something such as bread, you cook it at a high temperature so that it becomes brown and crisp. →see usage note at:","ex":{"en":"Toast the bread lightly on both sides.","cn":"稍稍烘烤面包两面。"}},{"pos":"N-COUNT 可数名词","cn":"干杯;祝酒","en":"When you drink a toast to someone or something, you drink some wine or another alcoholic drink as a symbolic gesture, in order to show your appreciation of them or to wish them success.","ex":{"en":"Eleanor and I drank a toast to Miss Jacobs","cn":"我和埃莉诺向雅各布斯小姐敬酒。"}},{"pos":"VERB 动词","cn":"为…干杯;向…祝酒","en":"When you toast someone or something, you drink a toast to them.","ex":{"en":"Party officials and generals toasted his health","cn":"政党官员与军队将领为他的健康举杯祝酒。"}},{"pos":"N-SING 单数名词","cn":"深受敬慕的人;最受推崇的人","en":"If someone is the toast of a place, they are very popular and greatly admired there, because they have done something very successfully or well.","ex":{"en":"She was the toast of Paris.","cn":"她是巴黎最受推崇的人。"}},{"pos":"PHRASE 短语","cn":"完蛋，遭殃","en":"If someone is toast, you mean that they are certain to be defeated or destroyed.","ex":{"en":"They know how to control, restrict and, if need be, throttle access, important to newspapers and absolutely vital to radio and television. And if you don't play the game, you're toast.","cn":"他们知道怎样控制、限制信息获取途径，而且如果需要，还会将其完全阻断，而这些途径对报纸来说很重要，对广播、电视更是极其关键。如果你不遵守游戏规则，你就完蛋了。"}}]},"media":{"uk":"media/uk/toast__gb_1.mp3","us":"media/us/toast__us_1.mp3","img":["media/ldoce/img/toast.jpg"]},"examples":[{"en":"The happy couple were toasted in champagne.","cn":"人们举起香槟酒为这对幸福的伉俪干杯。"},{"en":"Place under a hot grill until the nuts have toasted.","cn":"把这些坚果放在高温烤架下面烤熟。"}]},"topography":{"media":{"uk":"media/uk/topography__gb_1.mp3","us":"media/us/topography__us_1.mp3"},"oxford":{"phon":"təˈpɒɡrəfi","pos":"noun","senses":[{"en":"the physical features of an area of land, especially the position of its rivers, mountains, etc.; the study of these features","cn":"地形；地貌；地势；地形学","ex":{"en":"a map showing the topography of the island","cn":"这个岛的地形图"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"地形学;地形测量学","en":"Topography is the study and description of the physical features of an area, for example its hills, valleys, or rivers, or the representation of these features on maps."},{"pos":"N-COUNT 可数名词","cn":"地形；地貌；地势","en":"The topography of a particular area is its physical shape, including its hills, valleys, and rivers.","ex":{"en":"The topography of the river's basin has changed significantly since the floods.","cn":"该河流域的地形自洪水以来发生了显著变化。"}}]},"examples":[{"en":"a map showing the topography of the island","cn":"这个岛的地形图"},{"en":"a topographical map/feature","cn":"地形图；地貌特征"}]},"toilet":{"media":{"uk":"media/uk/toilet__gb_1.mp3","us":"media/us/toilet__us_1.mp3","img":["media/ldoce/img/toilet.jpg"]},"oxford":{"phon":"ˈtɔɪlət","pos":"noun","senses":[{"en":"a large bowl attached to a pipe that you sit on or stand over when you get rid of waste matter from your body","cn":"坐便器；抽水马桶","g":"[countable]","lab":"British English","ex":{"en":"Have you flushed the toilet?","cn":"你冲厕所了吗？"}},{"en":"a room containing a toilet","cn":"厕所；卫生间；盥洗室","g":"[countable]","lab":"British English","ex":{"en":"Every flat has its own bathroom and toilet.","cn":"每套公寓都带有洗澡间和盥洗室。"}},{"en":"a room or small building containing several toilets, each in a separate smaller room","cn":"（有几个分隔坐便器的）厕所间，厕所","g":"[countable]","lab":"British English","ex":{"en":"public toilets","cn":"公共厕所"}},{"en":"the process of washing and dressing yourself, arranging your hair, etc.","cn":"梳洗；打扮","g":"[uncountable]","lab":"old-fashioned"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抽水马桶；便池","en":"A toilet is a large bowl with a seat, or a platform with a hole, which is connected to a water system and which you use when you want to get rid of urine or faeces from your body.","ex":{"en":"She made Tina flush the pills down the toilet.","cn":"她让蒂娜把药丸扔进马桶里冲走。"}},{"pos":"N-COUNT 可数名词","cn":"厕所;卫生间;洗手间","en":"A toilet is a room in a house or public building that contains a toilet.","ex":{"en":"Annette ran and locked herself in the toilet","cn":"安妮特跑向洗手间，把自己锁在里面。"}},{"pos":"PHRASE 短语","cn":"上厕所;上洗手间","en":"You can say that someone goes to the toilet to mean that they get rid of waste substances from their body, especially when you want to avoid using words that you think may offend people."}]},"examples":[{"en":"Every flat has its own bathroom and toilet.","cn":"每套公寓都带有洗澡间和盥洗室。"},{"en":"Do you need the toilet?","cn":"你需要用洗手间吗？"}]},"tolerate":{"oxford":{"phon":"ˈtɒləreɪt","pos":"verb","senses":[{"en":"to allow somebody to do something that you do not agree with or like","cn":"容许，允许（不同意或不喜欢的事物）","ex":{"en":"Their relationship was tolerated but not encouraged.","cn":"他们的关系得到了允许，但不宜鼓励。"}},{"en":"to accept somebody/something that is annoying, unpleasant, etc. without complaining","cn":"忍受；容忍；包容","ex":{"en":"There is a limit to what one person can tolerate.","cn":"一个人的容忍是有限度的。"}},{"en":"to be able to be affected by a drug, difficult conditions, etc. without being harmed","cn":"（对药物）有耐受性；能经受（困难条件）","ex":{"en":"She tolerated the chemotherapy well.","cn":"她对化疗的耐受力很强。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"容忍;容许;宽容","en":"If you tolerate a situation or person, you accept them although you do not particularly like them.","ex":{"en":"She can no longer tolerate the position that she's in","cn":"她再也受不了自己的处境了。"}},{"pos":"VERB 动词","cn":"忍受；忍耐","en":"If you can tolerate something unpleasant or painful, you are able to bear it.","ex":{"en":"The ability to tolerate pain varies from person to person.","cn":"对疼痛的忍受力因人而异。"}}]},"media":{"uk":"media/uk/tolerate__gb_1.mp3","us":"media/us/tolerate__us_1.mp3"},"examples":[{"en":"Their relationship was tolerated but not encouraged.","cn":"他们的关系得到了允许，但不宜鼓励。"},{"en":"I don't know how you tolerate that noise!","cn":"我不知道你怎么能忍受那样的噪音！"}]},"touched":{"media":{"uk":"media/uk/touched__gb_1.mp3","us":"media/us/touched__us_1.mp3"},"oxford":{"phon":"tʌtʃt","pos":"adjective","senses":[{"en":"feeling happy and grateful because of something kind that somebody has done; feeling emotional about something","cn":"感激；受感动；激动","ex":{"en":"She was touched by their warm welcome.","cn":"她对他们的热烈欢迎十分感动。"}},{"en":"slightly crazy","cn":"神经兮兮；疯疯癫癫","lab":"old-fashioned, informal，，"}]},"examples":[{"en":"She was touched by their warm welcome.","cn":"她对他们的热烈欢迎十分感动。"},{"en":"I was touched that he still remembered me.","cn":"他仍然记得我，使我十分感动。"}],"base":"touch"},"toot":{"oxford":{"phon":"tuːt","pos":"noun","senses":[{"en":"a short, high sound made by a car horn or a whistle","cn":"（喇叭、哨子等发出的）嘟嘟声","ex":{"en":"She gave a sharp toot on her horn.","cn":"她高声按响了喇叭。"}},{"en":"when a car horn toots or you toot it, it makes a short, high sound","cn":"（使汽车喇叭）发出短促尖锐的声音，发出嘟嘟声","ex":{"en":"the sound of horns tooting","cn":"鸣喇叭的声音"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(汽车喇叭)发出嘟嘟声","en":"If someone toots their car horn or if a car horn toots, it produces a short sound or series of sounds.","ex":{"en":"People set off fireworks and tooted their car horns","cn":"人们点燃烟花，按响汽车喇叭。"}}]},"media":{"uk":"media/uk/toot__gb_1.mp3","us":"media/us/toot__us_1.mp3"},"examples":[{"en":"Toot your horn to let them know we're here.","cn":"按按喇叭，告诉他们我们到了。"},{"en":"She gave a sharp toot on her horn.","cn":"她高声按响了喇叭。"}]},"tortoise":{"oxford":{"phon":"ˈtɔːtəs","pos":"noun","senses":[{"en":"a reptile with a hard round shell, that lives on land and moves very slowly. It can pull its head and legs into its shell.","cn":"陆龟；龟"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陆龟;(乌)龟","en":"A tortoise is a slow-moving animal with a shell into which it can pull its head and legs for protection."}]},"media":{"img":["media/ldoce/img/tortoise.jpg","media/pic/reptiles_comp.jpg"],"uk":"media/uk/tortoise__gb_1.mp3","us":"media/us/tortoise__us_1.mp3"}},"top":{"media":{"uk":"media/uk/top__gb_1.mp3","us":"media/us/top__us_1.mp3"},"oxford":{"phon":"tɒp","pos":"noun","senses":[{"en":"the highest part or point of something","cn":"顶；顶部；顶端","g":"[countable]","lab":"British English","sc":"highest point","ex":{"en":"She was standing at the top of the stairs.","cn":"她站在楼梯的顶端。"}},{"en":"the upper flat surface of something","cn":"表面；上面","g":"[countable]","sc":"upper surface","ex":{"en":"Can you polish the top of the table?","cn":"请把桌面擦亮好吗？"}},{"en":"a piece of clothing worn on the upper part of the body","cn":"上衣","g":"[countable]","sc":"clothing","ex":{"en":"I need a top to go with this skirt.","cn":"我需要一件上衣来配这条裙子。"}},{"en":"a thing that you put on the end of something to close it","cn":"帽；盖；塞","g":"[countable]","sc":"of pen/bottle","ex":{"en":"Where's the top of this pen?","cn":"这支笔的笔帽在哪儿？"}},{"en":"the highest or most important rank or position","cn":"最高的级别；最重要的职位","g":"[singular]","sc":"highest rank","ex":{"en":"They finished the season at the top of the league.","cn":"他们打完这个赛季之后积分高居联赛的榜首。"}},{"en":"the end of a street, table, etc. that is furthest away from you or from where you usually come to it","cn":"尽头；远端","g":"[singular]","sc":"furthest point","ex":{"en":"I'll meet you at the top of Thorpe Street.","cn":"我会和你在索普大街的尽头碰面。"}},{"en":"the leaves of a plant that is grown mainly for its root","cn":"（根菜作物的）茎叶","g":"[countable, usually plural]","sc":"leaves of plant","ex":{"en":"Remove the green tops from the carrots.","cn":"去掉胡萝卜的绿叶。"}},{"en":"used after an amount of money, time, etc. to show that it is the highest, longest, etc. possible","cn":"（用于款额等后）最高，至多；（用于时间等后）最长，最久","g":"[plural]","lab":"informal","sc":"amount of money/time","ex":{"en":"It couldn't have cost more than £50, tops.","cn":"这东西的价格最高不会超过 50 英镑。"}},{"en":"a person or thing of the best quality","cn":"最优秀的人；最好的东西；精华","g":"[plural]","lab":"old-fashioned, informal，，","sc":"best","ex":{"en":"Among sports superstars she’s (the) tops.","cn":"她在超级体育明星中独占鳌头。"}},{"en":"a child’s toy that turns round on a point when it is moved very quickly by hand or by a string","cn":"陀螺","g":"[countable]","sc":"toy","ex":{"en":"She was so confused—her mind was spinning like a top.","cn":"她如坠五里雾中，被搞得晕头转向。"}},{"en":"highest in position","cn":"（位置）最高的","ex":{"en":"He lives on the top floor.","cn":"他住在顶层。"},"pos":"adjective"},{"en":"highest in rank, degree or importance","cn":"（级别、程度或重要性）最高的","ex":{"en":"He's one of the top players in the country.","cn":"他是国内最优秀的运动员之一。"},"pos":"adjective"},{"en":"very good","cn":"很好的；极棒的；顶呱呱的","lab":"British English, informal，，","ex":{"en":"He's a top bloke.","cn":"他是个大好人。"},"pos":"adjective"},{"en":"to be higher than a particular amount","cn":"高于，超过（某一数量）","sc":"be more","ex":{"en":"Worldwide sales look set to top $1 billion.","cn":"全球销售额看来很可能要超过 10 亿美元。"},"pos":"verb"},{"en":"to be in the highest position on a list because you are the most successful, important, etc.","cn":"居…之首；为…之冠","sc":"be the best","ex":{"en":"The band topped the charts for five weeks with their first single.","cn":"这支乐队的第一张单曲唱片有五个星期高居最畅销流行音乐唱片榜榜首。"},"pos":"verb"},{"en":"to put something on the top of something else","cn":"把（某物）放在…的上面","g":"[usually passive]","sc":"put on top","ex":{"en":"The chapel was topped by a dome of white marble.","cn":"小教堂顶端是白色大理石穹顶。"},"pos":"verb"},{"en":"to say or do something that is better, funnier, more impressive, etc. than something that somebody else has said or done in the past","cn":"胜过，优于，压倒（前人所做）","sc":"say/do something better","ex":{"en":"I'm afraid the other company has topped your offer (= offered more money).","cn":"很抱歉，另一家公司出价比你们高。"},"pos":"verb"},{"en":"to kill yourself deliberately","cn":"自杀","lab":"British English, informal，，","sc":"kill yourself","pos":"verb"},{"en":"to reach the highest point of a hill, etc.","cn":"到达山顶；达到顶端","lab":"literary","sc":"climb hill","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顶;顶端;顶部","en":"The top of something is its highest point or part.","ex":{"en":"I waited at the top of the stairs.","cn":"我在楼梯顶端等着。"}},{"pos":"ADJ 形容词","cn":"最高的;最上面的;最上层的","en":"The top thing or layer in a series of things or layers is the highest one.","ex":{"en":"I can't reach the top shelf","cn":"我够不着最上面的架子。"}},{"pos":"N-COUNT 可数名词","cn":"(瓶、罐、管等的)盖，帽，塞","en":"The top of something such as a bottle, jar, or tube is a cap, lid, or other device that fits or screws onto one end of it.","ex":{"en":"...the plastic tops from aerosol containers.","cn":"喷雾剂容器的塑料盖子"}},{"pos":"N-SING 单数名词","cn":"另一端;另一头","en":"The top of a street, garden, bed, or table is the end of it that is farthest away from where you usually enter it or from where you are.","ex":{"en":"...a little shop at the top of the street","cn":"在街道那头的小店"}},{"pos":"N-COUNT 可数名词","cn":"上衣","en":"A top is a piece of clothing that you wear on the upper half of your body, for example a blouse or shirt.","ex":{"en":"Look at my new top.","cn":"看看我的新上衣。"}},{"pos":"ADJ 形容词","cn":"最高(级别或量度)的","en":"You can use top to indicate that something or someone is at the highest level of a scale or measurement.","ex":{"en":"The vehicles have a top speed of 80 kilometres per hour.","cn":"这些车辆最高时速为 80 公里。"}},{"pos":"ADJ 形容词","cn":"最优良的","en":"You can use top to say that you think something is excellent.","ex":{"en":"For $50, the guests got three courses of top nosh, fizz, wine, and beer.","cn":"花 50 美元，客人们就尝到了三道美味菜肴，还有汽水、葡萄酒和啤酒。"}},{"pos":"N-SING 单数名词","cn":"最高层;最高地位(或职位)","en":"The top of an organization or career structure is the highest level in it.","ex":{"en":"We started from the bottom and we had to work our way up to the top.","cn":"我们从最底层开始，是一步一步奋斗到最高层的。"}},{"pos":"ADJ 形容词","cn":"最重要的;最著名的","en":"You can use top to describe the most important or famous people or things in a particular area of work or activity.","ex":{"en":"So you want to be a top model…","cn":"这么说，你想成为超级名模喽。"}},{"pos":"N-SING 单数名词","cn":"（排名）首位;（位居）第一","en":"If someone is at the top of a table or league or is the top of the table or league, their performance is better than that of all the other people involved.","ex":{"en":"The United States will be at the top of the medal table","cn":"美国将在奖牌榜上位列第一。"}},{"pos":"ADJ 形容词","cn":"最要紧的;最优先的","en":"You can use top to indicate that something is the first thing you are going to do, because you consider it to be the most important.","ex":{"en":"Cleaning up the water supply is their top priority","cn":"清洁供水系统是他们的当务之急。"}},{"pos":"ADJ 形容词","cn":"次数最多的","en":"You can use top to indicate that someone does a particular thing more times than anyone else or that something is chosen more times than anything else.","ex":{"en":"He was Italy's top scorer during the World Cup matches","cn":"他是世界杯比赛期间意大利队进球最多的球员。"}},{"pos":"VERB 动词","cn":"为…之首;居…之冠","en":"To top a list means to be mentioned or chosen more times than anyone or anything else.","ex":{"en":"It was the first time a Japanese manufacturer had topped the list for imported vehicles","cn":"这是日本制造商初次占据进口车排行的首位。"}},{"pos":"VERB 动词","cn":"高过；超过；多于","en":"If something tops a particular amount, it is larger than that amount.","ex":{"en":"Imports topped £10 billion last month","cn":"上个月进口总额超过了 100 亿英镑。"}},{"pos":"VERB 动词","cn":"覆盖;放在…的上面","en":"If something is topped with something, it has that thing as its highest part.","ex":{"en":"The holiest of their chapels are topped with gilded roofs","cn":"他们最神圣的教堂屋顶镀了金。"}},{"pos":"VERB 动词","cn":"胜过;压倒","en":"If you top a story, remark, or action, you follow it with a better or more impressive one.","ex":{"en":"How are you going to top that?","cn":"你怎样超过那个？"}},{"pos":"ADV 副词","cn":"至多;最多","en":"You can use tops after mentioning a quantity, to say that it is the maximum possible.","ex":{"en":"The publisher expected the book to sell 1,500 copies, tops","cn":"出版商预计该书至多能卖出 1,500 本。"}},{"pos":"PHRASE 短语","cn":"绝好;最出色;无可匹敌","en":"If you say that something is tops or is the tops, you mean that it is better or more successful than anything else.","ex":{"en":"Majorca and Ibiza are tops for holiday bargain-hunters in June…","cn":"对于实惠型度假者来说，马略卡岛与伊维萨岛是 6 月份的绝好选择。"}},{"pos":"PHRASE 短语","cn":"大发脾气;勃然大怒","en":"If someone blows their top, they become very angry about something.","ex":{"en":"He blew his top after airport officials refused to let him on a plane.","cn":"机场工作人员拒绝让他登机之后，他勃然大怒。"}},{"pos":"PHRASE 短语","cn":"出人头地;拔得头筹;占得上风","en":"If a person, organization, or country comes out on top, they are more successful than the others that they have been competing with.","ex":{"en":"The only way to come out on top is to adopt a different approach.","cn":"脱颖而出的唯一途径就是采用一种不同的方法。"}},{"pos":"PHRASE 短语","cn":"最高价格","en":"If someone pays top dollar for something, they pay the highest possible price for it.","ex":{"en":"People will always pay top dollar for something exclusive.","cn":"人们总是会为绝无仅有的东西付出高价。"}},{"pos":"PHRASE 短语","cn":"从上到下;彻底地","en":"If you say that you clean, tidy, or examine something from top to bottom, you are emphasizing that you do it completely and thoroughly.","ex":{"en":"She would clean the house from top to bottom.","cn":"她会把房子彻底打扫一下。"}},{"pos":"PHRASE 短语","cn":"从头到脚;全身;完全","en":"You can use from top to toe to emphasize that the whole of someone's body is covered or dressed in a particular thing or type of clothing.","ex":{"en":"They were sensibly dressed from top to toe in rain gear.","cn":"他们从头到脚都用雨具捂得严严实实，非常明智。"}},{"pos":"PHRASE 短语","cn":"使愁苦；使沮丧","en":"When something gets on top of you, it makes you feel unhappy or depressed because it is very difficult or worrying, or because it involves more work than you can manage.","ex":{"en":"Things have been getting on top of me lately.","cn":"最近事情太多，压得我透不过气来。"}},{"pos":"PHRASE 短语","cn":"不加思索地;来不及思索地","en":"If you say something off the top of your head, you say it without thinking about it much before you speak, especially because you do not have enough time.","ex":{"en":"It was the best I could think of off the top of my head.","cn":"这是我一时所能想到的最好的办法。"}},{"pos":"PHRASE 短语","cn":"在上面;在顶上","en":"If one thing is on top of another, it is placed over it or on its highest part.","ex":{"en":"...the vacuum flask that was resting on top of the stove.","cn":"放在炉子上的保温瓶"}},{"pos":"PHRASE 短语","cn":"另外;加之;除…之外(还)","en":"You can use on top or on top of to indicate that a particular problem exists in addition to a number of other problems.","ex":{"en":"A stepfamily faces all the problems that a normal family has, with a set of additional problems on top…","cn":"再婚家庭会面临正常家庭的所有问题，外加一堆额外难题。"}},{"pos":"PHRASE 短语","cn":"处于最高职位","en":"You say that someone is on top when they have reached the most important position in an organization or business.","ex":{"en":"How does he stay on top, 17 years after becoming foreign minister?","cn":"他是怎样在成为外交大臣以后的17年间保住最高职位的？"}},{"pos":"PHRASE 短语","cn":"完全控制;完全掌握","en":"If you are on top of or get on top of something that you are doing, you are dealing with it successfully.","ex":{"en":"...the government's inability to get on top of the situation.","cn":"政府无力掌控局势"}},{"pos":"PHRASE 短语","cn":"非常幸福;心满意足","en":"If you say that you feel on top of the world, you are emphasizing that you feel extremely happy and healthy.","ex":{"en":"Two months before she gave birth to Jason she left work feeling on top of the world.","cn":"生贾森前的两个月，她辞工回家，感觉无比幸福。"}},{"pos":"PHRASE 短语","cn":"盖上","en":"If one thing is over the top of another, it is placed over it so that it is completely covering it.","ex":{"en":"I have overcome this problem by placing a sheet of polythene over the top of the container","cn":"我在容器上盖了一片聚乙烯塑料薄膜，解决了这个问题。"}},{"pos":"PHRASE 短语","cn":"夸张的;言过其实的","en":"You describe something as over the top when you think that it is exaggerated, and therefore unacceptable.","ex":{"en":"The special effects are a bit over the top but I enjoyed it.","cn":"特效有点夸张，但是我喜欢。"}},{"pos":"PHRASE 短语","cn":"除去…的两端","en":"If you top and tail fruit or vegetables such as French beans, you cut off the tops and the bottoms of them when you are preparing them to be eaten."},{"pos":"PHRASE 短语","cn":"(某行业中的)最高地位;事业的最高峰","en":"If you say that someone is at the top of the tree, you mean that they have reached the highest level in their career or profession.","ex":{"en":"He sees himself going right to the top of the tree.","cn":"他预见自己在同行中将无人可及。"}},{"pos":"PHRASE 短语","cn":"声嘶力竭地;极大声地","en":"If you say something at the top of your voice, you say it very loudly.","ex":{"en":"'Stephen!' shouted Marcia at the top of her voice.","cn":"“斯蒂芬！”马西娅放声大喊。"}},{"pos":"","cn":"","en":"at the top of the heap→see: ;"},{"pos":"","cn":"","en":"相关词组：top off top up"}]},"examples":[{"en":"The band topped the charts for five weeks with their first single.","cn":"这支乐队的第一张单曲唱片有五个星期高居最畅销流行音乐唱片榜首。"},{"en":"Look, here's 30 dollars, and I'll buy you lunch on top.","cn":"瞧，这是给你的 30 块钱，另外我还要给你买午餐。"}]},"toastmasters":{"lemma":"toastmaster"},"tommy":{"media":{"uk":"media/uk/tommy__gb_1.mp3","us":"media/us/tommy__us_1.mp3"},"oxford":{"phon":"ˈtɒmi","pos":"noun","senses":[{"en":"a first name for boys, short for Thomas","cn":"汤米（男子名，Thomas缩写）"},{"en":"a British soldier","cn":"英国兵","lab":"old use, informal，，"},{"en":"a rock opera (= a story told through a series of rock music songs), written by Pete Townsend of the group The Who and originally recorded and performed by the group in 1969. It tells the story of a boy called Tommy who cannot hear, speak or see but who becomes very good at the game of pinball. It was made into a film (1974) directed by Ken Russell, and later into a stage show.","cn":"汤米：摇滚歌剧（通过一系列摇滚音乐讲述的故事），由The Who乐队的Pete Townsend撰写，最初是由该乐队在1969年录制和表演的。它讲述了一个叫Tommy的男孩的故事，听，说或看，但是谁在弹球游戏中变得非常出色。它被肯·罗素（Ken Russell）执导为电影（1974年），随后又进入了舞台表演。"}]}},"tom":{"media":{"uk":"media/uk/tom__gb_1.mp3","us":"media/us/tom__us_1.mp3"},"oxford":{"phon":"tɒm","pos":"noun","senses":[{"en":"a male cat","cn":"公猫；雄猫"},{"en":"a first name for boys, short for Thomas","cn":"汤姆（男子名，Thomas缩写）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雄猫","en":"A tom is a male cat."}]},"examples":[{"en":"We don't want any Tom, Dick or Harry using the club bar.","cn":"我们不想随便让什么人都来使用会所的酒吧。"}]},"tooth":{"media":{"uk":"media/uk/tooth__gb_1.mp3","us":"media/us/tooth__us_1.mp3"},"oxford":{"phon":"tuːθ","pos":"noun","senses":[{"en":"any of the hard white structures in the mouth used for biting food","cn":"牙；齿","lab":"informal","ex":{"en":"I've just had a tooth out at the dentist's.","cn":"我刚在牙科诊所拔了一颗牙。"}},{"en":"a narrow, pointed part that sticks out of an object","cn":"齿状部分；齿","ex":{"en":"the teeth on a saw","cn":"锯齿"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牙;齿","en":"Your teeth are the hard white objects in your mouth, which you use for biting and chewing.","ex":{"en":"She had very pretty straight teeth","cn":"她有一口漂亮整齐的牙齿。"}},{"pos":"N-PLURAL 复数名词","cn":"齿状物;(梳子、锯、齿轮、拉链等的)齿","en":"The teeth of something such as a comb, saw, cog, or zip are the parts that stick out in a row on its edge.","ex":{"en":"The front cog has 44 teeth.","cn":"前齿轮有 44 个齿。"}},{"pos":"N-PLURAL 复数名词","cn":"(官方组织、法律等的)威力，效力","en":"If you say that something such as an official group or a law has teeth, you mean that it has power and is able to be effective.","ex":{"en":"The opposition argues that the new council will be unconstitutional and without teeth","cn":"反对派争辩说新委员会不但违反宪法，而且没有效力。"}},{"pos":"PHRASE 短语","cn":"全副武装;武装到牙齿","en":"Someone who is armed to the teeth is armed with a lot of weapons or with very effective weapons.","ex":{"en":"Both sides were armed to the teeth.","cn":"双方都全副武装。"}},{"pos":"PHRASE 短语","cn":"获得初步经验(或训练);起步","en":"If you say that someone cut their teeth doing a particular thing, at a particular time, or in a particular place, you mean that that is how, when, or where they began their career and learned some of their skills.","ex":{"en":"...director John Glen, who cut his teeth on Bond movies","cn":"从邦德电影开始初试牛刀的导演约翰·格伦"}},{"pos":"PHRASE 短语","cn":"使人感到极其不舒服(或恼怒)","en":"If you say that something sets your teeth on edge, you mean that you find it extremely unpleasant or irritating.","ex":{"en":"Their voices set your teeth on edge.","cn":"他们的声音让你浑身不舒服。"}},{"pos":"PHRASE 短语","cn":"奋力争取/竭尽全力阻止","en":"If you fight tooth and nail to do something, you do everything you can in order to achieve it. If you fight something tooth and nail, you do everything you can in order to prevent it.","ex":{"en":"He fought tooth and nail to keep his job","cn":"他竭尽全力保住自己的工作。"}},{"pos":"PHRASE 短语","cn":"潜心专注于;全力投入","en":"If you describe a task or activity as something you can get your teeth into, you mean that you like it because it is interesting, complex, and makes you think hard.","ex":{"en":"This role gave her something to get her teeth into","cn":"这一角色让她全情投入其中。"}},{"pos":"PHRASE 短语","cn":"直对;顶着;不顾","en":"If you do something in the teeth of a difficulty or danger, you do it in spite of the difficulty or danger.","ex":{"en":"I was battling my way along the promenade in the teeth of a force ten gale","cn":"我不顾十级大风沿着步行街挣扎前行。"}},{"pos":"PHRASE 短语","cn":"满口谎话;睁着眼说瞎话","en":"If you say that someone is lying through their teeth, you are emphasizing that they are telling lies."},{"pos":"PHRASE 短语","cn":"年迈的;年老的","en":"If you describe someone as long in the tooth, you are saying unkindly or humorously that they are old or getting old.","ex":{"en":"Aren't I a bit long in the tooth to start being an undergraduate?","cn":"我现在才去读大学本科不是有点太老了吗？"}},{"pos":"PHRASE 短语","cn":"爱吃甜食","en":"If you have a sweet tooth, you like sweet food very much.","ex":{"en":"Add more honey if you have a sweet tooth.","cn":"如果你喜欢吃甜的就多加点蜂蜜。"}},{"pos":"","cn":"","en":"to get the bit between your teeth→see: ; to give one's eye teeth for something→see: ; to gnash one's teeth→see: ; to grit your teeth→see: ; a kick in the teeth→see: ; by the skin of your teeth→see: ;"}]},"examples":[{"en":"The new policy was adopted in the teeth of fierce criticism.","cn":"新政策尽管受到强烈的批评，但还是被采用了。"},{"en":"Choose an essay topic that you can really get your teeth into.","cn":"选择一个你可以真正悉心钻研的论文题目。"}]},"tobacco":{"oxford":{"phon":"təˈbækəʊ","pos":"noun","senses":[{"en":"the dried leaves of the tobacco plant that are used for making cigarettes, smoking in a pipe, etc.","cn":"烟叶；烟草","ex":{"en":"tobacco smoke","cn":"抽烟时冒出的烟"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"烟叶;烟草(制品)","en":"Tobacco is dried leaves which people smoke in pipes, cigars, and cigarettes. You can also refer to pipes, cigars, and cigarettes as a whole as tobacco .","ex":{"en":"Try to do without tobacco and alcohol","cn":"尽量不要抽烟喝酒。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"烟草植株","en":"Tobacco is the plant from which tobacco is obtained."}]},"media":{"uk":"media/uk/tobacco__gb_1.mp3","us":"media/us/tobacco__us_1.mp3"},"examples":[{"en":"The government imposed a ban on tobacco advertising (= the advertising of cigarettes and all other forms of tobacco ).","cn":"政府禁止做烟草广告。"}]},"toy":{"media":{"img":["media/pic/toys_comp.jpg","media/thumb/teddybear.jpg"],"uk":"media/uk/toy__gb_1.mp3","us":"media/us/toy__us_1.mp3"},"oxford":{"phon":"tɔɪ","pos":"noun","senses":[{"en":"an object for children to play with","cn":"玩具","ex":{"en":"cuddly/stuffed toys","cn":"毛绒／布绒玩具"}},{"en":"an object that you have for fun or pleasure rather than for a serious purpose","cn":"玩物；玩意儿","ex":{"en":"executive toys","cn":"办公桌摆件"}},{"en":"made as a copy of a particular thing and used for playing with","cn":"玩具的；作玩具的","ex":{"en":"a toy car","cn":"玩具汽车"},"pos":"adjective"},{"en":"of a very small type","cn":"个头很小的；小体型的","ex":{"en":"a toy poodle","cn":"小鬈毛狗"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"玩具","en":"A toy is an object that children play with, for example a doll or a model car.","ex":{"en":"He was really too old for children's toys.","cn":"他已经长大了，实在不再适合玩儿童玩具了。"}},{"pos":"N-COUNT 可数名词","cn":"消遣物;小玩意儿","en":"You can refer to objects that adults use for fun rather than for a serious purpose as toys .","ex":{"en":"Computers have become household toys.","cn":"计算机已成了家庭的消遣玩意儿。"}},{"pos":"","cn":"","en":"相关词组：toy with"}]},"examples":[{"en":"She hardly ate a thing, just toyed with a piece of cheese on her plate.","cn":"她几乎没吃一点东西，只是拨弄着碟子里的一块奶酪。"},{"en":"His latest toy is the electric drill he bought last week.","cn":"他的新玩意儿是他上星期买的电钻。"}]},"toilets":{"lemma":"toilet","media":{"uk":"media/uk/toilet__gb_1.mp3","us":"media/us/toilet__us_1.mp3"}},"toil":{"media":{"uk":"media/uk/toil__gb_1.mp3","us":"media/us/toil__us_1.mp3"},"oxford":{"phon":"tɔɪl","pos":"verb","senses":[{"en":"to work very hard and/or for a long time, usually doing hard physical work","cn":"（长时间）苦干，辛勤劳作","g":"[intransitive]","ex":{"en":"Hundreds of men toiled for years at building the pyramid.","cn":"建这座金字塔，数百人苦干了多年。"}},{"en":"to move slowly and with difficulty","cn":"艰难缓慢地移动；跋涉","g":"[intransitive]","ex":{"en":"They toiled up the hill in the blazing sun.","cn":"他们冒着炎炎烈日艰难地一步一步爬上山冈。"}},{"en":"hard, unpleasant work that makes you very tired","cn":"苦工；劳累的工作","ex":{"en":"a life of hardship and toil","cn":"艰难劳苦的一生"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"苦干;辛勤劳动","en":"When people toil, they work very hard doing unpleasant or tiring tasks.","ex":{"en":"People who toiled in dim, dank factories were too exhausted to enjoy their family life","cn":"在昏暗潮湿的工厂辛苦劳作的人们累得无力再去享受家庭生活。"}},{"pos":"VERB 动词","cn":"(通常指因疲倦而)费劲地行走，艰难地行动","en":"If you toil somewhere, you move there slowly and with difficulty, usually because you are very tired.","ex":{"en":"Arnold had his head down, gasping as he toiled up the hill.","cn":"阿诺德垂着头，一边费劲地往山上爬一边气喘吁吁。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"苦工;苦活","en":"Toil is unpleasant work that is very tiring physically."}]},"examples":[{"en":"They toiled up the hill in the blazing sun.","cn":"他们冒着炎炎烈日艰难地一步一步爬上山冈。"},{"en":"a life of hardship and toil","cn":"艰难劳苦的一生"}]},"touch":{"media":{"uk":"media/uk/touch__gb_1.mp3","us":"media/us/touch__us_1.mp3"},"oxford":{"phon":"tʌtʃ","pos":"verb","senses":[{"en":"to put your hand or another part of your body onto somebody/something","cn":"触摸；碰","g":"[transitive]","lab":"figurative","sc":"with hand/part of body","ex":{"en":"Don't touch that plate—it's hot!","cn":"别碰那个盘子，烫手！"}},{"en":"to be or come so close together that there is no space between","cn":"接触；触及","g":"[intransitive, transitive]","sc":"no space between","ex":{"en":"Make sure the wires don't touch.","cn":"一定不要让金属线搭在一起。"}},{"en":"to move something, especially in such a way that you damage it; to hit or harm somebody","cn":"移动；碰到；打（人）；使受伤","g":"[transitive]","sc":"move something/hit somebody","ex":{"en":"I told you not to touch my things.","cn":"我告诉过你不要动我的东西。"}},{"en":"to make somebody feel upset or emotional","cn":"感动；触动；感染","g":"[transitive]","sc":"affect somebody/something","ex":{"en":"Her story touched us all deeply.","cn":"她的故事使我们大家深受感动。"}},{"en":"to affect somebody/something","cn":"影响","g":"[transitive]","lab":"old-fashioned or formal","sc":"affect somebody/something","ex":{"en":"These are issues that touch us all.","cn":"这些问题与我们大家都有关系。"}},{"en":"to eat, drink or use something","cn":"吃；喝；使用","g":"[transitive]","sc":"eat/drink/use","ex":{"en":"You've hardly touched your food.","cn":"你没怎么吃东西啊。"}},{"en":"to be as good as somebody in skill, quality, etc.","cn":"与…媲美；比得上；抵得过","g":"[transitive]","sc":"equal somebody","ex":{"en":"No one can touch him when it comes to interior design.","cn":"在室内设计方面，没有人能比得上他。"}},{"en":"to reach a particular level, etc.","cn":"达到（某一水平等）","g":"[transitive]","sc":"reach level","ex":{"en":"The speedometer was touching 90.","cn":"速度表显示时速达 90 英里。"}},{"en":"to become connected with or work with a situation or person","cn":"与…有关；从事；与…共事","g":"[transitive]","sc":"be involved with","ex":{"en":"Everything she touches turns to disaster.","cn":"什么事她一插手就会糟糕。"}},{"en":"to be seen on somebody’s face for a short time","cn":"（在脸上）闪现，掠过","g":"[transitive]","sc":"of smile","ex":{"en":"A smile touched the corners of his mouth.","cn":"他的嘴角闪现出一丝笑意。"}},{"en":"the sense that enables you to be aware of things and what they are like when you put your hands and fingers on them","cn":"触觉；触感","g":"[uncountable]","sc":"sense","ex":{"en":"the sense of touch","cn":"触觉"},"pos":"noun"},{"en":"an act of putting your hand or another part of your body onto somebody/something","cn":"触摸；触；碰","g":"[countable, usually singular]","sc":"with hand/part of body","ex":{"en":"The gentle touch of his hand on her shoulder made her jump.","cn":"他的手轻轻地触了一下她肩膀便使她跳了起来。"},"pos":"noun"},{"en":"the way that something feels when you put your hand or fingers on it or when it comes into contact with your body","cn":"触摸时的感觉","g":"[singular]","sc":"way something feels","ex":{"en":"material with a smooth silky touch","cn":"摸起来光滑得像丝绸一样的料子"},"pos":"noun"},{"en":"a small detail that is added to something in order to improve it or make it complete","cn":"修饰；润色；装点","g":"[countable]","sc":"small detail","ex":{"en":"Meeting them at the airport was a nice touch.","cn":"到机场迎接他们是一个妙招。"},"pos":"noun"},{"en":"a way or style of doing something","cn":"作风；风格；手法","g":"[singular]","sc":"way of doing something","ex":{"en":"She prefers to answer any fan mail herself for a more personal touch.","cn":"她喜欢针对每一位崇拜者的来信亲自予以回复。"},"pos":"noun"},{"en":"a very small amount","cn":"一点儿；少许","g":"[countable, usually singular]","sc":"small amount","ex":{"en":"There was a touch of sarcasm in her voice.","cn":"她的话音中有点儿讥讽的意味。"},"pos":"noun"},{"en":"slightly; a little","cn":"轻微；稍许","g":"[singular]","sc":"slightly","ex":{"en":"The music was a touch too loud for my liking.","cn":"这音乐有点太吵，不合我的口味。"},"pos":"noun"},{"en":"the area outside the lines that mark the sides of the playing field","cn":"边线以外的区域","g":"[uncountable]","sc":"in football/rugby","ex":{"en":"He kicked the ball into touch.","cn":"他把球踢出了边线。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"触摸;接触;碰到","en":"If you touch something, you put your hand onto it in order to feel it or to make contact with it.","ex":{"en":"Her tiny hands gently touched my face","cn":"她的小手轻轻触摸我的脸庞。"}},{"pos":"V-RECIP-ERG","cn":"(使)接触;(使)相碰","en":"If two things are touching, or if one thing touches another, or if you touch two things, their surfaces come into contact with each other.","ex":{"en":"Their knees were touching ","cn":"他们的膝盖挨着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"触觉;触感","en":"Your sense of touch is your ability to tell what something is like when you feel it with your hands.","ex":{"en":"The evidence suggests that our sense of touch is programmed to diminish with age.","cn":"有证据表明，我们的触觉会随着年龄的增长而减损。"}},{"pos":"VERB 动词","cn":"轻击;轻碰","en":"To touch something means to strike it, usually quite gently.","ex":{"en":"He scored the first time he touched the ball…","cn":"他第一次触球就得分了。"}},{"pos":"VERB 动词","cn":"(与否定词连用)处理，照看，照管","en":"If something has not been touched, nobody has dealt with it or taken care of it.","ex":{"en":"When John began to restore the house in the 1960s, nothing had been touched for 40 years.","cn":"约翰 20 世纪 60 年代开始整修那幢房子时，它已有 40 年都无人照管了。"}},{"pos":"VERB 动词","cn":"(与否定词连用，尤用于受到指责时)伤害，攻击，破坏","en":"If you say that you did not touch someone or something, you are emphasizing that you did not attack, harm or destroy them, especially when you have been accused of doing so.","ex":{"en":"Pearce remained adamant, saying 'I didn't touch him'","cn":"皮尔斯仍旧坚定不移地说：“我没有碰过他。”"}},{"pos":"VERB 动词","cn":"(与否定词连用)尝，吃，喝，用","en":"You say that you never touch something or that you have not touched something for a long time to emphasize that you never use it, or you have not used it for a long time.","ex":{"en":"He doesn't drink much and doesn't touch drugs","cn":"他喝酒不多，也不沾毒品。"}},{"pos":"VERB 动词","cn":"谈及;涉及","en":"If you touch on a particular subject or problem, you mention it or write briefly about it.","ex":{"en":"The film touches on these issues, but only superficially","cn":"这部电影涉及了这些问题，但却流于表面。"}},{"pos":"VERB 动词","cn":"(短时间地)影响到","en":"If something touches you, it affects you in some way for a short time.","ex":{"en":"...a guilt that in some sense touches everyone","cn":"在某种意义上影响到每个人的负罪感"}},{"pos":"VERB 动词","cn":"触动;感动","en":"If something that someone says or does touches you, it affects you emotionally, often because you see that they are suffering a lot or that they are being very kind.","ex":{"en":"It has touched me deeply to see how these people live","cn":"看到这些人的生活境况，我深受触动。"}},{"pos":"VERB 动词","cn":"具有…特性","en":"If something is touched with a particular quality, it has a certain amount of that quality.","ex":{"en":"His crinkly hair was touched with grey","cn":"他卷曲的头发有些花白。"}},{"pos":"VERB 动词","cn":"比得上;及得过","en":"If you say about someone that nobody can touch him or her for a particular thing, you mean that he or she is much better at it than anyone else.","ex":{"en":"No one can touch these girls for professionalism.","cn":"就职业素养来说，没人能比得上这些姑娘。"}},{"pos":"VERB 动词","cn":"达到","en":"To touch a particular level, amount, or score, especially a high one, means to reach it.","ex":{"en":"By the third lap Kinkead had touched 289 m.p.h.","cn":"到第三圈时，金基德的车速达到了每小时 289 英里。"}},{"pos":"VERB 动词","cn":"向(某人)要(钱)","en":"If you touch someone for money, you ask them to give it to you.","ex":{"en":"Now is the time to touch him for a loan.","cn":"现在是向他借笔钱的时候了。"}},{"pos":"N-COUNT 可数名词","cn":"润色;装点;修饰","en":"A touch is a detail which is added to something to improve it.","ex":{"en":"They called the event 'a tribute to heroes', which was a nice touch","cn":"他们把这一活动称为“向英雄致敬”，这可是加分之举。"}},{"pos":"N-SING 单数名词","cn":"风格;手法;特有方式","en":"If someone has a particular kind of touch, they have a particular way of doing something.","ex":{"en":"The dishes he produces all have a personal touch","cn":"他做的菜全都带有其个人风格。"}},{"pos":"QUANT 数量词","cn":"一点;些许","en":"A touch of something is a very small amount of it.","ex":{"en":"She thought she just had a touch of flu","cn":"她认为自己仅仅有点感冒。"}},{"pos":"PHRASE 短语","cn":"稍许;略微","en":"You can use a touch to mean slightly or to a small extent, especially in order to make something you say seem less extreme. For example, if you say that something is a touch expensive, you might really think that it is very expensive.","ex":{"en":"We were all a touch uneasy, I think","cn":"我想我们都稍有点不自在。"}},{"pos":"PHRASE 短语","cn":"一按;一摁","en":"You use at the touch of in expressions such as at the touch of a button and at the touch of a key to indicate that something is possible by simply touching a switch or one of the keys of a keyboard.","ex":{"en":"Staff will be able to trace calls at the touch of a button.","cn":"工作人员一摁按钮便可以追踪电话。"}},{"pos":"PHRASE 短语","cn":"平易近人的品质","en":"If you say that someone has the common touch, you mean that they have the natural ability to have a good relationship with ordinary people and be popular with them.","ex":{"en":"Unlike many senior judges, he has consistently shown that he has the common touch.","cn":"与很多高级法官不同，他一贯表现得平易近人。"}},{"pos":"PHRASE 短语","cn":"(与…)联络;(与…)联系","en":"If you get in touch with someone, you contact them by writing to them or telephoning them. If you are, keep, or stay in touch with them, you write, phone, or visit each other regularly.","ex":{"en":"I will get in touch with solicitors about this…","cn":"我会就此事与律师联系。"}},{"pos":"PHRASE 短语","cn":"了解最新情况(或信息)/不了解最新情况(或信息)","en":"If you are in touch with a subject or situation, or if someone keeps you in touch with it, you know the latest news or information about it. If you are out of touch with it, you do not know the latest news or information about it.","ex":{"en":"You'll also be kept in touch with local Oxfam events.","cn":"您还将随时获得乐施会在当地的最新活动信息。"}},{"pos":"PHR-RECIP 相互短语","cn":"(与…)失去联络;(与…)失去联系","en":"If you lose touch with someone, you gradually stop writing, telephoning, or visiting them.","ex":{"en":"In my job one tends to lose touch with friends","cn":"干我这行，往往会与朋友失去联系。"}},{"pos":"PHRASE 短语","cn":"不再了解最新情况(或信息)","en":"If you lose touch with something, you no longer have the latest news or information about it.","ex":{"en":"Their leaders have lost touch with what is happening in the country.","cn":"他们的领导人不再了解该国正发生的一切。"}},{"pos":"PHRASE 短语","cn":"不确定的事态;无法预言的事","en":"If you say that something is touch and go, you mean that you are uncertain whether it will happen or succeed.","ex":{"en":"It was touch and go whether we'd go bankrupt.","cn":"我们是否会破产还很难说。"}},{"pos":"PHRASE 短语","cn":"容易借钱给人的人;好说话的人","en":"If you say that someone is a soft touch or an easy touch, you mean that they can easily be persuaded to lend you money or to do things for you.","ex":{"en":"Mr Wilson is no soft touch…","cn":"威尔逊先生绝不会轻易借钱给别人。"}},{"pos":"","cn":"","en":"would not touch someone or something with a barge pole→see: ; the finishing touch→see: ; touch wood→see: ;"},{"pos":"","cn":"","en":"相关词组：touch down touch off"}]},"examples":[{"en":"( figurative ) I must do some more work on that article — I haven't touched it all week.","cn":"我还得在那篇文章上再下点儿工夫，我整整一个星期没有碰它了。"},{"en":"His last two movies have been complete flops and now no studio will touch him.","cn":"他的前两部电影彻底失败了，现在没有制片厂愿意用他。"}]},"toolkit":{"media":{"uk":"media/uk/toolkit__gb_1.mp3","us":"media/us/toolkit__us_1.mp3"},"oxford":{"phon":"ˈtuːlkɪt","pos":"noun","senses":[{"en":"a set of tools in a box or bag","cn":"（装在箱子或包里的）一套工具；工具箱；工具包"},{"en":"a set of software tools","cn":"配套软件；软件包；工具箱","lab":"computing"},{"en":"the things that you need in order to achieve something","cn":"配备用品；装备"}]}},"toots":{"lemma":"toot","media":{"uk":"media/ldoce/hwd/bre/5/ld44toots.mp3","us":"media/ldoce/hwd/ame/e/toots.mp3"}},"tomorrow":{"media":{"uk":"media/uk/tomorrow__gb_1.mp3","us":"media/us/tomorrow__us_2.mp3"},"oxford":{"phon":"təˈmɒrəʊ","pos":"adverb","senses":[{"en":"on or during the day after today","cn":"在明天；在明日","lab":"especially British English","ex":{"en":"I'm off now. See you tomorrow.","cn":"我走了。明天见。"}},{"en":"the day after today","cn":"明天；明日","ex":{"en":"Today is Tuesday, so tomorrow is Wednesday.","cn":"今天是星期二，那么明天就是星期三。"},"pos":"noun"},{"en":"the future","cn":"未来；将来；来日","ex":{"en":"Who knows what changes tomorrow may bring?","cn":"谁知道将来会有什么变化？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在明天;在明日","en":"You use tomorrow to refer to the day after today.","ex":{"en":"Bye, see you tomorrow","cn":"再见，明天见。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"","en":"Tomorrow is also a noun.","ex":{"en":"What's on your agenda for tomorrow?…","cn":"你明天的日程是怎么安排的？"}},{"pos":"ADV 副词","cn":"在未来;(尤指)在不久的将来","en":"You can refer to the future, especially the near future, as tomorrow .","ex":{"en":"What is education going to look like tomorrow?","cn":"未来的教育会是什么样子？"}}]},"examples":[{"en":"She spends money like there's no tomorrow.","cn":"她拼命花钱，就像过了今天没有明天似的。"},{"en":"Today is Tuesday, so tomorrow is Wednesday.","cn":"今天是星期二，那么明天就是星期三。"}]},"tomb":{"oxford":{"phon":"tuːm","pos":"noun","senses":[{"en":"a large grave (= where a dead person is buried), especially one built of stone above or below the ground","cn":"坟墓；冢","ex":{"en":"the tombs of the Pharaohs","cn":"（埃及）法老的墓室"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"坟墓;冢","en":"A tomb is a large grave that is above ground and that usually has a sculpture or other decoration on it."}]},"media":{"uk":"media/uk/tomb__gb_1.mp3","us":"media/us/tomb__us_1.mp3"},"examples":[{"en":"the family tomb","cn":"家族坟墓"}]},"towards":{"media":{"uk":"media/uk/towards__gb_1.mp3","us":"media/us/towards__us_1.mp3"},"oxford":{"phon":"təˈwɔːdz","pos":"preposition","senses":[{"en":"in the direction of somebody/something","cn":"向；朝；对着","ex":{"en":"They were heading towards the German border.","cn":"他们正前往德国边界。"}},{"en":"getting closer to achieving something","cn":"趋向，接近，将近（完成某事）","ex":{"en":"This is a first step towards political union.","cn":"这是走向政治上联合的第一步。"}},{"en":"close or closer to a point in time","cn":"接近，将近（某一时间）","ex":{"en":"towards the end of April","cn":"将近四月底"}},{"en":"in relation to somebody/something","cn":"对；对于；关于","ex":{"en":"He was warm and tender towards her.","cn":"他对她既热情又温柔。"}},{"en":"with the aim of obtaining something, or helping somebody to obtain something","cn":"以…为目标（或目的）；用于","ex":{"en":"The money will go towards a new school building (= will help pay for it).","cn":"这笔资金将用于修建新校舍。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"向;朝;面对","en":"If you move, look, or point towards something or someone, you move, look, or point in their direction.","ex":{"en":"Caroline leant across the table towards him","cn":"卡罗琳隔着桌子俯身向他靠过来。"}},{"pos":"PREP 介词","cn":"倾向于；趋向于","en":"If things develop towards a particular situation, that situation becomes nearer in time or more likely to happen.","ex":{"en":"The talks made little evident progress towards agreement","cn":"会谈在达成一致方面几乎没有取得明显进展。"}},{"pos":"PREP 介词","cn":"对;对于;关于","en":"If you have a particular attitude towards something or someone, you have that attitude when you think about them or deal with them.","ex":{"en":"It's the business of the individual to determine his own attitude towards religion","cn":"对宗教持何种态度是个人的事情。"}},{"pos":"PREP 介词","cn":"将近(某一时刻)","en":"If something happens towards a particular time, it happens just before that time.","ex":{"en":"The Channel tunnel was due to open towards the end of 1993","cn":"海峡隧道预计 1993 年年底前开通。"}},{"pos":"PREP 介词","cn":"接近；靠近","en":"If something is towards part of a place or thing, it is near that part.","ex":{"en":"The home of the Morgan family was up Gloucester Road, towards the top of the hill","cn":"摩根家族的住宅在格洛斯特路接近山顶的地方。"}},{"pos":"PREP 介词","cn":"（钱）用于","en":"If you give money towards something, you give it to help pay for that thing.","ex":{"en":"He gave them £50,000 towards a house","cn":"他给了他们 5 万英镑用于买房子。"}}]},"examples":[{"en":"This is a first step towards political union.","cn":"这是走向政治上联合的第一步。"},{"en":"The money will go towards a new school building (= will help pay for it).","cn":"这笔资金将用于修建新校舍。"}]},"torrential":{"media":{"uk":"media/uk/torrential__gb_1.mp3","us":"media/us/torrential__us_1.mp3"},"oxford":{"phon":"təˈrenʃl","pos":"adjective","senses":[{"en":"falling in large amounts","cn":"倾泻的；如注的","ex":{"en":"torrential rain","cn":"倾盆大雨"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(大雨)倾盆的，如注的","en":"Torrential rain pours down very rapidly and in great quantities."}]}},"told":{"lemma":"tell","media":{"uk":"media/uk/told__gb_1.mp3","us":"media/us/told__us_1.mp3"}},"tons":{"lemma":"ton","media":{"uk":"media/ldoce/hwd/bre/4/tons0205.mp3","us":"media/ldoce/hwd/ame/8/tons.mp3"}},"totally":{"media":{"uk":"media/uk/totally__gb_1.mp3","us":"media/us/totally__us_1.mp3"},"oxford":{"phon":"ˈtəʊtəli","pos":"adverb","senses":[{"en":"completely","cn":"完全；全部；整个","lab":"especially North American English, informal，，","ex":{"en":"They come from totally different cultures.","cn":"他们来自完全不同的文化。"}}]},"examples":[{"en":"I'm still not totally convinced that he knows what he's doing.","cn":"我仍然不完全相信他明白自己在干什么。"},{"en":"( informal ) ( especially NAmE ) ‘She's so cute!’ ‘Totally!’ (= I agree) “","cn":"她真是精明过人！” “一点不错！”"}]},"toe":{"media":{"uk":"media/uk/toe__gb_1.mp3","us":"media/us/toe__us_1.mp3","img":["media/ldoce/img/shoes.jpg"]},"oxford":{"phon":"təʊ","pos":"noun","senses":[{"en":"one of the five small parts that stick out from the foot; any similar part on the foot of an animal or bird","cn":"脚趾；趾","ex":{"en":"the big/little toe (= the largest/smallest toe)","cn":"大脚趾；小脚趾"}},{"en":"the part of a sock, shoe, etc. that covers the toes","cn":"（袜、鞋等的）足尖部；鞋头","ex":{"en":"He kicked the earth with the toe of his boot.","cn":"他用靴子头踢了踢地面。"}},{"en":"having the type or number of toes mentioned","cn":"有…脚趾的","ex":{"en":"open-toed sandals","cn":"露趾凉鞋"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"足尖；脚趾","en":"Your toes are the five movable parts at the end of each foot."},{"pos":"N-COUNT 可数名词","cn":"(鞋、袜的)足尖部","en":"The toe of a shoe or sock is the part that covers the end of your foot."},{"pos":"PHRASE 短语","cn":"稍加尝试;谨慎尝试","en":"If you dip your toes into something or dip your toes into the waters of something, you start doing that thing slowly and carefully, because you are not sure whether it will be successful or whether you will like it.","ex":{"en":"This may encourage gold traders to dip their toes back into the markets","cn":"这可能会促使黄金交易商谨慎地尝试重返市场。"}},{"pos":"PHRASE 短语","cn":"使保持警觉","en":"If you say that someone or something keeps you on your toes, you mean that they cause you to remain alert and ready for anything that might happen.","ex":{"en":"His fiery campaign rhetoric has kept opposition parties on their toes for months.","cn":"他激烈的竞选言辞使反对党派一连几个月都保持警觉。"}},{"pos":"PHRASE 短语","cn":"听从;服从","en":"If you toe the line, you behave in the way that people in authority expect you to.","ex":{"en":"...attempts to persuade the rebel members to toe the line","cn":"说服叛乱分子顺从政府的努力"}},{"pos":"PHRASE 短语","cn":"触犯;得罪","en":"If you tread on someone's toes, you offend them by criticizing the way that they do something or by interfering in their affairs.","ex":{"en":"I must be careful not to tread on their toes. My job is to challenge, but not threaten them.","cn":"我必须小心谨慎，不能得罪他们。我的工作是挑战他们，而不是威胁他们。"}}]},"examples":[{"en":"Surprise visits help to keep the staff on their toes.","cn":"突击巡察有助于使员工不致懈怠偷懒。"},{"en":"Can you touch your toes? (= by bending over while keeping your legs straight)","cn":"你弯腰够得着你的脚趾么？"}]},"towns":{"lemma":"town"},"toiled":{"lemma":"toil"},"toured":{"lemma":"tour"},"toilers":{"oxford":{"phon":"tɔɪl","pos":"verb","senses":[{"en":"to work very hard and/or for a long time, usually doing hard physical work （","cn":"长时间）苦干，辛勤劳作"},{"en":"to move slowly and with difficulty","cn":"艰难缓慢地移动；跋涉"}]}},"towered":{"lemma":"tower"},"toward":{"lemma":"towards"},"touches":{"lemma":"touch"},"tourists":{"lemma":"tourist"},"towels":{"lemma":"towel"},"tottered":{"lemma":"totter"},"towers":{"lemma":"tower"},"tools":{"lemma":"tool"},"toxins":{"lemma":"toxin"},"toner":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"爽肤水;紧肤水;化妆水","en":"A toner is a substance which you can put on your skin, for example to clean it or make it less oily."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of ink that is used in machines that print or copy documents 〔","cn":"打印机﹑复印机等用的〕墨粉﹐色粉"},{"en":"a liquid that you put on your face to make your skin feel soft and smooth","cn":"润肤水"}]},"media":{"uk":"media/ldoce/hwd/bre/9/toner0205.mp3","us":"media/ldoce/hwd/ame/6/laadtoner.mp3"},"oxford":{"phon":"ˈtəʊnə(r)","pos":"noun","senses":[{"en":"a type of ink (= coloured liquid) used in machines that print or photocopy","cn":"（打印机或复印机使用的）墨粉"},{"en":"a liquid or cream used for making the skin on your face tighter and smoother","cn":"护肤霜；爽肤水"}]}},"torment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"极度痛苦；苦恼万分；折磨","en":"Torment is extreme suffering, usually mental suffering.","ex":{"en":"The torment of having her baby kidnapped is written all over her face.","cn":"因孩子被绑架所受的万分折磨全写在她脸上。"}},{"pos":"N-COUNT 可数名词","cn":"使人痛苦的事;折磨人的事","en":"A torment is something that causes extreme suffering, usually mental suffering.","ex":{"en":"Sooner or later most writers end up making books about the torments of being a writer","cn":"或早或晚，大多数作家最终都会著书讲述身为作家的苦恼。"}},{"pos":"VERB 动词","cn":"折磨;使痛苦万分","en":"If something torments you, it causes you extreme mental suffering.","ex":{"en":"At times the memories returned to torment her","cn":"有时，她再度想起往事，又会痛苦万分。"}},{"pos":"VERB 动词","cn":"戏弄;作弄","en":"If you torment a person or animal, you annoy them in a playful, rather cruel way for your own amusement.","ex":{"en":"My older brother and sister used to torment me by singing it to me.","cn":"哥哥姐姐以前常唱那首歌来戏弄我。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very unpleasant, painful, or upsetting conditions - use this especially about a situation that affects a lot of people","cn":""},{"en":"when your life is difficult and uncomfortable, especially because you are very poor","cn":""},{"en":"a difficult and unpleasant situation, in which people are suffering a lot and that makes you feel great sympathy for them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"By repeatedly trying to make someone miserable you torment them. The noun torment is the result of the verb torment ."}]},"collocations":{"phrases":["ADJ. great | inner, mental, private","VERB + TORMENT endure, suffer She has suffered great mental torment. | be released from","PREP. in ~ He was a man in torment.","PHRASES a soul in torment The sea wailed like a soul in torment."]},"media":{"uk":"media/ldoce/hwd/bre/4/torment_n0205.mp3","us":"media/ldoce/hwd/ame/c/l3torment.mp3"},"examples":[{"en":"She suffered years of mental torment after her son's death.","cn":"儿子去世后，她多年悲痛欲绝。"},{"en":"the cries of a man in torment","cn":"一个备受折磨的人的喊叫声"}],"oxford":{"phon":"ˈtɔːment","pos":"noun","senses":[{"en":"extreme pain, especially mental pain; a person or thing that causes this","cn":"（尤指精神上的）折磨，痛苦；苦难之源","ex":{"en":"She suffered years of mental torment after her son's death.","cn":"儿子去世后，她多年悲痛欲绝。"}},{"en":"to make somebody suffer very much","cn":"使备受折磨；使痛苦；烦扰","lab":"formal","ex":{"en":"He was tormented by feelings of insecurity.","cn":"他苦于没有安全感。"},"pos":"verb"},{"en":"to annoy a person or an animal in a cruel way","cn":"戏弄；捉弄；纠缠","pos":"verb"}]}},"tonal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"音调的;声调的;调性的","en":"Tonal means relating to the qualities or pitch of a sound or to the tonality of a piece of music.","ex":{"en":"There is little tonal variety in his voice.","cn":"他说话几乎没有声调变化。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to tones of colour or sound","cn":"色调的﹔音调的"},{"en":"a piece of music that is tonal is based on a particular key 〔","cn":"音乐〕调性的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tonal.mp3","us":"media/ldoce/hwd/ame/e/tonal.mp3"},"examples":[{"en":"The tonal range she uses is wide and varied.","cn":"她使用的色调丰富多彩。"}],"oxford":{"phon":"ˈtəʊnl","pos":"adjective","senses":[{"en":"relating to tones of sound or colour","cn":"音调的；声调的；色调的","lab":"specialist"},{"en":"having a particular key","cn":"调性的","lab":"music"}]}},"top-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"再斟满的一杯","en":"A top-up is another serving of a drink in the same glass that you have just used.","ex":{"en":"Anyone ready for a top-up?","cn":"谁还要再满上？"}},{"pos":"ADJ 形容词","cn":"(贷款或支付款项)补足的，追加的","en":"A top-up loan or payment is added to an amount of money in order to bring it up to a required level.","ex":{"en":"Student grants will be frozen at existing levels and top-up loans made available.","cn":"学生助学金将冻结在现有水平，但可以申请补足贷款。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of liquid that you add to a glass, cup etc in order to make it full again 〔","cn":"液体〕加至满杯的量"},{"en":"an extra payment that brings an amount to the desired level 〔","cn":"为达到所需水平而〕追加的钱款"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41top-up.mp3","us":"media/ldoce/hwd/ame/3/ld41top-up.mp3"},"examples":[{"en":"Students will have to pay top-up fees (= fees that are above the basic level).","cn":"学生必须交附加费用。"},{"en":"Can I give anyone a top-up?","cn":"我来给哪位添酒好吗？"}],"oxford":{"phon":"ˈtɒp ʌp","pos":"noun","senses":[{"en":"a payment that you make to increase the amount of money, etc. to the level that is needed","cn":"附加付款","ex":{"en":"a phone top-up (= to buy more time for calls)","cn":"电话充值费"}},{"en":"an amount of a drink that you add to a cup or glass in order to fill it again","cn":"（重新斟满杯子的）补充饮料","lab":"informal","ex":{"en":"Can I give anyone a top-up?","cn":"我来给哪位续杯好吗？"}}]}},"toll-free":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(电话号码)免费拨打的","en":"A toll-free telephone number is one which you can dial without having to pay for the call.","ex":{"en":"Call our customer-service staff toll-free.","cn":"免费拨打我们的客服电话。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if you telephone a particular number toll-free, you do not have to pay for the call 〔","cn":"打电话〕无须付费地﹐免费地"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41toll-free.mp3","us":"media/ldoce/hwd/ame/0/ld41toll-free.mp3"},"examples":[{"en":"a toll-free number","cn":"免费电话号码"}],"oxford":{"phon":"ˌtəʊl ˈfriː","pos":"adjective","senses":[{"en":"that you do not have to pay for","cn":"免费的","ex":{"en":"a toll-free number","cn":"免费电话号码"}}]}},"tonsillitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"扁桃体炎","en":"Tonsillitis is a painful swelling of your tonsils caused by an infection."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an infection of the tonsils","cn":"扁桃体炎﹐扁桃腺炎"}]},"media":{"uk":"media/ldoce/hwd/bre/a/tonsillitis0205.mp3","us":"media/ldoce/hwd/ame/5/laadtonsillitis.mp3"},"examples":[{"en":"Sam’s got tonsillitis .","cn":"萨姆得了扁桃体炎。"}],"oxford":{"phon":"ˌtɒnsəˈlaɪtɪs","pos":"noun","senses":[{"en":"an infection of the tonsils in which they become swollen (= larger than normal) and painful","cn":"扁桃体炎"}]}},"topical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有关时事的;时下关注的;热门话题的","en":"Topical is used to describe something that concerns or relates to events that are happening at the present time.","ex":{"en":"The magazine's aim is to discuss topical issues within a Christian framework","cn":"该杂志的宗旨是在基督教框架下讨论时下的热门话题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the present situation is the one that exists now; your present job, address etc is the one that you have now","cn":""},{"en":"use this about things or situations that exist now, when you think they may be changed in the future","cn":""},{"en":"use this about a situation or activity which is happening now, but which is not expected to continue for a long time","cn":""}]},"vocab":{"pos":"1 adj 2 adj 3 adj","senses":[{"en":"When some information or news is current and of immediate interest, we say it is topical . This might be a news story or a bit of gossip, or just a subject that is of current importance. If it's \"now,\" it's topical ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/topical0205.mp3","us":"media/ldoce/hwd/ame/5/topical.mp3"},"examples":[{"en":"a topical joke/reference","cn":"时事笑话；提及热门话题"},{"en":"topical events","cn":"当前人们所关注的事件"}],"oxford":{"phon":"ˈtɒpɪkl","pos":"adjective","senses":[{"en":"connected with something that is happening or of interest at the present time","cn":"有关时事的；当前关注的；热门话题的","ex":{"en":"a topical joke/reference","cn":"时事笑话；提及热门话题"}},{"en":"connected with, or put directly on, a part of the body","cn":"（身体）局部的，表面的","lab":"medical"}]}},"tolerable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可忍受的;可容忍的","en":"If you describe something as tolerable, you mean that you can bear it, even though it is unpleasant or painful.","ex":{"en":"The levels of tolerable pain vary greatly from individual to individual…","cn":"对疼痛的耐受程度因人而异，差别很大。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过得去的;还可以的","en":"If you describe something as tolerable, you mean that it is fairly good and reasonably satisfactory, but not of the highest quality or standard.","ex":{"en":"He fell asleep just past midnight with tolerable ease","cn":"他刚过午夜就睡着了，睡得还算安稳。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a situation or type of behaviour that is bearable is difficult or unpleasant, but you are just able to bear it","cn":""},{"en":"a situation that is tolerable is bad but you are able to accept it and deal with it","cn":""},{"en":"a situation that is tolerable is not very good, but you are able to accept it 〔","cn":"状况〕可接受的﹐过得去的﹐尚好的"}]},"collocations":{"phrases":["VERBS be | become | make sth | find sth She inspected the rooms and found them perfectly tolerable.","ADV. very | perfectly | barely, scarcely In August the heat is barely tolerable. | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/9/tolerable0205.mp3","us":"media/ldoce/hwd/ame/1/tolerable.mp3"},"examples":[{"en":"At times, the heat was barely tolerable.","cn":"有时天气炎热得几乎令人难以忍受。"},{"en":"He plays the piano tolerably (well).","cn":"他钢琴弹得还算不错。"}],"oxford":{"phon":"ˈtɒlərəbl","pos":"adjective","senses":[{"en":"fairly good, but not of the best quality","cn":"尚好的；过得去的；还可以的","ex":{"en":"a tolerable degree of success","cn":"说得过去的成功"}},{"en":"that you can accept or bear, although unpleasant or painful","cn":"可接受的；可忍受的；可容忍的","ex":{"en":"At times, the heat was barely tolerable.","cn":"有时天气炎热得几乎令人难以忍受。"}}]}},"touristy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"挤满游客的;被旅游商品充斥的","en":"If you describe a place as touristy, you do not like it because it is full of tourists or full of things for tourists to buy and do.","ex":{"en":"Visit some of the less touristy islands.","cn":"游览一些商业味没那么重的岛屿吧。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a place that is touristy is full of tourists and the things that attract tourists – used to show disapproval","cn":"挤满游客的﹐旅游味道浓的〔含贬义〕"},{"en":"a touristy activity is typical of the things that tourists do – used to show disapproval 〔","cn":"活动〕和旅游有关的﹐旅游的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41touristy.mp3","us":"media/ldoce/hwd/ame/b/touristy.mp3"},"examples":[{"en":"Jersey is the most touristy of the islands.","cn":"这些岛屿中就数泽西岛最能吸引游客。"},{"en":"a shop full of touristy souvenirs","cn":"摆满旅游纪念品的商店"}],"oxford":{"phon":"ˈtʊərɪsti","pos":"adjective","senses":[{"en":"attracting or designed to attract a lot of tourists","cn":"吸引很多游客的；为吸引游客设计的","ex":{"en":"Jersey is the most touristy of the islands.","cn":"这些岛屿中就数泽西岛最能吸引游客。"}}]}},"toadstool":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毒菌;毒蘑菇","en":"A toadstool is a fungus that you cannot eat because it is poisonous."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wild plant like a mushroom , that can be poisonous （","cn":"毒）蕈"}]},"vocab":{"pos":"n","senses":[{"en":"A toadstool might sound like something you'd find a fairy living under, but it's really just a poisonous mushroom."}]},"media":{"uk":"media/ldoce/hwd/bre/8/toadstool0205.mp3","us":"media/ldoce/hwd/ame/4/toadstool.mp3"},"oxford":{"phon":"ˈtəʊdstuːl","pos":"noun","senses":[{"en":"a fungus with a round flat or curved head and a short stem. Many types of toadstool are poisonous.","cn":"伞菌（许多有毒性）"}]}},"tough":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚强的;吃苦耐劳的;坚韧不拔的","en":"A tough person is strong and determined, and can tolerate difficulty or suffering.","ex":{"en":"He built up a reputation as a tough businessman","cn":"他树立了铁面生意人的名声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗野的;粗暴的","en":"If you describe someone as tough, you mean that they are rough and violent.","ex":{"en":"He had shot three people dead earning himself a reputation as a tough guy.","cn":"他因枪杀三人得到了暴徒的恶名。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"治安很差的；充满犯罪与暴力的","en":"A tough place or area is considered to have a lot of crime and violence.","ex":{"en":"She doesn't seem cut out for this tough neighbourhood","cn":"她似乎不适合在这个治安恶劣的社区生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"艰难的;困苦的;难熬的","en":"A tough way of life or period of time is difficult or full of suffering.","ex":{"en":"She had a pretty tough childhood…","cn":"她的童年非常不幸。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"棘手的;难办的;难解决的","en":"A tough task or problem is difficult to do or solve.","ex":{"en":"It was a very tough decision but we feel we made the right one","cn":"这是个困难的决定，但是我们认为我们做出了正确的选择。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(政策或行动)强硬的，严厉的","en":"Tough policies or actions are strict and firm.","ex":{"en":"He is known for taking a tough line on security","cn":"他因在安全问题上采取强硬路线而闻名。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚固的;坚韧的;牢固的","en":"A tough substance is strong, and difficult to break, cut, or tear.","ex":{"en":"In industry, diamond can form a tough, non-corrosive coating for tools.","cn":"在工业上，金刚石可以用作工具表面坚固、耐腐蚀的覆盖层。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(肉)非常老的，切不下的，嚼不动的","en":"Tough meat is difficult to cut and chew.","ex":{"en":"The steak was tough and the peas were like bullets.","cn":"牛排老得嚼不动，豌豆像子弹一样硬。"}},{"pos":"PHRASE 短语","cn":"不泄气;坚持不懈","en":"If someone who is trying to achieve something hangs tough, they remain determined and do not give up, even when there are difficulties or problems.","ex":{"en":"The White House is hanging tough for a good agreement to be reached.","cn":"白宫为达成一项有利协议寸步不让。"}},{"pos":"","cn":"","en":"a tough row to hoe→see: ; a tough nut→see: ;"},{"pos":"","cn":"","en":"相关词组：tough out"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easy to do, understand, or deal with","cn":""},{"en":"difficult. Hard is less formal than difficult and is very common in spoken English","cn":""},{"en":"very difficult, because you have to use a lot of effort, or because it affects you emotionally","cn":""}]},"vocab":{"pos":"1 adj 2 adj n 3 adj","senses":[{"en":"The adjective tough is good for describing hard times. If you just got mugged, lost your job, got the flu, and broke your toe, you're having a really tough week."}]},"collocations":{"phrases":["VERBS be, seem | get","ADV. extremely, particularly, really, very | a bit, fairly, a little, pretty, quite Things were pretty tough at first.","PREP. on It's very tough on the wives when the husbands go off like that. 2 strict/firm","VERBS be | become, get","ADV. extremely, particularly, very | fairly, pretty, quite | enough Has the government been tough enough on polluters?","PREP. on The government has promised to get tough on crime. | with You have to be tough with these young thugs. 3 strong","VERBS be, feel, look, seem | become, get, grow | act, talk (both informal) Then this guy started acting tough.","ADV. incredibly, really, remarkably, very | pretty, quite, reasonably | enough Are you sure you're physically tough enough for this job? | m"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdetough.mp3","us":"media/ldoce/hwd/ame/b/tough1.mp3"},"examples":[{"en":"‘If you take the car, I won't be able to go out.’ ‘Tough luck!’ “","cn":"如果你把车开走，我就出不去了。” “该你倒霉！”"},{"en":"It's about time teachers started to get tough with bullies.","cn":"现在教师该对横行霸道的学生开始采取严厉措施了。"}],"oxford":{"phon":"tʌf","pos":"adjective","senses":[{"en":"having or causing problems or difficulties","cn":"艰苦的；艰难的；棘手的","sc":"difficult","ex":{"en":"a tough childhood","cn":"苦难的童年"}},{"en":"demanding that particular rules be obeyed and showing a lack of sympathy for any problems that this may cause","cn":"严厉的；强硬的；无情的","sc":"strict","ex":{"en":"It's about time teachers started to get tough with bullies.","cn":"现在教师要对横行霸道的学生开始采取严厉措施了。"}},{"en":"strong enough to deal successfully with difficult conditions or situations","cn":"坚强的；健壮的；能吃苦耐劳的；坚韧不拔的","sc":"strong","ex":{"en":"a tough breed of cattle","cn":"耐劣等饲养条件的牛种"}},{"en":"physically strong and likely to be violent","cn":"彪悍的；粗暴的；粗野的","sc":"strong","ex":{"en":"You think you're so tough, don't you?","cn":"你以为自己够厉害的，是不是？"}},{"en":"with a lot of crime or violence","cn":"治安很差的；充满犯罪（或暴力）的","sc":"violent","ex":{"en":"She grew up in a tough neighbourhood.","cn":"她生长在一个治安混乱的街区。"}},{"en":"difficult to cut or bite on","cn":"难切开的；嚼不烂的；老的","sc":"meat","ex":{"en":"The meat was a bit tough.","cn":"肉有点老了。"}},{"en":"not easily cut, broken, torn, etc.","cn":"坚固的；不易切开（或打破、撕破等）的","sc":"not easily damaged","ex":{"en":"a tough pair of shoes","cn":"一双结实的鞋子"}},{"en":"unlucky for somebody in a way that seems unfair","cn":"不幸的；倒霉的","lab":"informal","sc":"not lucky","ex":{"en":"It was tough on her being dropped from the team like that.","cn":"她就这样被队里刷了下来，真是倒霉。"}},{"en":"a person who regularly uses violence against other people","cn":"粗暴的人；暴徒；恶棍","pos":"noun"}]}},"torsion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"扭转","en":"Torsion is a twisting effect on something such as a piece of metal or an organ of the body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the twisting of a piece of metal 〔","cn":"金属的〕扭转"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41torsion.mp3","us":"media/ldoce/hwd/ame/8/torsion.mp3"},"oxford":{"phon":"ˈtɔːʃn","pos":"noun","senses":[{"en":"the action of twisting something, especially one end of something while the other end is held fixed","cn":"（物体等一端固定的）扭转"}]}},"tolerance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宽容;容忍","en":"Tolerance is the quality of allowing other people to say and do as they like, even if you do not agree or approve of it.","ex":{"en":"...his tolerance and understanding of diverse human nature.","cn":"他对人性多面性的宽容与理解"}},{"pos":"N-UNCOUNT 不可数名词","cn":"忍耐(力);忍受(力)","en":"Tolerance is the ability to bear something painful or unpleasant.","ex":{"en":"There is lowered pain tolerance, lowered resistance to infection.","cn":"对疼痛的忍耐力降低了，对感染的抵抗力也减弱了。"}},{"pos":"N-VAR 可变名词","cn":"耐受性","en":"If someone or something has a tolerance to a substance, they are exposed to it so often that it does not have very much effect on them.","ex":{"en":"As with any drug taken in excess, your body can build up a tolerance to it.","cn":"和过量服用任何其他药物一样，身体会对它产生耐药性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not strict in the way that you punish people or control their behaviour","cn":""},{"en":"someone who is easy-going does not care about being strict, and is usually calm and relaxed","cn":""},{"en":"someone who is soft seems weak because they are not strict enough with other people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you practice tolerance , you accept another's ideas and beliefs. If you respect someone's opinions — even if you disagree or find them nonsensical — you display tolerance ."}]},"collocations":{"phrases":["ADJ. great, high, remarkable | low | amused, patronising He watched the kids throw water around with amused tolerance. | political, racial, ","QUANT. degree, level","VERB + TOLERANCE have | show | lack | learn","TOLERANCE + NOUN level","PREP. ~ for Some children have a low tolerance for boredom. | ~ of people with a high tolerance of discomfort | ~ to Tolerance to alcohol de"]},"media":{"uk":"media/ldoce/hwd/bre/4/tolerance0205.mp3","us":"media/ldoce/hwd/ame/1/tolerance.mp3"},"examples":[{"en":"They were working to a tolerance of 0.0001 of a centimetre.","cn":"他们在按 0.0001 厘米的公差加工。"},{"en":"Tolerance to alcohol decreases with age.","cn":"酒量随年龄的增大而减少。"}],"oxford":{"phon":"ˈtɒlərəns","pos":"noun","senses":[{"en":"the quality of being willing to accept or tolerate somebody/something, especially opinions or behaviour that you may not agree with, or people who are not like you","cn":"忍受；容忍；宽容；宽恕","g":"[uncountable]","ex":{"en":"She had no tolerance for jokes of any kind.","cn":"她容不得开任何玩笑。"}},{"en":"the ability to suffer something, especially pain, difficult conditions, etc. without being harmed","cn":"忍耐力；忍受性；耐力；耐量","g":"[countable, uncountable]","ex":{"en":"tolerance to cold","cn":"耐寒力"}},{"en":"the amount by which the measurement of a value can vary without causing problems","cn":"公差；容限","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"They were working to a tolerance of 0.0001 of a centimetre.","cn":"他们在按 0.0001 厘米的公差加工。"}}]}},"tome":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巨著;大部头书","en":"A tome is a very large, heavy book."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large heavy book","cn":"大部头著作"}]},"vocab":{"pos":"n","senses":[{"en":"A tome is a large book. If you're pre-med, chances are you're going to have one heck of a tome for your biology class. Tome is often used to refer to a book that is not only really large but also unusually important."}]},"media":{"uk":"media/ldoce/hwd/bre/4/tome0205.mp3","us":"media/ldoce/hwd/ame/6/tome.mp3"},"oxford":{"phon":"təʊm","pos":"noun","senses":[{"en":"a large, heavy book, especially one dealing with a serious topic","cn":"（尤指严肃的）大部头书，巨著","ex":{"en":"a weighty tome","cn":"一本沉重的大部头"}}]}},"toaster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烤面包(片)机","en":"A toaster is a piece of electrical equipment used to toast bread."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine you use for toasting bread","cn":"烤面包机﹐吐司[多士]炉"}]},"media":{"img":["media/ldoce/img/toaster.jpg"],"uk":"media/ldoce/hwd/bre/7/toaster0205.mp3","us":"media/ldoce/hwd/ame/2/toaster.mp3"},"oxford":{"phon":"ˈtəʊstə(r)","pos":"noun","senses":[{"en":"an electrical machine for making toast","cn":"（电的）烤面包片器；吐司炉"}]}},"torpedo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鱼雷；水雷","en":"A torpedo is bomb that is shaped like a tube and that travels under water."},{"pos":"VERB 动词","cn":"用鱼雷袭击(或击中、击沉)","en":"If a ship is torpedoed, it is hit, and usually sunk, by a torpedo or torpedoes.","ex":{"en":"More than a thousand people died when the Lusitania was torpedoed.","cn":"卢西塔尼亚号被鱼雷击沉，导致 1,000 多人死亡。"}},{"pos":"VERB 动词","cn":"故意破坏;使彻底完蛋","en":"If someone torpedoes negotiations or plans, they deliberately prevent them from being completed or from being successful.","ex":{"en":"These attacks are seen as an effort to torpedo the talks.","cn":"人们认为这些袭击是为了故意破坏会谈。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow weapon that is fired under the surface of the sea and explodes when it hits something","cn":"鱼雷"},{"en":"to attack or destroy a ship with a torpedo","cn":"用鱼雷攻击[摧毁]"},{"en":"to stop something such as a plan from succeeding","cn":"破坏〔计划等〕﹔使失败"}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"A torpedo is a type of missile or bomb fired underwater. To torpedo is to attack with torpedoes ."}]},"collocations":{"phrases":["VERB + TORPEDO carry enemy planes carrying torpedoes | fire, launch, release | drop","TORPEDO + VERB hit sth, strike sth","TORPEDO + NOUN tube | boat, bomber"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdetorpedo.mp3","us":"media/ldoce/hwd/ame/6/torpedo1.mp3"},"examples":[{"en":"Her comments had torpedoed the deal.","cn":"她的一番话使得那笔交易彻底告吹。"},{"en":"New threats of violence have effectively torpedoed the peace talks.","cn":"新的暴力威胁实际上已经破坏了和平谈判。"}],"oxford":{"phon":"tɔːˈpiːdəʊ","pos":"noun","senses":[{"en":"a long, narrow bomb that is fired under the water from a ship or submarine and that explodes when it hits a ship, etc.","cn":"鱼雷"},{"en":"to attack a ship or make it sink using a torpedo","cn":"用鱼雷袭击（或击沉）","ex":{"en":"The destroyer was torpedoed off the coast of Africa.","cn":"这艘驱逐舰在非洲海岸附近被鱼雷击中。"},"pos":"verb"},{"en":"to completely destroy the possibility that something could succeed","cn":"彻底破坏，完全摧毁（某事成功的可能性）","lab":"informal","ex":{"en":"Her comments had torpedoed the deal.","cn":"她的一番话使得那笔交易彻底告吹。"},"pos":"verb"}]}},"toffee-nosed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自视甚高的;自命不凡的","en":"If you say that someone is toffee-nosed, you disapprove of them because they have a high opinion of themselves and a low opinion of other people."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a toffee-nosed person thinks that they are better than other people because of their social position – used to show disapproval","cn":"好摆架子的﹐盛气凌人的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41toffee-nosed.mp3","us":"media/ldoce/hwd/ame/5/ld41toffee-nosed.mp3"},"oxford":{"phon":"ˈtɒfi nəʊzd","pos":"adjective","senses":[{"en":"behaving as if you are better than other people, especially those of a lower social class","cn":"势利眼的；妄自尊大的；目空一切的"}]}},"tobacconist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烟草商;烟草店老板","en":"A tobacconist is a shopkeeper who sells things such as tobacco, cigarettes, and cigars."},{"pos":"N-COUNT 可数名词","cn":"烟草店","en":"A tobacconist or a tobacconist's is a shop that sells things such as tobacco, cigarettes, and cigars."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has a shop that sells tobacco, cigarettes etc","cn":"烟草店老板﹐烟草经销商"},{"en":"a shop that sells tobacco, cigarettes etc","cn":"烟草店"}]},"media":{"uk":"media/ldoce/hwd/bre/4/tobacconist0205.mp3","us":"media/ldoce/hwd/ame/3/tobacconist.mp3"},"examples":[{"en":"There's a tobacconist's on the corner.","cn":"街角处有一家烟草店。"}],"oxford":{"phon":"təˈbækənɪst","pos":"noun","senses":[{"en":"a person who owns, manages or works in a shop selling cigarettes, tobacco for pipes, etc.","cn":"烟草店老板；烟草商"},{"en":"a shop that sells cigarettes, tobacco, etc.","cn":"烟草店","ex":{"en":"There's a tobacconist's on the corner.","cn":"街角处有一家烟草店。"}}]}},"townspeople":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"镇民;市民","en":"The townspeople of a town or city are the people who live there.","ex":{"en":"Food shortages forced many townspeople into the country to grow their own food.","cn":"食物短缺迫使很多市民到农村自己种粮食。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people who live in a particular town","cn":"全体镇民﹐全镇人"}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdetownspeople.mp3","us":"media/ldoce/hwd/ame/3/townspeople.mp3"},"examples":[{"en":"the proud townspeople of Semer Water","cn":"塞默－沃特城自豪的居民们"}],"oxford":{"phon":"ˈtaʊnzpiːpl","pos":"noun","senses":[{"en":"people who live in towns, not in the countryside; the people who live in a particular town","cn":"镇民；市民；城里人；（某一城镇的）居民","ex":{"en":"The farm holidays are for townspeople who would like a taste of the countryside.","cn":"农场假期适合那些想要体验乡村风情的城镇居民。"}}]}},"towrope":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(拖车的)拖索，拖缆","en":"A towrope is a strong rope that is used for pulling vehicles."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a rope or chain used for pulling vehicles along","cn":"拖索﹐拖缆﹐纤绳"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41towrope.mp3","us":"media/ldoce/hwd/ame/d/ld41towrope.mp3"}},"torrent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"急流;激流;洪流","en":"A torrent is a lot of water falling or flowing rapidly or violently.","ex":{"en":"Torrents of water gushed into the reservoir","cn":"急流涌入了水库。"}},{"pos":"N-COUNT 可数名词","cn":"(谩骂、问题等的)连发，迸发","en":"A torrent of abuse or questions is a lot of abuse or questions directed continuously at someone.","ex":{"en":"He turned round and directed a torrent of abuse at me.","cn":"他转过身来冲我劈头盖脸地骂了一通。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a continuous movement of water in a particular direction in the sea or in a river","cn":""},{"en":"a large amount of water that moves quickly and strongly in a particular direction","cn":""},{"en":"a large amount of water moving very quickly and strongly in a particular direction","cn":"湍流﹐急流"}]},"vocab":{"pos":"n","senses":[{"en":"A torrent is a heavy rain, or the flooding or wildly-running streams it causes, like the torrent that soaks everyone unlucky enough to be out on the street at that moment."}]},"collocations":{"phrases":["ADJ. raging, roaring, rushing After heavy rain, the little stream becomes a raging torrent. | foaming, muddy","PREP. in ~s The rain poured down in torrents.","PHRASES a torrent of rain/water 2 large amount of sth that comes suddenly","VERB + TORRENT unleash The sight of her father unleashed a torrent of emotions.","PREP. in a ~ Her pent-up anger was released in a torrent of words. | ~ of a torrent of abuse/criticism/tears"]},"media":{"uk":"media/ldoce/hwd/bre/a/torrent0205.mp3","us":"media/ldoce/hwd/ame/a/torrent.mp3"},"examples":[{"en":"After the winter rains, the stream becomes a raging torrent.","cn":"冬雨过后，溪流湍急。"},{"en":"The rain was coming down in torrents.","cn":"大雨如注。"}],"oxford":{"phon":"ˈtɒrənt","pos":"noun","senses":[{"en":"a large amount of water moving very quickly","cn":"急流；激流；湍流；洪流","ex":{"en":"After the winter rains, the stream becomes a raging torrent.","cn":"冬雨过后，溪流湍急。"}},{"en":"a large amount of something that comes suddenly and violently","cn":"迸发；连发；狂潮","ex":{"en":"a torrent of abuse/criticism","cn":"连珠炮似的谩骂／批评"}}]}},"toothbrush":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牙刷","en":"A toothbrush is a small brush that you use for cleaning your teeth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small brush that you use for cleaning your teeth","cn":"牙刷"}]},"media":{"img":["media/ldoce/img/toothbrush.jpg","media/thumb/toothbrush.jpg"],"uk":"media/ldoce/hwd/bre/8/toothbrush0205.mp3","us":"media/ldoce/hwd/ame/0/toothbrush.mp3"},"oxford":{"phon":"ˈtuːθbrʌʃ","pos":"noun","senses":[{"en":"a small brush for cleaning your teeth","cn":"牙刷"}]}},"toothpaste":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"牙膏","en":"Toothpaste is a thick substance which you put on your toothbrush and use to clean your teeth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick substance that you use to clean your teeth","cn":"牙膏"}]},"media":{"img":["media/ldoce/img/toothbrush.jpg","media/thumb/toothpaste.jpg"],"uk":"media/ldoce/hwd/bre/c/toothpaste0205.mp3","us":"media/ldoce/hwd/ame/1/toothpaste.mp3"},"oxford":{"phon":"ˈtuːθpeɪst","pos":"noun","senses":[{"en":"a substance that you put on a brush and use to clean your teeth","cn":"牙膏","ex":{"en":"a tube of toothpaste","cn":"一管牙膏"}}]}},"tombstone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"墓碑;墓石","en":"A tombstone is a large stone with words carved into it, which is placed on a grave."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stone that is put on a grave and shows the dead person’s name, dates of birth and death etc","cn":"墓石﹐墓碑"}]},"media":{"uk":"media/ldoce/hwd/bre/0/tombstone0205.mp3","us":"media/ldoce/hwd/ame/0/tombstone1.mp3"},"oxford":{"phon":"ˈtuːmstəʊn","pos":"noun","senses":[{"en":"a large, flat stone that lies over a grave (= where a dead person is buried) or stands at one end, that shows the name, age, etc. of the person buried there","cn":"墓碑"},{"en":"a town in the US state of Arizona known for its violent history. It was established in 1879 for workers in the local silver mines, and the famous gun fight at the OK Corral happened there in 1881. It nearly became a ghost town (= a town with no people), but tourists now come to see the OK Corral, Boot Hill and other Wild West places of interest.","cn":"墓碑：美国亚利桑那州一个以暴力历史闻名的城镇。它成立于1879年，当时是为当地银矿的工人服务的，1881年在OK畜栏发生了著名的枪战。它几乎变成了鬼城，但是现在游客来找OK了。畜栏，布特山和其他狂野西部景点。","pos":""}]}},"toneless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏声调的;平板的;单调的","en":"A toneless voice is dull and does not express any feeling.","ex":{"en":"'What shall we do?' Milton said again in a toneless voice.","cn":"“我们该怎么办？”米尔顿又用平板而单调的声音问道。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a toneless voice does not express any feelings 〔","cn":"声音〕单调的﹐平淡的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41toneless.mp3","us":"media/ldoce/hwd/ame/d/toneless.mp3"},"examples":[{"en":"‘I’m sorry,’ he said, in a flat toneless voice. “","cn":"对不起。”他以平淡的语气说道。"}],"oxford":{"phon":"ˈtəʊnləs","pos":"adjective","senses":[{"en":"not expressing any emotion or interest","cn":"单调的；呆板的；沉闷的"}]}},"topside":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（牛的）大腿肉","en":"Topside is a joint of beef that is cut from the upper part of the cow's leg. It is usually cooked by roasting or stewing."},{"pos":"ADV 副词","cn":"到(或向、在)甲板上","en":"On a ship, if you go topside, you go up onto the top deck.","ex":{"en":"He left the control station and went topside.","cn":"他离开控制台，走到甲板上。"}},{"pos":"N-COUNT 可数名词","cn":"(船体的)主甲板以上部分，水线以上部分","en":"The topside or topsides of a ship or boat are the top deck or the parts which you can see above the water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"high quality beef cut from the upper leg of the cow 〔","cn":"牛的〕米龙肉﹐针扒肉﹐上部圆腿肉"},{"en":"towards or onto the deck (= upper surface ) of a boat or ship","cn":"朝向甲板﹔在甲板上"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld44topside.mp3","us":"media/ldoce/hwd/ame/b/ld44topside.mp3"},"oxford":{"phon":"ˈtɒpsaɪd","pos":"noun","senses":[{"en":"a piece of beef that is cut from the upper part of the leg","cn":"牛臀肉"}]}},"toady":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谄媚者;马屁精","en":"If you refer to someone as a toady, you disapprove of them because they flatter or are pleasant towards an important or powerful person in the hope of getting some advantage from them."},{"pos":"VERB 动词","cn":"奉承;谄媚;拍马","en":"If you say that someone is toadying to an important or powerful person, you disapprove of them because they are flattering or being pleasant towards that person in the hope of getting some advantage from them.","ex":{"en":"They came backstage afterward, cooing and toadying to him.","cn":"她们随后来到后台，对他娇语谄媚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who pretends to like an important person and does things for them, so that that person will help them – used to show disapproval","cn":"谄媚者﹐马屁精〔含贬义〕"},{"en":"to pretend to like an important person and do things for them, so that they will help you – used to show disapproval","cn":"谄媚﹐奉承﹐拍马屁〔含贬义〕"}]},"vocab":{"pos":"n v","senses":[{"en":"You can call the kid who is always really nice to the teacher in hopes of getting a good grade a brown-noser or, if you want to sound clever, a toady ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41toady.mp3","us":"media/ldoce/hwd/ame/e/toady1.mp3"},"examples":[{"en":"toadying to the boss","cn":"拍老板的马屁"}],"oxford":{"phon":"ˈtəʊdi","pos":"noun","senses":[{"en":"a person who is too kind or shows too much respect towards somebody more important in order to gain their favour or help","cn":"谄媚者；马屁精"},{"en":"to treat somebody more important with special respect or kind treatment in order to gain their favour or help","cn":"拍马；奉承；谄媚","ex":{"en":"I’m not prepared to toady to him just to save my job.","cn":"我不准备仅仅为了保住我的工作而向他拍马屁。"},"pos":"verb"}]}},"tortilla":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(用玉米面和鸡蛋制成的)墨西哥玉米薄饼","en":"A tortilla is a piece of thin flat bread that first came from Mexico, and is made from corn and eggs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of thin flat Mexican bread made from corn or wheat flour","cn":"墨西哥薄饼"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tortilla.mp3","us":"media/ldoce/hwd/ame/f/tortilla.mp3"},"oxford":{"phon":"tɔːˈtiːə","pos":"noun","senses":[{"en":"a thin Mexican pancake made with corn (maize) flour or wheat flour, usually eaten hot and filled with meat, cheese, etc.","cn":"墨西哥薄馅饼（用玉米面或白面制成，通常加肉、奶酪等为馅，热食）"},{"en":"a Spanish dish made with eggs and potatoes fried together","cn":"西班牙土豆炒鸡蛋"}]}},"toehold":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"初步的立足点","en":"If you have a toehold in a situation, you have managed to gain an uncertain position or a small amount of power in it, which you hope will give you the opportunity to get a better or more powerful position.","ex":{"en":"Mitsubishi Motors were anxious to get a toehold in the European market.","cn":"三菱汽车急于在欧洲市场上取得初步的立足之地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your first involvement in a particular activity, from which you can develop and become stronger 〔","cn":"事业发展壮大的〕立脚点﹐起点"},{"en":"a place on a rock where you can put your foot when you are climbing 〔","cn":"攀岩时可落脚的〕立足点﹐踏足点"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41toehold.mp3","us":"media/ldoce/hwd/ame/9/toehold.mp3"},"examples":[{"en":"The firm is anxious to gain a toehold in Europe.","cn":"这家公司急于在欧洲找个立脚点。"},{"en":"The company has gained a toehold in the competitive computer market.","cn":"该公司在竞争激烈的电脑市场初步站稳了脚跟。"}],"oxford":{"phon":"ˈtəʊhəʊld","pos":"noun","senses":[{"en":"a position in a place or an activity that you hope will lead to more power or success","cn":"初步的地位；立足点","ex":{"en":"The firm is anxious to gain a toehold in Europe.","cn":"这家公司急于在欧洲找个立脚点。"}},{"en":"a very small hole or space on a rock face, just big enough to put your foot in when you are climbing","cn":"（攀登时可放进脚去的）小立足点，小支撑点"}]}},"tort":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"侵权行为","en":"A tort is something that you do or fail to do which harms someone else and for which you can be sued for damages."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an action that is wrong but not criminal and can be dealt with in a civil court of law 〔","cn":"不构成刑事犯罪的〕（民事）侵权行为"}]},"vocab":{"pos":"n","senses":[{"en":"If you sue a surgeon for operating on your left foot instead of the right one, you are filing a tort suit. Hopefully, you'll walk out of court victorious (on both feet)."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41tort.mp3","us":"media/ldoce/hwd/ame/2/tort.mp3"},"oxford":{"phon":"tɔːt","pos":"noun","senses":[{"en":"something wrong that somebody does to somebody else that is not criminal, but that can lead to action in a civil court","cn":"侵权行为（不构成刑事犯罪但可引起民事诉讼）"}]}},"tousled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)蓬乱的，凌乱的","en":"If you have tousled hair, it is untidy and looks as if it has not been brushed or combed."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tousled hair or a tousled appearance looks untidy 〔","cn":"头发〕蓬乱的﹔蓬头垢面的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdetousled.mp3","us":"media/ldoce/hwd/ame/a/laadtousled.mp3"},"examples":[{"en":"a boy with blue eyes and tousled hair","cn":"头发蓬乱的蓝眼睛男孩"},{"en":"She had just awakened, her eyes sleepy and her hair tousled .","cn":"她刚醒﹐睡眼惺忪﹐头发蓬乱。"}],"oxford":{"phon":"ˈtaʊzld","pos":"adjective","senses":[{"en":"untidy in an attractive way","cn":"（头发）蓬乱的","ex":{"en":"a boy with blue eyes and tousled hair","cn":"头发蓬乱的蓝眼睛男孩"}}]}},"toxic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有毒的;毒性的;引起中毒的","en":"A toxic substance is poisonous.","ex":{"en":"...the cost of cleaning up toxic waste","cn":"清除有毒废弃物的成本"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing physical harm – used especially about things that cause harm to your health, the environment etc","cn":""},{"en":"to have a harmful effect on someone or something. This phrase is very commonly used in everyday English when saying that something is harmful","cn":""},{"en":"used about things that cause permanent physical harm, or that have a bad effect in other ways, for example on people’s opinion of someone","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Danger! Hazardous! Do not eat! These are just some of the warnings you'll see on toxic substances — meaning stuff that's poisonous and even deadly."}]},"collocations":{"phrases":["VERBS be, stay | become | remain","ADV. extremely, highly, very | quite | potentially potentially toxic chemicals","PREP. to This chemical is toxic to many forms of life."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdetoxic.mp3","us":"media/ldoce/hwd/ame/3/toxic.mp3"},"examples":[{"en":"Many pesticides are highly toxic.","cn":"许多杀虫剂毒性很大。"},{"en":"toxic chemicals/fumes/gases/substances","cn":"有毒的化学品/烟雾/气体/物质"}],"oxford":{"phon":"ˈtɒksɪk","pos":"adjective","senses":[{"en":"containing poison; poisonous","cn":"有毒的；引起中毒的","ex":{"en":"toxic chemicals/fumes/gases/substances","cn":"有毒的化学品／烟雾／气体／物质"}},{"en":"a level of debt or high-risk investment that causes very serious problems for a bank or other financial institution","cn":"有毒的（指能引致银行或其他金融机构出现严重问题的高水平债务或高风险投资）"},{"en":"very unpleasant, especially in the way somebody likes to control and influence other people in a dishonest way","cn":"有害的；摆布人的；束缚人的","lab":"informal, disapproving，，","ex":{"en":"I felt trapped in this toxic relationship.","cn":"我觉得困在了这段危机四伏的关系之中。"}}]}},"topless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(女子)胸部裸露的","en":"If a woman goes topless, she does not wear anything to cover her breasts.","ex":{"en":"I wouldn't sunbathe topless if I thought I might offend anyone.","cn":"如果我觉得会冒犯任何人，我就不会袒露上身进行日光浴了。"}},{"pos":"ADJ 形容词","cn":"(表演中)女艺人裸露胸部的;(酒吧)雇佣袒胸女招待的","en":"A topless show or bar is one in which the female entertainers or staff do not wear anything to cover their breasts."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wearing any clothes or not covered by clothes – used especially when this seems rather shocking","cn":""},{"en":"to not be wearing any clothes. This phrase is very commonly used in everyday English instead of saying that someone is naked","cn":""},{"en":"used about feet, legs, arms etc that are not covered by clothes","cn":""}]},"collocations":{"phrases":["VERBS be, go, perform, pose, sunbathe Do you dare to go topless on the beach? There were rumours that she had posed topless for a magazine. "]},"media":{"uk":"media/ldoce/hwd/bre/6/topless0205.mp3","us":"media/ldoce/hwd/ame/d/topless.mp3"},"examples":[{"en":"a topless bar (= where the female staff are topless )","cn":"女招待不穿上装的酒吧"},{"en":"to sunbathe topless","cn":"裸露着上身沐日光浴"}],"oxford":{"phon":"ˈtɒpləs","pos":"adjective","senses":[{"en":"not wearing any clothes on the upper part of the body, especially so that the breasts are not covered","cn":"上身裸露的；不穿上装的","ex":{"en":"a topless model","cn":"上身裸露的模特儿"}},{"en":"without any clothes on the top part of the body, especially so that the breasts are not covered","cn":"上身裸露地；不穿上装地","ex":{"en":"to sunbathe topless","cn":"裸露上身晒日光浴"},"pos":"adverb"}]}},"tonnage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(船舶的)吨位","en":"The tonnage of a ship is its size or the amount of space that it has inside it for cargo."},{"pos":"N-VAR 可变名词","cn":"总吨数;总重量","en":"Tonnage is the total number of tons that something weighs, or the total amount that there is of it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the size of a ship or the amount of goods it can carry, shown in tonne s 〔","cn":"船舶的〕吨位"},{"en":"the total number of tonne s that something weighs 〔","cn":"以吨计的〕总重量﹐总吨数"}]},"vocab":{"pos":"n","senses":[{"en":"Tonnage is a type of tax. Tonnage is charged to the owners of ships that enter the United States, and the charge depends on how much their freight weighs."}]},"media":{"uk":"media/ldoce/hwd/bre/2/tonnage0205.mp3","us":"media/ldoce/hwd/ame/9/tonnage.mp3"},"examples":[{"en":"A huge tonnage of bombs has already been dropped on the area.","cn":"巨大吨数的炸弹已被投到该地区。"}],"oxford":{"phon":"ˈtʌnɪdʒ","pos":"noun","senses":[{"en":"the size of a ship or the amount it can carry, expressed in tons or tonnes","cn":"（表示船舶大小或载重量的）吨位"},{"en":"the total amount that something weighs","cn":"（某物的）总重量","ex":{"en":"the total tonnage of bombs dropped in the war","cn":"战争中投下的炸弹总吨位"}}]}},"toenail":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"趾甲","en":"Your toenails are the thin hard areas at the end of each of your toes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the hard part that covers the top of each of your toes","cn":"脚趾甲"}]},"collocations":{"phrases":["ADJ. ingrowing","VERB + TOENAIL clip, cut, trim","TOENAIL + NOUN clippings"]},"media":{"uk":"media/ldoce/hwd/bre/8/toenail0205.mp3","us":"media/ldoce/hwd/ame/3/toenail.mp3"},"oxford":{"phon":"ˈtəʊneɪl","pos":"noun","senses":[{"en":"the nail on a toe","cn":"趾甲"}]}},"torque":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"转矩;力矩;扭矩","en":"Torque is a force that causes something to spin around a central point such as an axle."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the force or power that makes something turn around a central point, especially in an engine 〔","cn":"尤指发动机的〕转矩"}]},"vocab":{"pos":"n","senses":[{"en":"If you have ever tightened a bolt with a wrench, or tried to get the lid off a jar of strawberry jam, then you have dealt with the concept of torque — a twisting action or a turning force."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41torque.mp3","us":"media/ldoce/hwd/ame/b/torque.mp3"},"oxford":{"phon":"tɔːk","pos":"noun","senses":[{"en":"a twisting force that causes machines, etc. to rotate (= turn around)","cn":"（使机器等旋转的）转矩","ex":{"en":"The more torque an engine has, the bigger the load it can pull in the same gear.","cn":"发动机的扭转力越大，同档情况下的牵引力就越大。"}}]}},"topcoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外套；轻便大衣;宽大衣","en":"A topcoat is a coat that you wear over your other clothes."},{"pos":"N-VAR 可变名词","cn":"(油漆等的)外涂层;外涂层漆","en":"A topcoat is the final layer of paint or varnish that is put on something. Topcoat is the type of paint or varnish that you use for the final layer."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the last layer of paint that you put on a surface 〔","cn":"油漆的〕外涂层"},{"en":"a warm long coat","cn":"长大衣"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41topcoat.mp3","us":"media/ldoce/hwd/ame/5/topcoat.mp3"},"oxford":{"phon":"ˈtɒpkəʊt","pos":"noun","senses":[{"en":"the last layer of paint put on a surface","cn":"（油漆等的）外涂层"},{"en":"an overcoat","cn":"大衣","lab":"old-fashioned"}]}},"towering":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"高耸的;参天的;屹立的","en":"If you describe something such as a mountain or cliff as towering, you mean that it is very tall and therefore impressive.","ex":{"en":"...towering cliffs of black granite which rise straight out of the sea.","cn":"从海里突兀而起的参天的黑色花岗岩峭壁"}},{"pos":"ADJ 形容词","cn":"杰出的;卓越的;强烈的","en":"If you describe someone or something as towering, you are emphasizing that they are impressive because of their importance, skill, or intensity.","ex":{"en":"He remains a towering figure in modern British politics","cn":"他在现代英国政坛上一直是位杰出的人物。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"measuring a long distance from the bottom to the top – used about mountains, walls, and buildings","cn":""},{"en":"high – used about people, trees, plants, and buildings. Tall is used especially about things that are high and narrow","cn":""},{"en":"very impressive because of being very big and tall – used about mountains, buildings, trees, and animals","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/towering0205.mp3","us":"media/ldoce/hwd/ame/6/towering.mp3"},"examples":[{"en":"towering cliffs","cn":"高耸的悬崖"},{"en":"a towering performance","cn":"出色的表演"}],"oxford":{"phon":"ˈtaʊərɪŋ","pos":"adjective","senses":[{"en":"extremely tall or high and therefore impressive","cn":"高大的；高耸的；屹立的","ex":{"en":"towering cliffs","cn":"高耸的悬崖"}},{"en":"of extremely high quality","cn":"卓越的；杰出的；出色的","ex":{"en":"a towering performance","cn":"出色的表演"}},{"en":"extremely strong","cn":"强烈的；激烈的","ex":{"en":"a towering rage","cn":"勃然大怒"}}]}},"tourniquet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"止血带","en":"A tourniquet is a strip of cloth that is tied tightly round an injured arm or leg in order to stop it bleeding."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a band of cloth that is twisted tightly around an injured arm or leg to stop it bleeding","cn":"止血带"}]},"vocab":{"pos":"n","senses":[{"en":"A tourniquet is a device used to control the flow of blood temporarily. If you cut your knee really badly, the doctor might put a tourniquet on your thigh before operating — to control the blood flow to your knee."}]},"media":{"uk":"media/ldoce/hwd/bre/b/tourniquet0205.mp3","us":"media/ldoce/hwd/ame/f/tourniquet.mp3"},"oxford":{"phon":"ˈtʊənɪkeɪ","pos":"noun","senses":[{"en":"a piece of cloth, etc. that is tied tightly around an arm or a leg to stop the loss of blood from a wound","cn":"（扎在手臂或腿上的）止血带","ex":{"en":"Apply a tight tourniquet above the wound.","cn":"在伤口上方绑紧止血带。"}}]}},"torrid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"炎热的;酷热的;灼热的","en":"Torrid weather is extremely hot and dry.","ex":{"en":"...the torrid heat of a Spanish summer.","cn":"西班牙夏天灼热的高温"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"狂热的;火热的;(情欲)不能自已的","en":"A torrid relationship or incident involves very strong emotions connected with love and sex.","ex":{"en":"She began a torrid love affair with a theatrical designer.","cn":"她和一位舞台设计师开始了一场狂热的恋情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"艰难的;难熬的","en":"If someone or something has a torrid time, they experience a lot of difficulties.","ex":{"en":"Seles, the victim of a death threat earlier this week, has had a torrid time during the Championships","cn":"塞勒斯在本周早些时候受到了死亡威胁，因此在锦标赛期间备受煎熬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"involving strong emotions, especially of sexual love 〔","cn":"尤指性爱〕热烈的﹐〔情欲〕炽烈的"},{"en":"torrid weather is very hot 〔","cn":"天气〕灼热的﹐炎热的"},{"en":"a torrid time is a very difficult one 〔","cn":"时期〕艰难的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you’re having a torrid romance, that means it's steamy and emotionally charged. If you’re listening to a torrid band, then you’re listening to a band that has a lot of energy."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41torrid.mp3","us":"media/ldoce/hwd/ame/f/torrid.mp3"},"examples":[{"en":"They face a torrid time in tonight's game.","cn":"他们在今晚的比赛中面临一场恶战。"},{"en":"a torrid love affair","cn":"狂热的恋情"}],"oxford":{"phon":"ˈtɒrɪd","pos":"adjective","senses":[{"en":"full of strong emotions, especially connected with sex and love","cn":"（尤指情爱）热烈的，狂热的，热情洋溢的","ex":{"en":"a torrid love affair","cn":"狂热的恋情"}},{"en":"very hot or dry","cn":"炎热而干燥的；酷热的；灼热的","lab":"formal","ex":{"en":"a torrid summer","cn":"酷热的夏季"}},{"en":"very difficult","cn":"艰难的","lab":"British English","ex":{"en":"They face a torrid time in tonight's game.","cn":"他们在今晚的比赛中面临一场恶战。"}}]}},"toddy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(在威士忌、朗姆酒或白兰地等烈酒中加入热水和糖调成的)热甜酒","en":"A toddy is a drink that is made by adding hot water and sugar to a strong alcoholic drink such as whisky, rum, or brandy.","ex":{"en":"...a hot toddy.","cn":"一杯热甜酒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hot drink made with whisky , sugar, and hot water","cn":"托地酒﹐热甜酒〔由威士忌加糖和热水调制而成〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41toddy.mp3","us":"media/ldoce/hwd/ame/c/toddy.mp3"},"oxford":{"phon":"ˈtɒdi","pos":"noun","senses":[{"en":"a drink made with strong alcohol, sugar, hot water and sometimes spices","cn":"托迪酒（用烈酒、糖、热水调配而成，有时还加香料）"}]}},"torturer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拷打者;拷问者;虐待者","en":"A torturer is someone who tortures people."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately hurt someone in order to force them to give you information, to punish them, or to be cruel","cn":""},{"en":"if a feeling or knowledge tortures you, it makes you suffer a lot mentally","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/torture_v0205.mp3","us":"media/ldoce/hwd/ame/6/torture1.mp3"},"examples":[{"en":"Political opponents of the regime may be tortured.","cn":""},{"en":"Rachel sat alone for hours at home, tortured by jealousy.","cn":""}],"oxford":{"phon":"ˈtɔːtʃərə(r)","pos":"noun","senses":[{"en":"a person who causes somebody severe physical or mental pain in order to punish them or make them give information","cn":"酷刑者：为了惩罚或使他们提供信息而引起某人严重的身体或精神痛苦的人"}]}},"touchy-feely":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"煽情的;矫情的;肉麻的","en":"If you describe something as touchy-feely, you mean that it involves people expressing emotions such as love and affection openly in a way which you find embarrassing and silly.","ex":{"en":"...a touchy-feely song about making your life worth living.","cn":"一支让生活更有价值的煽情歌曲"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too concerned with feelings and emotions, rather than with facts or actions","cn":"过分多愁善感的﹐情绪化的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/touchy_feely0205.mp3","us":"media/ldoce/hwd/ame/3/laadtouchy-feely.mp3"},"examples":[{"en":"a touchy-feely drama","cn":"伤感的戏剧"}],"oxford":{"phon":"ˌtʌtʃi ˈfiːli","pos":"adjective","senses":[{"en":"expressing emotions too openly","cn":"露骨地表示情感的","ex":{"en":"He was one of those touchy-feely guys who’s always calling home to speak to the kids.","cn":"他是那些总是打电话回家和孩子们说话的敏感人物之一。"}}]}},"toothpick":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牙签","en":"A toothpick is a small stick which you use to remove food from between your teeth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small pointed stick that you can use for removing bits of food that are stuck between your teeth","cn":"牙签"}]},"media":{"uk":"media/ldoce/hwd/bre/8/toothpick0205.mp3","us":"media/ldoce/hwd/ame/f/toothpick.mp3"},"oxford":{"phon":"ˈtuːθpɪk","pos":"noun","senses":[{"en":"a short pointed piece of wood or plastic used for removing bits of food from between the teeth","cn":"牙签"}]}},"tour":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巡回访问;巡回演出；巡回比赛","en":"A tour is an organized trip that people such as musicians, politicians, or theatre companies go on to several different places, stopping to meet people or perform.","ex":{"en":"The band are currently on a two-month tour of Europe","cn":"乐队目前正在欧洲进行为期两个月的巡回演出。"}},{"pos":"VERB 动词","cn":"作巡回活动(或演出、比赛)","en":"When people such as musicians, politicians, or theatre companies tour, they go on a tour, for example in order to perform or to meet people.","ex":{"en":"A few years ago they toured the country in a roadshow","cn":"几年前他们在全国作了巡回演出。"}},{"pos":"N-COUNT 可数名词","cn":"旅行;游历;观光","en":"A tour is a journey during which you visit several places that interest you.","ex":{"en":"It was week five of my tour of the major cities of Europe.","cn":"那是我在欧洲主要城市游历的第 5 周。"}},{"pos":"N-COUNT 可数名词","cn":"（短时间的）游览，参观,观光","en":"A tour is a short trip that you make round a place, for example round a historical building, so that you can look at it.","ex":{"en":"...a guided tour of a ruined Scottish castle.","cn":"由导游带领游览苏格兰荒废城堡"}},{"pos":"VERB 动词","cn":"在…旅行;游历;游览;参观","en":"If you tour a place, you go on a journey or trip round it.","ex":{"en":"You can also tour the site on modern coaches equipped with videos","cn":"您也可以乘坐配有视频设备的现代化长途汽车游览那处遗址。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when you travel from one place to another – used especially about travelling a long distance, or travelling somewhere regularly","cn":""},{"en":"a journey to visit a place","cn":""},{"en":"a journey for pleasure, during which you visit several different towns, areas etc","cn":"旅游﹐游览﹐观光"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Use the noun tour to describe a route taken while sight-seeing or the act of experiencing a place, like a tour of Italy in which travelers tour museums and churches."}]},"collocations":{"phrases":["ADJ. foreign, international, national, nationwide, overseas, provincial, world | American, UK, etc. | two-city, three-country, etc. The grou","VERB + TOUR do, go on, make, undertake | embark on, set off on","TOUR + NOUN company, operator | date, schedule Phone for details of the band's tour dates. | leader, manager Our tour leaders are all fluent","PREP. on (a) ~ We met a group of cyclists on a tour in the Lake District. The band is currently on tour in the States. | ~ of I'd like to do","PHRASES tour of duty The soldiers were returning from a six-month tour of duty in Northern Ireland. 2 short visit","ADJ. brief, quick, lightning Our host gave us a quick tour of the house. | extensive | grand (humorous) Come on, I'll give you the grand tou","VERB + TOUR give sb, take sb on | do, make I made a lightning tour of the office to say goodbye.","TOUR + NOUN guide"]},"media":{"uk":"media/ldoce/hwd/bre/4/tour_v0205.mp3","us":"media/ldoce/hwd/ame/4/tour1.mp3"},"examples":[{"en":"The band is currently on a nine-day tour of France.","cn":"这支乐队目前正在法国进行九天的巡回演出。"},{"en":"We were given a guided tour (= by sb who knows about the place) of the palace.","cn":"我们由导游带领参观游览了那座宫殿。"}],"oxford":{"phon":"tʊə(r)","pos":"noun","senses":[{"en":"a journey made for pleasure during which several different towns, countries, etc. are visited","cn":"旅行；旅游","lab":"British English","ex":{"en":"a walking/sightseeing/bus tour","cn":"徒步／观光／乘公交车旅行"}},{"en":"an act of walking around a town, building, etc. in order to visit it","cn":"游览；参观；观光","ex":{"en":"We were given a guided tour (= by somebody who knows about the place) of the palace.","cn":"我们由导游带领参观游览了那座宫殿。"}},{"en":"an official series of visits made to different places by a sports team, an orchestra, an important person, etc.","cn":"巡回比赛（或演出等）；巡视","ex":{"en":"The band is currently on a nine-day tour of France.","cn":"这支乐队目前正在法国进行九天的巡回演出。"}},{"en":"a period of time when somebody is serving in the military or as a diplomat in a particular place","cn":"巡回演出：一段时期，有人在某个地方服兵役或当外交官","ex":{"en":"He served tours all over the world during his 35-year career.","cn":"在其 35 年的职业生涯中他在世界各地任过职。"}},{"en":"to travel around a place, for example on holiday, or to perform, to advertise something, etc.","cn":"（在…）旅游；（在…）巡回演出（或做宣传广告等）","ex":{"en":"He toured America with his one-man show.","cn":"他在美国进行了个人巡回演出。"},"pos":"verb"}]}},"toleration":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"willingness to allow people to believe what they want without being criticized or punished","cn":"容忍（精神）﹔宽容（态度）"}]},"collocations":{"phrases":["ADJ. religious","QUANT. degree, measure Religious minorities were allowed a wide measure of toleration.","PREP. ~ for He preached toleration for all religions."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41toleration.mp3","us":"media/ldoce/hwd/ame/a/toleration.mp3"},"examples":[{"en":"religious toleration","cn":"宗教上的宽容"}],"oxford":{"phon":"ˌtɒləˈreɪʃn","pos":"noun","senses":[{"en":"the fact of being willing to allow something that you do not like or agree with to happen or continue","cn":"忍受；容忍；宽容；容许","ex":{"en":"religious toleration","cn":"宗教上的宽容"}}]}},"toothless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有牙齿的","en":"You use toothless to describe a person or their smile when they have no teeth."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无实权的;不起作用的","en":"If you describe something such as an official group or a law as toothless, you mean it has no real power and is not effective.","ex":{"en":"In his view, the Commission remains a toothless and ineffectual body.","cn":"在他看来，委员会仍然是一个没有实权、不起作用的机构。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is toothless has no teeth","cn":"没有牙齿的"},{"en":"an organization that is toothless has no power to make people obey its rules 〔","cn":"机构〕无效力的﹐无约束力的﹐不起作用的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/toothless0205.mp3","us":"media/ldoce/hwd/ame/c/toothless.mp3"},"examples":[{"en":"She gave us a toothless grin.","cn":"她张开没牙的嘴巴对我们笑了笑。"},{"en":"a toothless old man","cn":"没牙的老头"}],"oxford":{"phon":"ˈtuːθləs","pos":"adjective","senses":[{"en":"having no teeth","cn":"无牙的；无齿的","ex":{"en":"a toothless old man","cn":"没牙的老头儿"}},{"en":"having no power or authority","cn":"人微言轻的；没有权威的；不起作用的","ex":{"en":"The local council has often been criticized for being a toothless institution.","cn":"地方议会经常被批评为一个没有权力的机构。"}}]}},"tortuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"曲折的;弯弯曲曲的","en":"A tortuous road is full of bends and twists.","ex":{"en":"The only road access is a tortuous mountain route.","cn":"唯一的陆路通道是一条蜿蜒的山道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"转弯抹角的;绕圈子的;迂回复杂的","en":"A tortuous process or piece of writing is very long and complicated.","ex":{"en":"...these long and tortuous negotiations aimed at ending the conflict","cn":"旨在结束冲突的漫长而曲折的谈判"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a road, track, coast etc curves , it has a long smooth bend in it","cn":""},{"en":"if a road, track, or river winds , it has many smooth bends and is usually very long","cn":""},{"en":"if a track, road, or stream twists it has many sharp bends and changes direction many times","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Tortuous means twisting or complicated. \"James Bond drove his custom BMW 120 mph on the road that was tortuous in its twists and turns. He had to stop the evil madman's plan for world domination that was so tortuous even 007 could not understand it.\""}]},"media":{"uk":"media/ldoce/hwd/bre/1/tortuous0205.mp3","us":"media/ldoce/hwd/ame/c/tortuous.mp3"},"examples":[{"en":"the long, tortuous process of negotiating peace","cn":"漫长而曲折的和平谈判过程"},{"en":"tortuous language","cn":"含混不清的语言"}],"oxford":{"phon":"ˈtɔːtʃuəs","pos":"adjective","senses":[{"en":"not simple and direct; long, complicated and difficult to understand","cn":"拐弯抹角的；含混不清的；冗长费解的","lab":"usually disapproving","ex":{"en":"tortuous language","cn":"含混不清的语言"}},{"en":"full of bends","cn":"弯弯曲曲的；逶迤的；蜿蜒的","ex":{"en":"a tortuous mountain track","cn":"一条曲折的山路"}}]}},"toffee":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"太妃糖；奶糖","en":"Toffee is a sticky sweet that you chew. It is made by boiling sugar and butter together with water."},{"pos":"N-COUNT 可数名词","cn":"(一颗)太妃糖；(一块)奶糖","en":"A toffee is an individual piece of toffee."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sticky sweet brown substance that you can eat, made by boiling sugar, water, and butter together, or a piece of this substance （","cn":"一块）太妃糖"},{"en":"to be very bad at doing something","cn":"根本干不了某事﹐完全无法胜任某事"}]},"media":{"uk":"media/ldoce/hwd/bre/b/toffee0205.mp3","us":"media/ldoce/hwd/ame/b/toffee.mp3"},"examples":[{"en":"He can't dance for toffee!","cn":"他根本不会跳舞！"},{"en":"He can’t sing for toffee!","cn":"他根本就不会唱歌！"}],"oxford":{"phon":"ˈtɒfi","pos":"noun","senses":[{"en":"a sticky sweet made by heating sugar, butter and water together and allowing it to cool","cn":"太妃糖；乳脂糖"}]}},"topographical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地形的;地貌的","en":"A topographical survey or map relates to or shows the physical features of an area of land, for example its hills, valleys, and rivers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the science of describing an area of land, or making maps of it","cn":""},{"en":"the shape of an area of land, including its hills, valleys etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/topography0205.mp3","us":"media/ldoce/hwd/ame/d/topography.mp3"},"examples":[{"en":"a topographical map/feature","cn":"地形图；地貌特征"}],"oxford":{"phon":"ˌtɒpəˈɡræfɪkl","pos":"adjective","senses":[{"en":"connected with the physical features of an area of land, especially the position of its rivers, mountains, etc.","cn":"地形；地貌；地势；地形学","ex":{"en":"a topographical map/feature","cn":"地形图；地貌"}}]}},"tomahawk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"印第安战斧","en":"A tomahawk is a small light axe that is used by Native American peoples."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light axe used by Native Americans 〔","cn":"北美印第安人用的〕轻斧﹐战斧"}]},"media":{"img":["media/ldoce/img/tomahawk.jpg"],"uk":"media/ldoce/hwd/bre/7/ld41tomahawk.mp3","us":"media/ldoce/hwd/ame/a/tomahawk.mp3"},"oxford":{"phon":"ˈtɒməhɔːk","pos":"noun","senses":[{"en":"a light axe used by native North Americans","cn":"印第安战斧（美洲土著的一种武器）"}]}},"toff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"上等人;有钱人","en":"If you refer to someone as a toff, you are saying in an unkind way that they come from the upper classes or are very rich."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is rich or has a high social position – used to show disapproval","cn":"有钱人﹐上流人士〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/toff0205.mp3","us":"media/ldoce/hwd/ame/e/ld41toff.mp3"},"oxford":{"phon":"tɒf","pos":"noun","senses":[{"en":"a way of referring to somebody from a high social class that shows that you do not approve of them","cn":"纨绔子弟；花花公子","ex":{"en":"What are you doing dressed up like a toff?","cn":"你打扮得像个贵人干什么呢？"}}]}},"toxin":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"毒素","en":"A toxin is any poisonous substance produced by bacteria, animals, or plants.","ex":{"en":"Experts have linked this condition to a build-up of toxins in the body…","cn":"专家已把这一病症与体内毒素的积累联系起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a poisonous substance, especially one that is produced by bacteria and causes a particular disease","cn":"毒素〔尤指细菌产生的致病物质〕"}]},"vocab":{"pos":"n","senses":[{"en":"A toxin is an organic poison — it’s made by plants and animals. Toxins make people sick. If your appendix burst, toxins are released into your blood stream. Also breathing in a toxin like ricin will make you very ill."}]},"media":{"uk":"media/ldoce/hwd/bre/9/toxin0205.mp3","us":"media/ldoce/hwd/ame/b/tocsin.mp3"},"oxford":{"phon":"ˈtɒksɪn","pos":"noun","senses":[{"en":"a poisonous substance, especially one that is produced by bacteria in plants and animals","cn":"毒素（尤指生物体内细菌产生的毒物）","ex":{"en":"The algae kills off plant and animal life and, in some cases, produces dangerous toxins.","cn":"藻类会大量杀死生物体，并在某些情况下产生危险的毒素。"}}]}},"toothsome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可口的;美味的","en":"If you describe food as toothsome, you mean that it tastes very good.","ex":{"en":"...the toothsome honey-sweetened gingerbread.","cn":"加有蜂蜜的美味姜饼"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tasting very good","cn":"味道好的﹐美味可口的"}]},"vocab":{"pos":"adj","senses":[{"en":"Toothsome describes something that's absolutely delicious, like a bite of your famous flourless chocolate cake."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41toothsome.mp3","us":"media/ldoce/hwd/ame/d/toothsome.mp3"},"examples":[{"en":"an attractive and toothsome dish","cn":"美味诱人的菜肴"}],"oxford":{"phon":"ˈtuːθsəm","pos":"adjective","senses":[{"en":"tasting good","cn":"美味的；可口的"}]}},"townie":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(对乡村一无所知的)城里人","en":"If someone who lives in the countryside refers to someone from a town or city as a townie, they disapprove of that person because they think they have no knowledge of the countryside or country life."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who lives in a town or city and does not know anything about life in the countryside 〔","cn":"对乡村生活一无所知的〕城里人"}]},"media":{"uk":"media/ldoce/hwd/bre/8/townie0205.mp3","us":"media/ldoce/hwd/ame/3/townie.mp3"},"oxford":{"phon":"ˈtaʊni","pos":"noun","senses":[{"en":"a person who lives in or comes from a town or city, especially somebody who does not know much about life in the countryside","cn":"（尤指不了解乡村生活的）城里人","ex":{"en":"Country life isn’t as idyllic as townies imagine.","cn":"乡村生活并不像城里人想象的那样田园诗般。"}},{"en":"a person who lives in a town with a college or university but does not attend it or work at it","cn":"（大学城中不上大学或不在大学工作的）居民，老百姓","lab":"North American English"},{"en":"a member of a group of young people who live in a town, all wear similar clothes, such as tracksuits and caps, and often behave badly","cn":"阿飞，城市小流氓（穿着类似，行为不端）","lab":"British English, informal，，"}]}},"toothy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(笑容)露齿的","en":"A toothy smile is one in which a person shows a lot of teeth."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a smile in which you show a lot of teeth","cn":"露齿的笑"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41toothy.mp3","us":"media/ldoce/hwd/ame/2/toothy.mp3"},"examples":[{"en":"He grinned a wide, toothy grin.","cn":"他嘴咧得很大﹐露出牙齿笑着。"}],"oxford":{"phon":"ˈtuːθi","pos":"adjective","senses":[{"en":"a toothy smile shows a lot of teeth","cn":"（笑时）露齿的，多齿的"}]}},"touchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易怒的;过于敏感的;暴躁的","en":"If you describe someone as touchy, you mean that they are easily upset, offended, or irritated.","ex":{"en":"She is very touchy about her past","cn":"她对自己的过去非常敏感。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"棘手的;难办的;需谨慎处理的","en":"If you say that something is a touchy subject, you mean that it is a subject that needs to be dealt with carefully and in a sensitive way, because it might upset or offend people.","ex":{"en":"...the touchy question of political reform.","cn":"政治改革这一棘手问题"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easily annoyed by unimportant things, especially because you already feel bad-tempered about something","cn":""},{"en":"someone who is touchy is easily offended and made angry by things, so you have to be careful what you say to them","cn":""},{"en":"an old person who is crotchety becomes angry about unimportant things and complains a lot","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are touchy are hard to handle — not literally, but to talk about. Touchy subjects make people upset."}]},"media":{"uk":"media/ldoce/hwd/bre/f/touchy0205.mp3","us":"media/ldoce/hwd/ame/5/touchy.mp3"},"examples":[{"en":"He's a little touchy about his weight.","cn":"他有点忌讳别人说他胖。"},{"en":"She is very touchy about her past.","cn":"她对她的过去十分敏感。"}],"oxford":{"phon":"ˈtʌtʃi","pos":"adjective","senses":[{"en":"easily upset or offended","cn":"易烦恼；易生气；易怒","g":"[not usually before noun]","ex":{"en":"He's a little touchy about his weight.","cn":"他有点忌讳别人说他胖。"}},{"en":"that may upset or offend people and should therefore be dealt with carefully","cn":"敏感的；需要小心处理的；棘手的","g":"[usually before noun]","ex":{"en":"I can’t understand why her resignation is still such a touchy subject.","cn":"我不明白为什么她的辞职仍然是一个敏感话题。"}}]}},"towelling":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毛巾布;毛巾料","en":"Towelling is a kind of fairly thick soft cloth that is used especially for making towels.","ex":{"en":"...a towelling bathrobe.","cn":"毛巾布浴袍"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"thick soft cloth, used especially for making towels or bathrobe s","cn":"毛巾布"}]},"media":{"uk":"media/ldoce/hwd/bre/b/towelling0205.mp3","us":"media/ldoce/hwd/ame/4/ld41towelling.mp3"},"examples":[{"en":"a towelling bathrobe","cn":"毛巾布浴衣"},{"en":"a towelling robe","cn":"一件毛巾布睡袍"}],"oxford":{"phon":"ˈtaʊəlɪŋ","pos":"noun","senses":[{"en":"a type of soft cotton cloth that has a surface covered with raised loops of thread, used especially for making towels","cn":"毛巾布；毛巾料","ex":{"en":"a towelling bathrobe","cn":"毛巾布浴衣"}}]},"base":"towel"},"toad":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蟾蜍;癞蛤蟆","en":"A toad is a creature which is similar to a frog but which has a drier skin and spends less time in water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small animal that looks like a large frog and lives mostly on land","cn":"蟾蜍﹐癞蛤蟆"}]},"media":{"img":["media/ldoce/img/toad.jpg","media/thumb/toad.jpg"],"uk":"media/ldoce/hwd/bre/5/toad0205.mp3","us":"media/ldoce/hwd/ame/9/toad.mp3"},"oxford":{"phon":"təʊd","pos":"noun","senses":[{"en":"a small animal like a frog but with a drier and less smooth skin, that lives on land but breeds (= produces young) in water (= is an amphibian)","cn":"蟾蜍；癞蛤蟆"},{"en":"an unpleasant person","cn":"讨厌的人；恶心的人","lab":"informal, disapproving，，","ex":{"en":"You repulsive little toad!","cn":"你这个讨厌的癞蛤蟆！"}},{"en":"one of the main characters in The Wind in the Willows by Kenneth Grahame. Toad (an animal like a frog) is a very lively character who owns a big house. He becomes very enthusiastic about cars but is sent to prison for driving in a dangerous way. He escapes dressed as a woman and is then helped by his friends to get back into his home, which has been captured by his enemies.","cn":"蟾蜍：肯尼斯·格雷厄姆（Kenneth Grahame）的《柳树风》中的主要人物之一。蟾蜍（一种像青蛙的动物）是一个非常活泼的人物，拥有一间大房子。他对汽车非常热心，但因危险驾驶而被判入狱。他穿着女人的衣服逃脱，然后在朋友的帮助下回到自己的家中，被他的敌人俘获。","pos":""}]}},"touchstone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"试金石;验证手段;检验标准","en":"If you use one thing as a touchstone of another, you use it as a test or standard by which you judge the second thing.","ex":{"en":"Job security has become the touchstone of a good job for many employees.","cn":"工作稳定性已成为很多员工衡量一份工作好坏的标准。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something used as a test or standard","cn":"试金石﹔检验标准"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun touchstone to describe a basis for comparison. For example, a filmmaker's touchstone might be her all-time favorite movie; she wants her movie to be that good or similar to it in some way."}]},"media":{"uk":"media/ldoce/hwd/bre/d/touchstone0205.mp3","us":"media/ldoce/hwd/ame/9/touchstone.mp3"},"examples":[{"en":"the touchstone for quality","cn":"检验质量的标准"},{"en":"Pupil behaviour was seen as ‘the touchstone of quality’ of the school system.","cn":"学生的行为被看作学校制度的“质量试金石”。"}],"oxford":{"phon":"ˈtʌtʃstəʊn","pos":"noun","senses":[{"en":"something that provides a standard against which other things are compared and/or judged","cn":"试金石；检验标准","ex":{"en":"the touchstone for quality","cn":"检验质量的标准"}}]}},"tore":{"lemma":"tear","media":{"uk":"media/ldoce/hwd/bre/2/tore0205.mp3","us":"media/ldoce/hwd/ame/e/ld41tore.mp3"}},"toothache":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"牙痛","en":"Toothache is pain in one of your teeth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when part of your body hurts","cn":""},{"en":"a pain that continues for a long time but is not very sharp","cn":""},{"en":"a continuous pain in a part of your body","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/toothache0205.mp3","us":"media/ldoce/hwd/ame/9/toothache.mp3"},"examples":[{"en":"( BrE ) I've got toothache.","cn":"我牙疼。"},{"en":"( NAmE, BrE ) I've got a toothache.","cn":"我牙疼。"}],"oxford":{"phon":"ˈtuːθeɪk","pos":"noun","senses":[{"en":"a pain in your teeth or in one tooth","cn":"牙痛","lab":"British English","ex":{"en":"I've got toothache.","cn":"我牙疼。"}}]}},"toss":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扔；抛；掷","en":"If you toss something somewhere, you throw it there lightly, often in a rather careless way.","ex":{"en":"He screwed the paper into a ball and tossed it into the fire","cn":"他把纸揉成一团扔进火里。"}},{"pos":"VERB 动词","cn":"(常表示愤怒或轻蔑地)甩(头或头发)","en":"If you toss your head or toss your hair, you move your head backwards, quickly and suddenly, often as a way of expressing an emotion such as anger or contempt.","ex":{"en":"'I'm sure I don't know.' Cook tossed her head","cn":"“我确信我不知道。”库克一甩头说。"}},{"pos":"VERB 动词","cn":"掷(硬币以决定)","en":"In sports and informal situations, if you decide something by tossing a coin, you spin a coin into the air and guess which side of the coin will face upwards when it lands.","ex":{"en":"We tossed a coin to decide who would go out and buy the buns.","cn":"我们掷硬币决定谁出去买小圆面包。"}},{"pos":"N-SING 单数名词","cn":"掷硬币决定","en":"The toss is a way of deciding something, such as who is going to go first in a game, that consists of spinning a coin into the air and guessing which side of the coin will face upwards when it lands.","ex":{"en":"Bangladesh won the toss and decided to bat first.","cn":"孟加拉国队掷硬币赢了，决定先击球。"}},{"pos":"VERB 动词","cn":"使摇动;使颠簸","en":"If something such as the wind or sea tosses an object, it causes it to move from side to side or up and down.","ex":{"en":"The seas grew turbulent, tossing the small boat like a cork","cn":"海浪变得汹涌澎湃，把小船像漂浮的软木塞一样抛来甩去。"}},{"pos":"VERB 动词","cn":"（在液体中）轻轻搅拌(食物)","en":"If you toss food while preparing it, you put pieces of it into a liquid and lightly shake them so that they become covered with the liquid.","ex":{"en":"Do not toss the salad until you're ready to serve","cn":"到快上菜时再轻轻搅拌色拉。"}},{"pos":"PHRASE 短语","cn":"为不重要的事争论不休","en":"If you say that someone argues the toss, you are criticizing them for continuing to argue for longer than is necessary about something that is not very important.","ex":{"en":"They were still arguing the toss about the first goal","cn":"他们仍在为第一个进球争论不休。"}},{"pos":"PHRASE 短语","cn":"介意，在乎","en":"If you say that you do not give a toss about someone or something, you are emphasizing that you do not care about them at all.","ex":{"en":"Well, who gives a toss about sophistication anyway?","cn":"嗯，不管怎样，谁会在意高雅时髦呢？"}},{"pos":"PHRASE 短语","cn":"辗转反侧;翻来覆去","en":"If you toss and turn, you keep moving around in bed and cannot sleep properly, for example because you are ill or worried.","ex":{"en":"You feel as if you've been tossing and turning all night, and wake up feeling worn out.","cn":"感觉就像整夜翻来覆去睡不着、醒来时浑身疲惫一样。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as a ball or stone move quickly through the air using your hand","cn":""},{"en":"to throw something, especially in a careless way without using much effort","cn":""},{"en":"to throw something with a lot of force","cn":""}]},"collocations":{"phrases":["ADV. carelessly, casually She picked up the package and casually tossed it into her bag. | aside, away, back, over She tossed back her blond","PREP. into, out of, to He tossed the letter over to me. 2 keep moving up and down/from side to side","ADV. restlessly She tossed about restlessly all night with a high fever. | about He was tossed about in his boat.","PHRASES toss and turn He tossed and turned all night, unable to sleep. 3 cover food in a sauce","ADV. gently, lightly | well | together","PREP. in Toss the vegetables lightly in olive oil."]},"media":{"uk":"media/ldoce/hwd/bre/3/toss_n0205.mp3","us":"media/ldoce/hwd/ame/7/toss1.mp3"},"examples":[{"en":"Drain the pasta and toss it in melted butter.","cn":"把面条的汤控干，在溶化了的黄油里搅拌。"},{"en":"( figurative ) He had to toss up between (= decide between) paying the rent or buying food.","cn":"他不得不在付房租和买食品之间作出决定。"}],"oxford":{"phon":"tɒs","pos":"verb","senses":[{"en":"to throw something lightly or carelessly","cn":"（轻轻或漫不经心地）扔，抛，掷","g":"[transitive]","lab":"especially British English","sc":"throw","ex":{"en":"I tossed the book aside and got up.","cn":"我把书丢在一边，站了起来。"}},{"en":"to throw a coin in the air in order to decide something, especially by guessing which side is facing upwards when it lands","cn":"（为…）掷硬币决定；掷币猜边儿","g":"[transitive, intransitive]","lab":"especially British English","sc":"coin","ex":{"en":"Let's toss a coin.","cn":"咱们掷硬币猜边儿决定吧。"}},{"en":"to move your head suddenly upwards, especially to show that you are annoyed or impatient","cn":"仰，向上甩（头，以表示恼怒或不耐烦）","g":"[transitive]","sc":"your head","ex":{"en":"She just tossed her head and walked off.","cn":"她头一甩，走开了。"}},{"en":"to move or make somebody/something move from side to side or up and down","cn":"（使）摇摆，挥动，颠簸","g":"[intransitive, transitive]","sc":"side to side/up and down","ex":{"en":"Branches were tossing in the wind.","cn":"树枝随风摇曳。"}},{"en":"to shake or turn food in order to cover it with oil, butter, etc.","cn":"摇匀；翻动（以沾油、奶酪等）","g":"[transitive]","sc":"in cooking","ex":{"en":"Drain the pasta and toss it in melted butter.","cn":"把面条的汤控干，在融化了的黄油里搅拌。"}},{"en":"to throw a pancake upwards so that it turns over in the air and lands back in the frying pan so you can fry the other side","cn":"把（煎饼）颠起翻面","g":"[transitive]","lab":"British English","sc":"in cooking"},{"en":"an act of throwing a coin in the air in order to decide something","cn":"掷硬币决定","sc":"of coin","ex":{"en":"The final result was decided on/by the toss of a coin.","cn":"最后的结果是掷硬币决定的。"},"pos":"noun"},{"en":"an act of moving your head suddenly upwards, especially to show that you are annoyed or impatient","cn":"向上甩头，猛仰头（尤指表示恼怒或不耐烦）","sc":"of head","ex":{"en":"She dismissed the question with a toss of her head.","cn":"她一扬头，对这一问题不予理睬。"},"pos":"noun"},{"en":"an act of throwing something, especially in a competition or game","cn":"（尤指比赛或游戏中）投掷","sc":"throw","ex":{"en":"a toss of 10 metres","cn":"10 米远的投掷"},"pos":"noun"}]}},"tornado":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"龙卷风；大旋风","en":"A tornado is a violent wind storm consisting of a tall column of air which spins round very fast and causes a lot of damage."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A tornado is a violent windstorm in the shape of a funnel cloud that reaches to the ground. If a tornado is coming, you’ll want to take cover."}]},"collocations":{"phrases":["TORNADO + VERB hit sth, strike sth The town was hit by a tornado last night. | damage sth, destroy sth, devastate sth","PREP. in a/the ~ The building was badly damaged in a tornado."]},"media":{"uk":"media/ldoce/hwd/bre/9/tornado0205.mp3","us":"media/ldoce/hwd/ame/8/tornado.mp3"},"oxford":{"phon":"tɔːˈneɪdəʊ","pos":"noun","senses":[{"en":"a violent storm with very strong winds that move in a circle. There is often also a long cloud that is narrower at the bottom than the top.","cn":"龙卷风；旋风","lab":"North American English","ex":{"en":"Tornadoes ripped into the southern United States yesterday.","cn":"昨天龙卷风袭击了美国南部地区。"}},{"en":"a British military aircraft, used until 2019 by the Royal Air Force. The Tornado was both a fighter and a bomber .","cn":"龙卷风：英国军用飞机，一直被皇家空军使用到2019年。龙卷风既是战斗机（是用来攻击其他飞机的飞机），也是轰炸机（是携带炸弹的飞机）。"}]}},"topsy-turvy":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"混乱的;乱七八糟的;颠三倒四的","en":"Something that is topsy-turvy is in a confused or disorganized state.","ex":{"en":"The world has turned topsy-turvy in my lifetime.","cn":"在我的一生中世界已经变得一团糟。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in a state of complete disorder or confusion","cn":"乱七八糟的﹐一团糟的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/topsy_turvy0205.mp3","us":"media/ldoce/hwd/ame/5/topsy-turvy.mp3"},"examples":[{"en":"Everything's topsy-turvy in my life at the moment.","cn":"现在我的生活全都被打乱了。"},{"en":"He left his room all topsy-turvy.","cn":"他把房间弄得一团糟。"}],"oxford":{"phon":"ˌtɒpsi ˈtɜːvi","pos":"adjective","senses":[{"en":"in a state in which nothing is certain and everything is very confused","cn":"乱七八糟的；杂乱无章的；颠三倒四的","ex":{"en":"Everything's topsy-turvy in my life at the moment.","cn":"现在我的生活全都被打乱了。"}}]}},"tog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"托格(测定毯子、被子保暖度的官方计量单位)","en":"A tog is an official measurement that shows how warm a blanket or quilt is.","ex":{"en":"The range of tog values has been extended to 15 togs.","cn":"托格值的范围已经扩大至 15 托格。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指为某一特殊目的所穿的)衣服","en":"Togs are clothes, especially ones for a particular purpose.","ex":{"en":"The photograph showed him wearing football togs.","cn":"照片上他穿着足球衣。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"clothes","cn":"衣服"},{"en":"a unit for measuring the warmth of duvet s , sleeping bag s , jackets etc","cn":"托格〔计量羽绒被﹑睡袋﹑外套等保暖性的单位〕"},{"en":"to be or get dressed for a particular occasion or activity 〔","cn":"为特殊场合或活动而〕打扮起来"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tog.mp3","us":"media/ldoce/hwd/ame/7/laadtog.mp3"},"examples":[{"en":"They were all togged up in their skiing gear.","cn":"他们全都身着滑雪服。"},{"en":"running togs","cn":"跑步装"}],"oxford":{"phon":"tɒɡ","pos":"noun","senses":[{"en":"clothes, especially ones that you wear for a particular purpose","cn":"（尤指专用的）衣服，服装","g":"[plural]","lab":"informal, becoming old-fashioned，，","ex":{"en":"running togs","cn":"跑步装"}},{"en":"a unit for measuring how warm bed covers such as duvets are","cn":"托格（显示羽绒被褥等保暖性的热阻计量单位）","lab":"British English"}]}},"tom-tom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手鼓","en":"A tom-tom is a tall narrow drum that is usually played with the hands."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall narrow drum that you play with your hands 〔","cn":"一种狭长的〕手鼓﹐长筒鼓"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tom_tom0205.mp3","us":"media/ldoce/hwd/ame/9/tom-tom.mp3"},"oxford":{"phon":"ˈtɒm tɒm","pos":"verb","senses":[{"en":"to make something known or to talk about it in a way that shows that you are too proud of it","cn":"大肆宣扬；得意洋洋地谈论","ex":{"en":"The government again tom-tommed its achievements in improving education.","cn":"政府再次对其在改善教育方面取得的成就表示不满。"}},{"en":"a medium-sized drum that may be part of a drum kit","cn":"嗵鼓（有时是架子鼓的组成部分）","pos":"noun"},{"en":"a drum played with the hands, especially in native North American and South Asian cultures","cn":"（尤指亚洲或美洲土著文化中的）咚咚鼓，手鼓","pos":"noun"}]}},"tonne":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公吨(等于 1,000 千克)","en":"A tonne is a metric unit of weight that is equal to 1000 kilograms.","ex":{"en":"...65.5 million tonnes of coal","cn":"6,550 万公吨煤"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a unit for measuring weight, equal to 1,000 kilograms","cn":"公吨〔等于1,000公斤〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/tonne0205.mp3","us":"media/ldoce/hwd/ame/1/amelasdetonne.mp3"},"examples":[{"en":"a record grain harvest of 236m tonnes * 2.36","cn":"亿公吨创纪录的谷物收获量"},{"en":"a record grain harvest of 236m tonnes","cn":""}],"oxford":{"phon":"tʌn","pos":"noun","senses":[{"en":"a unit for measuring weight, equal to 1 000 kilograms","cn":"吨（等于 1 000 公斤）","ex":{"en":"a record grain harvest of 236m tonnes","cn":"创纪录的 2.36 亿吨谷物收获量"}}]}},"topsoil":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"表土（层）","en":"Topsoil is the layer of soil nearest the surface of the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the upper level of soil in which most plants have their roots","cn":"表土层﹔耕作层"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41topsoil.mp3","us":"media/ldoce/hwd/ame/b/topsoil.mp3"},"oxford":{"phon":"ˈtɒpsɔɪl","pos":"noun","senses":[{"en":"the layer of soil nearest the surface of the ground","cn":"表土；表土层"}]}},"torpid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迟钝的;有气无力的;懒洋洋的","en":"If you are torpid, you are mentally or physically inactive, especially because you are feeling lazy or sleepy."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not active because you are lazy or sleepy","cn":"迟钝的﹔懒散的﹔昏昏欲睡的﹐有气无力的"}]},"vocab":{"pos":"adj","senses":[{"en":"While the adjective torpid sounds a lot like the noun torpedo , it actually describes something slow or even inactive, like the torpedo that's just sitting around before it's launched."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41torpid.mp3","us":"media/ldoce/hwd/ame/e/torpid.mp3"},"examples":[{"en":"a torpid mind","cn":"迟钝的头脑"}],"oxford":{"phon":"ˈtɔːpɪd","pos":"adjective","senses":[{"en":"not active; with no energy or enthusiasm","cn":"不活泼的；迟钝的；有气无力的；懒散的"}]}},"totalitarian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极权主义的","en":"A totalitarian political system is one in which there is only one political party which controls everything and does not allow any opposition parties.","ex":{"en":"They feared that totalitarians might yet conquer the entire world.","cn":"他们担心极权主义者会征服整个世界。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a political system or country that has a dictator (= a leader who has complete power and who has not been elected )","cn":""},{"en":"used for describing countries in which ordinary people have no power and the government has complete control over everything","cn":""},{"en":"a country where the government strictly controls people’s freedom, for example to travel or to talk about politics","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"You can decipher the meaning of totalitarian by the first part: \"total.\" It refers to a government with total power, one that exercises complete, even oppressive control over the people and their activities. (You can also figure it’s not nice.)"}]},"media":{"uk":"media/ldoce/hwd/bre/d/totalitarian0205.mp3","us":"media/ldoce/hwd/ame/f/totalitarian.mp3"},"oxford":{"phon":"təʊˌtæləˈteəriən","pos":"adjective","senses":[{"en":"in which there is only one political party, which has complete power and control over the people","cn":"极权主义的","ex":{"en":"a totalitarian state/regime","cn":"极权国家/政权"}}]}},"torchlight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"火把光;火炬光","en":"If you do something by torchlight, you do it using the light that is produced by a torch or torches.","ex":{"en":"Surgeons are performing operations in tents by torchlight","cn":"医生正在帐篷里借着火把的光做手术。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the light produced by an electric torch","cn":"手电筒光"},{"en":"the light produced by burning torches","cn":"火把光；火炬光"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41torchlight.mp3","us":"media/ldoce/hwd/ame/c/torchlight.mp3"},"examples":[{"en":"a torchlight procession","cn":"点着火把的游行队伍"}],"oxford":{"phon":"ˈtɔːtʃlaɪt","pos":"noun","senses":[{"en":"the light that is produced by an electric torch or by burning torches","cn":"手电筒光；火炬的光亮","ex":{"en":"She read in bed at night by torchlight.","cn":"晚上她在床上借着手电筒看书。"}}]}},"top-heavy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"头重脚轻的;上重下轻的","en":"Something that is top-heavy is larger or heavier at the top than at the bottom, and might therefore fall over.","ex":{"en":"...top-heavy flowers such as sunflowers.","cn":"类似向日葵这样头重脚轻的花"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高级官员过多的;行政管理人员过多的","en":"If you describe a business or other organization as top-heavy, you mean that it has too many senior managers in relation to the number of junior managers or workers.","ex":{"en":"...top-heavy bureaucratic structures.","cn":"高级官员过多的官僚体系"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too heavy at the top and therefore likely to fall over","cn":"头重脚轻的﹐上重下轻的"},{"en":"an organization that is top-heavy has too many managers compared to the number of ordinary workers 〔","cn":"机构等〕高层人员过多的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/top_heavy0205.mp3","us":"media/ldoce/hwd/ame/c/top-heavy.mp3"},"examples":[{"en":"The company was burdened by a top-heavy bureaucracy.","cn":"公司被将多兵少的官僚制度所累。"}],"oxford":{"phon":"ˌtɒp ˈhevi","pos":"adjective","senses":[{"en":"too heavy at the top and therefore likely to fall","cn":"上部过重的；头重脚轻的"},{"en":"having too many senior staff compared to the number of workers","cn":"高级职员过多的；将多兵少的","ex":{"en":"top-heavy bureaucracy","cn":"头重脚轻的官僚主义"}}]}},"toupee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男用假发;遮秃假发","en":"A toupee is a piece of artificial hair worn by a man to cover a patch on his head where he has lost his hair."}]},"vocab":{"pos":"n","senses":[{"en":"A toupee is a partial wig, made to cover a bald patch. You'll have to be careful when you're wearing your toupee on a windy day!"}]},"oxford":{"phon":"ˈtuːpeɪ","pos":"noun","senses":[{"en":"a small section of artificial hair, worn by a man to cover an area of his head where hair no longer grows","cn":"（男用）小型遮秃假发"}]}},"touchline":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(橄榄球、足球等的)边线","en":"In sports such as rugby and football, the touchline is one of the two lines which mark the side of the playing area."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two lines that mark the longer sides of a sports playing area, especially in football 〔","cn":"尤指足球场的〕边线"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41touchline.mp3","us":"media/ldoce/hwd/ame/f/touchline.mp3"},"oxford":{"phon":"ˈtʌtʃlaɪn","pos":"noun","senses":[{"en":"a line that marks the side of the playing field in football (soccer), rugby, etc.","cn":"（足球、橄榄球等场地的）边线"}]}},"torturous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"折磨人的;极端痛苦的;引起痛苦的","en":"Something that is torturous is extremely painful and causes great suffering.","ex":{"en":"His breathing was torturous…","cn":"他的呼吸充满痛苦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very painful or unpleasant to experience 〔","cn":"经历〕痛苦的﹐不愉快的"}]},"vocab":{"pos":"adj","senses":[{"en":"Torturous describes anything that involves terrible suffering. Visiting a veal farm and witnessing the torturous conditions the calves are kept in might convince you to become a vegetarian."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41torturous.mp3","us":"media/ldoce/hwd/ame/1/laadtorturous.mp3"},"examples":[{"en":"a torturous five days of fitness testing","cn":"五天痛苦的体能测试"}]},"topknot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指女性的)顶髻","en":"If someone, especially a woman, has her hair in a topknot, her hair is arranged in a small neat pile on top of her head."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"hair that is tied together on top of your head","cn":"顶髻"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41topknot.mp3","us":"media/ldoce/hwd/ame/8/topknot.mp3"},"oxford":{"phon":"ˈtɒpnɒt","pos":"noun","senses":[{"en":"a way of arranging your hair in which it is tied up on the top of your head","cn":"顶髻"}]}},"township":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(过去南非的)黑人城镇，黑人居住区","en":"In South Africa, a township was a town where only black people lived.","ex":{"en":"...the South African township of Soweto.","cn":"南非黑人城镇索韦托"}},{"pos":"N-COUNT 可数名词","cn":"区，镇区(美国及加拿大县的下一级行政区)","en":"In the United States and Canada, a township is an area of land, especially a part of a county which is organized as a unit of local government."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a town in Canada or the US that has some local government 〔","cn":"加拿大或美国享有一定地方行政权的〕区﹐镇区"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41township.mp3","us":"media/ldoce/hwd/ame/d/l3township.mp3"},"oxford":{"phon":"ˈtaʊnʃɪp","pos":"noun","senses":[{"en":"(in South Africa in the past) a town or part of a town that black people had to live in, and where only black people lived","cn":"（旧时南非的）黑人城镇，黑人居住区","ex":{"en":"It was the first black township to have its own community radio station.","cn":"这是第一个拥有自己的社区广播电台的黑人城镇。"}},{"en":"(in the US or Canada) a division of a county that is a unit of local government","cn":"镇区（美国和加拿大县以下一级的地方政府）"}]}},"topaz":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"黄晶;黄玉","en":"A topaz is a precious stone which is usually yellowish-brown in colour."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a transparent yellow stone that is used as a jewel","cn":"黄玉，托帕石"}]},"vocab":{"pos":"n","senses":[{"en":"Topaz is yellow quartz, and you may have seen it in your grandmother's beaded jewelry."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41topaz.mp3","us":"media/ldoce/hwd/ame/d/topaz.mp3"},"examples":[{"en":"a topaz ring","cn":"黄玉戒指"}],"oxford":{"phon":"ˈtəʊpæz","pos":"noun","senses":[{"en":"a clear yellow semi-precious stone","cn":"黄玉","ex":{"en":"a topaz ring","cn":"黄宝石戒指"}}]}},"tomboy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"假小子;野丫头","en":"If you say that a girl is a tomboy, you mean that she likes playing rough or noisy games, or doing things that were traditionally considered to be things that boys enjoy."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a girl who likes playing the same games as boys","cn":"野丫头﹐假小子〔指喜欢玩男孩子游戏的女孩子〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/tomboy0205.mp3","us":"media/ldoce/hwd/ame/3/tomboy.mp3"},"oxford":{"phon":"ˈtɒmbɔɪ","pos":"noun","senses":[{"en":"a young girl who enjoys activities and games that are traditionally considered to be for boys","cn":"假小子，野丫头（喜欢男孩玩意儿的女孩子）"}]}},"touchdown":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(飞机或宇宙飞船的)降落，着陆","en":"Touchdown is the landing of an aircraft or spacecraft.","ex":{"en":"...a perfect touchdown","cn":"完美着陆"}},{"pos":"N-COUNT 可数名词","cn":"(橄榄球中的)攻方持球越线得分，达阵","en":"In rugby and American football, a touchdown is when a team scores points by taking the ball over the opposition's goal line."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the moment at which a plane or spacecraft lands 〔","cn":"飞机﹑航天器的〕降落﹐着陆"},{"en":"an act of putting the ball down on the ground behind the opposing team’s goal line in rugby 〔","cn":"英式橄榄球的〕达阵"},{"en":"an act of moving the ball across the opposing team’s goal line in American football 〔","cn":"美式橄榄球的〕达阵"}]},"media":{"uk":"media/ldoce/hwd/bre/9/touchdown0205.mp3","us":"media/ldoce/hwd/ame/f/touchdown.mp3"},"oxford":{"phon":"ˈtʌtʃdaʊn","pos":"noun","senses":[{"en":"the moment when a plane or spacecraft lands","cn":"（飞机或航天器的）着陆，降落，接地","g":"[countable, uncountable]","ex":{"en":"a smooth touchdown","cn":"顺利着陆"}},{"en":"an act of scoring points by putting the ball down on the area of ground behind the other team’s goal line","cn":"（在对方球门线后）持球触地；达阵","g":"[countable]"},{"en":"an act of scoring points by crossing the other team’s goal line while carrying the ball, or receiving the ball when you are over the other team’s goal line","cn":"达阵（持球越过对方球门线或在对方球门线后接球）","g":"[countable]","ex":{"en":"Manning and Brett threw nine touchdown passes between them.","cn":"曼宁和布雷特相互传球，投掷出 9 个达阵得分。"}}]}},"tonality":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"调性","en":"Tonality is the presence of a musical key in a piece of music."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the character of a piece of music that depends on the key of the music and the way in which the tunes and harmonies are combined 〔","cn":"音乐的〕调性"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tonality.mp3","us":"media/ldoce/hwd/ame/7/tonality.mp3"},"oxford":{"phon":"təʊˈnæləti","pos":"noun","senses":[{"en":"the quality of a piece of music that depends on the key in which it is written","cn":"调性","ex":{"en":"The piece then shifts in tonality, setting a more hopeful mood.","cn":"然后，这首曲子的基调发生了变化，营造出一种更加充满希望的情绪。"}}]}},"tournament":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锦标赛","en":"A tournament is a sports competition in which players who win a match continue to play further matches in the competition until just one person or team is left."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organized event in which people try to do an activity or sport better than other people, especially in order to win a prize","cn":""},{"en":"an important sports event in which players or teams play against each other to decide who is the best in an area, the country, or the world","cn":""},{"en":"a competition in a sport or game in which each player or team plays a series of games until one person or team wins","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A tournament refers to a gathering of competitors playing a series of games. There are chess tournaments , golf tournaments , tennis tournaments , and a number of tournaments titled “ Tournament of Champions.”"}]},"collocations":{"phrases":["ADJ. chess, golf, tennis, etc. | qualifying, ranking, World Cup | European, international, national, world | major | one-day | knockout, rou","VERB + TOURNAMENT enter, play (in), take part in The tournament was played under floodlights. Several top teams have agreed to play in the t","TOURNAMENT + VERB take place","TOURNAMENT + NOUN victory, win her first tournament win of the season | leader, winner | director, organizer, sponsor | referee | player, pr","PREP. in a/the ~ the strongest player in the tournament | out of a/the ~ The loser will be out of the tournament."]},"media":{"uk":"media/ldoce/hwd/bre/0/tournament0205.mp3","us":"media/ldoce/hwd/ame/1/tournament.mp3"},"examples":[{"en":"a golf/squash/tennis, etc. tournament","cn":"高尔夫球、壁球、网球等锦标赛"},{"en":"I feel I can win this tournament.","cn":"我觉得我能打赢这次锦标赛。"}],"oxford":{"phon":"ˈtʊənəmənt","pos":"noun","senses":[{"en":"a sports competition involving a number of teams or players who take part in different games and must leave the competition if they lose. The competition continues until there is only the winner left.","cn":"锦标赛；联赛","lab":"North American English, less frequent，，","ex":{"en":"a golf/tennis/soccer/chess tournament","cn":"高尔夫球／网球／足球／国际象棋锦标赛"}},{"en":"a competition in the Middle Ages between knights on horseback fighting to show courage and skill","cn":"（中世纪的）骑马比武","ex":{"en":"a medieval jousting tournament","cn":"中世纪的马术比赛"}}]}},"topple":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)摇摇欲坠;(使)不稳而倒下","en":"If someone or something topples somewhere or if you topple them, they become unsteady or unstable and fall over.","ex":{"en":"He just released his hold and toppled slowly backwards","cn":"他刚一松开手就缓缓向后倒下。"}},{"pos":"VERB 动词","cn":"推翻;颠覆","en":"To topple a government or leader, especially one that is not elected by the people, means to cause them to lose power.","ex":{"en":"...the revolution which toppled the regime.","cn":"推翻该政权的革命"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a tall object falls over , it falls onto its side from an upright position","cn":""},{"en":"if a building, wall, or fence falls down , part or all of it falls to the ground, because it is in bad condition or because it has been damaged","cn":""},{"en":"if a building, wall etc collapses , it suddenly falls down, especially because of a sudden pressure","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To topple something is to knock it down. A house of cards can be toppled — so can a government."}]},"media":{"uk":"media/ldoce/hwd/bre/3/topple0205.mp3","us":"media/ldoce/hwd/ame/7/topple.mp3"},"examples":[{"en":"He brushed past, toppling her from her stool.","cn":"他经过时蹭了她一下，使她从凳子上摔了下来。"},{"en":"The pile of books toppled over.","cn":"那一摞书倒了。"}],"oxford":{"phon":"ˈtɒpl","pos":"verb","senses":[{"en":"to become unsteady and fall down; to make something do this","cn":"（使）失去平衡而坠落，倒塌，倒下","g":"[intransitive, transitive]","ex":{"en":"The pile of books toppled over.","cn":"那一摞书倒了。"}},{"en":"to make somebody lose their position of power or authority","cn":"打倒；推翻；颠覆","g":"[transitive]","ex":{"en":"a plot to topple the President","cn":"推翻总统的阴谋"}}]}},"towpath":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(旧时马匹沿河岸拉纤时所走的)纤路，曳船道","en":"A towpath is a path along the side of a canal or river, which horses used to walk on when they pulled boats."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a path along the side of a canal or river, used especially in the past by horses pulling boats 〔","cn":"旧时运河或河流两岸供马拉船的〕曳船道﹐纤路"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41towpath.mp3","us":"media/ldoce/hwd/ame/0/towpath.mp3"},"oxford":{"phon":"ˈtəʊpɑːθ","pos":"noun","senses":[{"en":"a path along the bank of a river or canal, that was used in the past by horses pulling boats (called narrowboats)","cn":"纤道，纤路（旧时河流沿岸马拉驳船所走的路）"}]}},"torpor":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻木;迟钝;懒散","en":"Torpor is the state of being completely inactive mentally or physically, for example because of illness or laziness.","ex":{"en":"He had slumped into a state of torpor from which nothing could rouse him","cn":"他陷入麻木状态，任何事都不能令他振奋。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state of being not active because you are lazy or sleepy","cn":"懒散﹔有气无力﹔呆钝"}]},"vocab":{"pos":"n","senses":[{"en":"Torpor is a state of mental and physical inactivity. \"After a huge Thanksgiving meal, my family members fall into a torpor ; no one can even pick up the TV remote.\""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41torpor.mp3","us":"media/ldoce/hwd/ame/2/torpor.mp3"},"examples":[{"en":"In the heat they sank into a state of torpor.","cn":"炎热的天气使得他们委靡不振。"},{"en":"She tried to rouse him from the torpor into which he had sunk.","cn":"她试图把他从迷迷糊糊的状态中唤醒。"}],"oxford":{"phon":"ˈtɔːpə(r)","pos":"noun","senses":[{"en":"the state of not being active and having no energy or enthusiasm","cn":"迟钝；死气沉沉；懒散","ex":{"en":"In the heat they sank into a state of torpor.","cn":"炎热的天气使得他们萎靡不振。"}}]}},"totalitarianism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"极权主义","en":"Totalitarianism is the ideas, principles, and practices of totalitarian political systems."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a political system or country that has a dictator (= a leader who has complete power and who has not been elected )","cn":""},{"en":"used for describing countries in which ordinary people have no power and the government has complete control over everything","cn":""},{"en":"a country where the government strictly controls people’s freedom, for example to travel or to talk about politics","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If the government has complete and absolute power over the people, that's totalitarianism . This is a repressive, unfree type of society."}]},"media":{"uk":"media/ldoce/hwd/bre/d/totalitarian0205.mp3","us":"media/ldoce/hwd/ame/f/totalitarian.mp3"},"oxford":{"phon":"təʊˌtæləˈteəriənɪzəm","pos":"noun","senses":[{"en":"the principles and practices of a political system in which there is only one party, which has complete power and control over the people","cn":"极权主义","ex":{"en":"to oppose dictatorship and totalitarianism","cn":"反对独裁统治和极权主义"}}]}},"townsfolk":{"lemma":"townspeople"},"totem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图腾","en":"In some societies, a family's totem is the particular animal, plant, or natural object which they regard as a special symbol and which they believe has spiritual significance."},{"pos":"N-COUNT 可数名词","cn":"标志物;象征物","en":"Something that is a totem of another thing is a symbol of it.","ex":{"en":"This opera is one of the cultural totems of Western civilisation.","cn":"这部歌剧是西方文明的文化标志物之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an animal, plant etc that is thought to have a special spiritual connection with a particular tribe, especially in North America, or a figure made to look like the animal etc","cn":"图腾﹔图腾形象"}]},"vocab":{"pos":"n","senses":[{"en":"A totem is an emblem or badge that features an animal or plant. Each totem represents a family, clan, or tribe. Do you come from a long line of fishermen? Perhaps your family’s totem is a trout."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41totem.mp3","us":"media/ldoce/hwd/ame/b/totem.mp3"},"examples":[{"en":"totemic animals","cn":"图腾动物"}],"oxford":{"phon":"ˈtəʊtəm","pos":"noun","senses":[{"en":"an animal or other natural object that is chosen and respected in a particular culture as a special symbol; an image of this animal, etc.","cn":"图腾；图腾形象"},{"en":"a person or thing that is thought of as a symbol of a particular quality or idea","cn":"被认为是特定品质或思想象征的人或事物","ex":{"en":"The Hampden Park football stadium is a totem of Scottish identity.","cn":"汉普顿公园足球场是苏格兰身份的图腾。"}}]}},"totter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"跌跌撞撞;蹒跚;踉跄","en":"If someone totters somewhere, they walk there in an unsteady way, for example because they are ill or drunk.","ex":{"en":"He tottered to the fridge, got a beer and slumped at the table","cn":"他踉跄地走到冰箱前，拿出一瓶啤酒，一屁股坐在桌边。"}},{"pos":"VERB 动词","cn":"摇摇欲坠;变得不稳;动摇","en":"If something such as a market or government is tottering, it is weak and likely to collapse or fail completely.","ex":{"en":"The property market is tottering.","cn":"房地产市场摇摇欲坠。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly become unsteady and start to fall","cn":""},{"en":"if someone or something totters or teeters they move unsteadily from side to side and look as if they are going to fall","cn":""},{"en":"to move unsteadily from side to side","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you spin yourself around until you are dizzy, you will likely totter if you try to step forward. Totter is a verb that means \"move unsteadily, as though you are about to fall down.\""}]},"media":{"uk":"media/ldoce/hwd/bre/9/totter0205.mp3","us":"media/ldoce/hwd/ame/3/totter.mp3"},"examples":[{"en":"the tottering walls of the castle","cn":"古城堡摇摇欲坠的墙壁"},{"en":"( figurative ) a tottering dictatorship","cn":"濒临瓦解的独裁统治"}],"oxford":{"phon":"ˈtɒtə(r)","pos":"verb","senses":[{"en":"to walk or move with weak, unsteady steps, especially because you are drunk or ill","cn":"蹒跚；踉跄；跌跌撞撞","g":"[intransitive]","ex":{"en":"She managed to totter back to her seat.","cn":"她摇摇晃晃地回到座位上。"}},{"en":"to be weak and seem likely to fall","cn":"摇摇欲坠；摇摇晃晃","g":"[intransitive]","lab":"figurative","ex":{"en":"the tottering walls of the castle","cn":"城堡摇摇欲坠的墙壁"}}]}},"tomfoolery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蠢事;愚蠢的行为;瞎闹","en":"Tomfoolery is playful behaviour, usually of a rather silly, noisy, or rough kind.","ex":{"en":"Were you serious, or was that a bit of tomfoolery?","cn":"你是认真的呢，还是有点胡闹？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"silly behaviour","cn":"愚蠢的行为"}]},"vocab":{"pos":"n","senses":[{"en":"Tomfoolery is foolishness. Starting a food fight in a cafeteria is an example of tomfoolery ."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tomfoolery.mp3","us":"media/ldoce/hwd/ame/2/tomfoolery.mp3"},"oxford":{"phon":"tɒmˈfuːləri","pos":"noun","senses":[{"en":"silly behaviour","cn":"愚蠢的行为"}]}},"tootle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"悠闲自得地去；不慌不忙地开车去","en":"If you tootle somewhere, you travel or go there without rushing or without any particular aim.","ex":{"en":"I'm sure Ted is tootling down the motorway at this very moment.","cn":"我确信泰德此刻正悠闲自得地开车行驶在高速路上。"}},{"pos":"VERB 动词","cn":"(轻声随意地)演奏","en":"If you tootle a tune on an instrument, you play it quietly, without concentrating or taking it seriously.","ex":{"en":"McCann tootled a tune on the piano.","cn":"麦卡恩在钢琴上随手轻弹一曲。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move slowly in a car 〔","cn":"驾车〕缓慢地行驶"},{"en":"to play an instrument that you blow","cn":"吹奏乐器"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41tootle.mp3","us":"media/ldoce/hwd/ame/3/laadtootle.mp3"},"examples":[{"en":"We spent the afternoon tootling along the coast.","cn":"我们下午开着车沿海边缓缓行驶。"},{"en":"tootling away on a flute","cn":"吹着笛子"}],"oxford":{"phon":"ˈtuːtl","pos":"verb","senses":[{"en":"to walk, drive, etc. somewhere without hurrying","cn":"信步；闲逛；溜达；不慌不忙地开车","g":"[intransitive]"},{"en":"to produce a series of notes by blowing into a musical instrument","cn":"连续吹（乐器）；发出一连串的嘟嘟声","g":"[intransitive, transitive]"}]}},"totality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"全体;整个;全部","en":"The totality of something is the whole of it.","ex":{"en":"...a process of social, economic and political change which involves the totality of human experience","cn":"涉及人类全部经验的社会、经济和政治变革过程"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the whole of something","cn":"某事物的全部"},{"en":"a total amount","cn":"总数﹐总额"}]},"media":{"uk":"media/ldoce/hwd/bre/f/totality0205.mp3","us":"media/ldoce/hwd/ame/1/totality.mp3"},"examples":[{"en":"The seriousness of the situation is difficult to appreciate in its totality.","cn":"很难从全局上理解局势的严重性。"},{"en":"It’s essential that we look at the problem in its totality.","cn":"最重要的是﹐我们应整体看待这个问题。"}],"oxford":{"phon":"təʊˈtæləti","pos":"noun","senses":[{"en":"the state of being complete or whole; the whole number or amount","cn":"全体；全部；整个；总数；总额","ex":{"en":"The seriousness of the situation is difficult to appreciate in its totality.","cn":"很难从全局上理解局势的严重性。"}}]}},"tomcat":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male cat","cn":"公猫﹐雄猫"}]},"media":{"uk":"media/ldoce/hwd/bre/a/tomcat0205.mp3","us":"media/ldoce/hwd/ame/8/tomcat.mp3"},"oxford":{"phon":"ˈtɒmkæt","pos":"noun","senses":[{"en":"a male cat","cn":"公猫；雄猫"}]}},"toddler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"学步的孩童","en":"A toddler is a young child who has only just learned to walk or who still walks unsteadily with small, quick steps."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very young child who has not yet learned to speak or walk","cn":""},{"en":"a baby who has learned how to walk","cn":""},{"en":"a baby or a very young child","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun toddler to describe a small child who is just learning how to walk."}]},"media":{"img":["media/ldoce/img/toddler.jpg"],"uk":"media/ldoce/hwd/bre/4/toddler0205.mp3","us":"media/ldoce/hwd/ame/3/toddler.mp3"},"oxford":{"phon":"ˈtɒdlə(r)","pos":"noun","senses":[{"en":"a child who has only recently learnt to walk","cn":"学步的幼儿；刚学会走路的孩子","ex":{"en":"We run a mother and toddler group in the mornings.","cn":"我们早上组织一个母婴小组。"}}]}},"toddle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(小孩)蹒跚行走","en":"When a child toddles, it walks unsteadily with short quick steps.","ex":{"en":"...once your baby starts toddling","cn":"一旦你的宝宝开始蹒跚学步"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a small child toddles, it walks with short unsteady steps 〔","cn":"幼儿〕蹒跚行走"},{"en":"to walk somewhere, especially in a slow and relaxed way","cn":"闲逛﹔溜达"}]},"vocab":{"pos":"v","senses":[{"en":"When you toddle , you wobble a bit on your legs as you walk. It's most common to see very small children toddle around."}]},"media":{"uk":"media/ldoce/hwd/bre/a/toddle0205.mp3","us":"media/ldoce/hwd/ame/c/toddle.mp3"},"examples":[{"en":"I locked the door and then toddled off to bed.","cn":"我锁上房门，然后就上床睡觉去了。"},{"en":"She toddles down to the park most afternoons.","cn":"多数下午她都遛达着去公园。"}],"oxford":{"phon":"ˈtɒdl","pos":"verb","senses":[{"en":"when a young child who has just learnt to walk toddles, he/she walks with short, unsteady steps","cn":"（幼儿学步时）摇摇摆摆地走，蹒跚行走","g":"[intransitive]","ex":{"en":"I have to watch him all the time now that he’s toddling.","cn":"现在他蹒跚学步，我必须一直看着他。"}},{"en":"to walk or go somewhere","cn":"步行；走；到…去","g":"[intransitive]","lab":"informal","ex":{"en":"She toddles down to the park most afternoons.","cn":"多数下午她都溜达着去公园。"}}]}},"toughen":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)变坚硬;(使)变坚韧","en":"If you toughen something or if it toughens, you make it stronger so that it will not break easily.","ex":{"en":"Do not add salt to beans when cooking as this tends to toughen the skins.","cn":"煮豆荚时别加盐，因为这常会使豆壳变硬。"}},{"pos":"VERB 动词","cn":"加强，强化（政策、规章或惩罚）；使强硬","en":"If a person, institution, or law toughens its policies, regulations, or punishments, it makes them firmer or stricter.","ex":{"en":"Talks are under way to toughen trade restrictions","cn":"加强贸易限制的会谈正在进行中。"}},{"pos":"VERB 动词","cn":"（经历）使坚强，使顽强","en":"If an experience toughens you, it makes you stronger and more independent in character.","ex":{"en":"They believe that participating in fights toughens boys and shows them how to be men.","cn":"他们认为参与打架会使男孩子变得坚强，教会他们怎样成为男人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become tougher, or to make someone or something tougher （","cn":"使）变坚韧﹔（使）变坚强"}]},"media":{"uk":"media/ldoce/hwd/bre/e/toughen0205.mp3","us":"media/ldoce/hwd/ame/c/toughen.mp3"},"examples":[{"en":"The government is considering toughening up the law on censorship.","cn":"政府正在考虑强化书报电影审查方面的法律。"},{"en":"toughened glass","cn":"钢化玻璃"}],"oxford":{"phon":"ˈtʌfn","pos":"verb","senses":[{"en":"to become or make something stronger, so that it is not easily cut, broken, etc.","cn":"（使）坚硬，坚固","g":"[transitive, intransitive]","ex":{"en":"toughened glass","cn":"钢化玻璃"}},{"en":"to make something such as laws or rules stricter","cn":"加强，强化（法律、规定等）","g":"[transitive]","ex":{"en":"The government is considering toughening up the law on censorship.","cn":"政府正在考虑强化书报电影审查方面的法律。"}},{"en":"to make somebody stronger and more able to deal with difficult situations","cn":"使更坚强；使坚韧","g":"[transitive]","ex":{"en":"His parents sent him away to school to toughen him up.","cn":"他的父母送他去学校是为了让他坚强起来。"}}]}},"toga":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(古罗马人穿的)托加袍","en":"A toga is a piece of clothing which was worn by the ancient Romans."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long loose piece of clothing worn by people in ancient Rome","cn":"托加袍〔古罗马人穿的宽松长袍〕"}]},"vocab":{"pos":"n","senses":[{"en":"A toga is the draped, dress-like garment worn by men in ancient Rome. Today, businessmen wear suits and ties, but thousands of years ago, the business suit of Rome was a toga ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/toga0205.mp3","us":"media/ldoce/hwd/ame/2/toga.mp3"},"oxford":{"phon":"ˈtəʊɡə","pos":"noun","senses":[{"en":"a loose outer piece of clothing worn by the citizens of ancient Rome","cn":"托加袍（古罗马市民穿的宽松大袍）"}]}},"toyota":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a type of car or other motor vehicle made by the Japanese company Toyota","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/lpd_toyota.mp3","us":"media/ldoce/hwd/ame/c/lpd_toyota.mp3"}},"torch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手电筒","en":"A torch is a small electric light which is powered by batteries and which you can carry in your hand."},{"pos":"N-COUNT 可数名词","cn":"火把;火炬","en":"A torch is a long stick with burning material at one end, used to provide light or to set things on fire.","ex":{"en":"They lit a torch and set fire to the chapel's thatch.","cn":"他们点着一支火把，放火烧了小教堂的茅草屋顶。"}},{"pos":"N-COUNT 可数名词","cn":"吹管;喷灯;氧乙炔炬","en":"A torch is a device that produces a hot flame and is used for tasks such as cutting or joining pieces of metal.","ex":{"en":"The gang worked for up to ten hours with acetylene torches to open the vault.","cn":"那伙匪徒为打开金库用氧乙炔炬干了长达10个小时。"}},{"pos":"VERB 动词","cn":"纵火焚烧;放火烧","en":"If someone torches a building or vehicle, they set fire to it deliberately.","ex":{"en":"The rioters torched the local library","cn":"暴乱者放火烧了当地的图书馆。"}},{"pos":"PHRASE 短语","cn":"暗恋;对…单相思","en":"If you say that someone is carrying a torch for someone else, you mean that they secretly admire them or love them.","ex":{"en":"He has always carried a torch for Barbara.","cn":"他一直单恋芭芭拉。"}},{"pos":"PHRASE 短语","cn":"(为…)奋战;(为…)奋斗","en":"If you say that someone is carrying the torch of a particular belief or movement, you mean that they are working hard to ensure that it is not forgotten and continues to grow stronger.","ex":{"en":"This group aims to carry the torch for the millions who demonstrated and the thousands who died","cn":"这个团体旨在将游行示威的数百万人与死去的数千人的信念传承下去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that produces light, especially electric light, to help you to see","cn":""},{"en":"an object that produces light by using electricity, oil, or gas – often used in names of lights","cn":""},{"en":"a lamp that you can carry, consisting of a metal container with glass sides that surrounds a flame or light","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A torch is a handheld light. Although flashlights are sometimes called \"torches,\" technically a torch has a burning flame."}]},"collocations":{"phrases":["ADJ. powerful | electric","VERB + TORCH carry, have | switch off/on, turn off/on | flash, play, point, shine The policeman played his torch over the men's faces. I sho","TORCH + VERB flash, play, shine A powerful torch shone in their direction.","TORCH + NOUN beam","PHRASES the beam of a torch, light from/of a torch We struggled to read the map by the light of the torch. 2 piece of burning wood carried t","ADJ. blazing, burning, flaming, flaring, flickering","VERB + TORCH light They lit their torches from the fire. | carry, hold Servants were carrying lighted torches.","TORCH + VERB light The path to the castle was lit by blazing torches. | burn The torches were burning fiercely. | flare | flicker, splutter "]},"media":{"img":["media/ldoce/img/torch.jpg"],"uk":"media/ldoce/hwd/bre/d/torch_v0205.mp3","us":"media/ldoce/hwd/ame/c/torch.mp3"},"examples":[{"en":"( figurative ) They struggled to keep the torch of idealism and hope alive.","cn":"他们为使理想主义和希望的火炬不熄灭而奋斗。"},{"en":"Shine the torch on the lock while I try to get the key in.","cn":"我插钥匙时，请用手电筒照着锁头。"}],"oxford":{"phon":"tɔːtʃ","pos":"noun","senses":[{"en":"a small electric lamp that you can hold in your hand and carry with you","cn":"手电筒","lab":"British English","ex":{"en":"Shine the torch on the lock while I try to get the key in.","cn":"我插钥匙时，请用手电筒照着锁头。"}},{"en":"a tool for directing a very hot flame onto part of a surface, for example to remove paint","cn":"喷灯","lab":"both North American English"},{"en":"a long stick that has material at one end that is set on fire and that people carry to give light","cn":"火炬；火把","lab":"figurative","ex":{"en":"a flaming torch","cn":"燃烧着的火炬"}},{"en":"to set fire to a building or vehicle deliberately in order to destroy it","cn":"放火烧，纵火烧（建筑物或汽车）","ex":{"en":"The houses had been looted and then torched.","cn":"房屋遭到抢劫，然后被烧毁。"},"pos":"verb"}]}},"topmost":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最高的;最上面的；顶端的","en":"The topmost thing in a number of things is the one that is highest or nearest the top.","ex":{"en":"...the topmost branches of a gigantic oak tree.","cn":"一棵巨大橡树的梢枝"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"at the top above the lower part of something","cn":""},{"en":"the topmost or uppermost part of something is the highest of all its parts, right at the top","cn":""},{"en":"the topmost part of something is its highest part","cn":"最高的﹔最上面的﹔顶端的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/topmost0205.mp3","us":"media/ldoce/hwd/ame/8/topmost.mp3"},"examples":[{"en":"the topmost branches of the tree","cn":"树顶的枝丫"},{"en":"The topmost branches were still bathed in sunlight.","cn":"最高处的树枝仍然沐浴在阳光下。"}],"oxford":{"phon":"ˈtɒpməʊst","pos":"adjective","senses":[{"en":"highest","cn":"最高的；最上面的","ex":{"en":"the topmost branches of the tree","cn":"树顶的枝丫"}}]}},"tory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(英国)托利党党员的，保守党党员的","en":"In Britain, a Tory politician or voter is a member of or votes for the Conservative Party.","ex":{"en":"...the former Tory Party chairman, Chris Patten.","cn":"托利党前主席彭定康"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of the British Conservative Party 〔","cn":"英国的〕保守党成员﹐托利党人"}]},"media":{"uk":"media/ldoce/hwd/bre/8/tory0205.mp3","us":"media/ldoce/hwd/ame/a/tory.mp3"},"examples":[{"en":"The Tories (= the Tory party) lost the election.","cn":"英国保守党在选举中失败。"},{"en":"Tory policies","cn":"英国保守党的政策"}],"oxford":{"phon":"ˈtɔːri","pos":"noun","senses":[{"en":"a member or supporter of the British Conservative party","cn":"英国保守党党员（或支持者）","ex":{"en":"The Tories (= the Tory party) lost the election.","cn":"英国保守党在选举中失败。"}},{"en":"connected with the British Conservative Party","cn":"（英国）保守党的","ex":{"en":"the Tory party","cn":"英国保守党"},"pos":"adjective"}]}},"torso":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人体的)躯干","en":"Your torso is the main part of your body, and does not include your head, arms, and legs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone's body , not including the head, legs, or arms","cn":""},{"en":"the main part of a person's body, but not including the head, arms, or legs","cn":""},{"en":"an arm or a leg","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A torso is no more than the trunk of the human body — minus arms, legs, and heads. Joggers or early morning dog walkers frequently find torsos. And then the police are called."}]},"collocations":{"phrases":["ADJ. bare, naked | tanned | lower, upper | human | headless, mutilated The headless torso of a man was found in some bushes.","VERB + TORSO reveal He took off his shirt to reveal his tanned torso."]},"media":{"uk":"media/ldoce/hwd/bre/e/torso0205.mp3","us":"media/ldoce/hwd/ame/0/torso.mp3"},"examples":[{"en":"the torso of a woman","cn":"一名女性的躯干"}],"oxford":{"phon":"ˈtɔːsəʊ","pos":"noun","senses":[{"en":"the main part of the body, not including the head, arms or legs","cn":"（身体的）躯干","ex":{"en":"He took off his T-shirt to reveal his tanned torso.","cn":"他脱下 T 恤衫露出晒得黝黑的上身。"}},{"en":"a statue of a torso","cn":"躯干雕像","ex":{"en":"The museum has a Roman torso in the entrance hall.","cn":"博物馆的入口大厅有一个罗马躯干。"}}]}},"towel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毛巾","en":"A towel is a piece of thick soft cloth that you use to dry yourself.","ex":{"en":"...a bath towel.","cn":"浴巾"}},{"pos":"VERB 动词","cn":"用毛巾擦(干)","en":"If you towel something or towel it dry, you dry it with a towel.","ex":{"en":"James came out of his bedroom, toweling his wet hair","cn":"詹姆斯从卧室出来，用毛巾擦着他湿漉漉的头发。"}},{"pos":"PHRASE 短语","cn":"承认失败;认输","en":"If you throw in the towel, you stop trying to do something because you realize that you cannot succeed.","ex":{"en":"It seemed as if the police had thrown in the towel and were abandoning the investigation.","cn":"警方似乎已经认输，打算放弃调查。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of cloth that you use for drying your skin or for drying things such as dishes","cn":"毛巾﹔抹布"},{"en":"to dry yourself using a towel","cn":"用毛巾擦干"}]},"collocations":{"phrases":["ADJ. clean, fresh | damp, wet | dry | rolled-up | fluffy, soft, thick | paper | bath, bathroom, beach, hand, kitchen, tea | roller | sanitar","VERB + TOWEL drape, wrap He had a towel draped across his shoulders.","TOWEL + VERB hang Several towels hung over the side of the bath.","TOWEL + NOUN rail a heated towel rail"]},"media":{"img":["media/ldoce/img/towel.jpg"],"uk":"media/ldoce/hwd/bre/7/towel_v0205.mp3","us":"media/ldoce/hwd/ame/5/towel1.mp3"},"examples":[{"en":"Help yourself to a clean towel.","cn":"请随便拿一条干净毛巾用。"},{"en":"a kitchen towel (= a piece of paper from a roll that you use to clean up liquid, etc. in the kitchen)","cn":"厨房用清洁纸巾"}],"oxford":{"phon":"ˈtaʊəl","pos":"noun","senses":[{"en":"a piece of cloth or paper used for drying things, especially your body","cn":"毛巾；手巾；抹布；纸巾","ex":{"en":"Help yourself to a clean towel.","cn":"请随便拿一条干净毛巾用。"}},{"en":"to dry yourself/somebody/something with a towel","cn":"用毛巾擦干","pos":"verb"}]}},"tongue-in-cheek":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not being serious about something that should be taken seriously, so that people think you do not care","cn":""},{"en":"actions or behaviour that are playful are not serious, but they are fun and friendly","cn":""},{"en":"making jokes or trying to be funny in a clever or unkind way that people think is annoying","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/tongue_in_chee0205.mp3","us":"media/ldoce/hwd/ame/3/tongue-in-cheek.mp3"},"examples":[{"en":"The offer was made almost tongue-in-cheek.","cn":"这种提议差不多只是说说而已。"},{"en":"a tongue-in-cheek remark","cn":"一句戏言"}],"oxford":{"phon":"ˌtʌŋ ɪn ˈtʃiːk","pos":"adjective","senses":[{"en":"not intended seriously; done or said as a joke","cn":"言不由衷的；随便说说的；开玩笑的","ex":{"en":"a tongue-in-cheek remark","cn":"一句戏言"}},{"en":"not seriously; as a joke","cn":"言不由衷的；随便说说的；开玩笑的","ex":{"en":"The offer was made almost tongue-in-cheek.","cn":"这种提议差不多只是说说而已。"},"pos":"adverb"}]}},"tormentor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"折磨者;使人痛苦的人","en":"Some-one's tormentor is a person who deliberately causes them physical or mental pain.","ex":{"en":"...cases where women subjected to years of brutality lose control and kill their tormentors.","cn":"一些多年遭受暴力的女性最终失控杀死折磨她们的人的案例"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone suffer a lot, especially mentally","cn":""},{"en":"to deliberately treat someone cruelly by annoying them or hurting them","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/torment_v0205.mp3","us":"media/ldoce/hwd/ame/c/l3torment2.mp3"},"examples":[{"en":"Seth was tormented by feelings of guilt.","cn":""},{"en":"The older boys would torment him whenever they had the chance.","cn":""}],"oxford":{"phon":"tɔːˈmentə(r)","pos":"noun","senses":[{"en":"a person who causes somebody to suffer","cn":"折磨人的人；折磨者","ex":{"en":"The dog suddenly turned on its tormentors.","cn":"狗突然转向了折磨它的人。"}}]}},"top-secret":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"top-secret documents or information must be kept completely secret 〔","cn":"文件或情报〕绝密的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/top_secret0205.mp3","us":"media/ldoce/hwd/ame/d/top-secret.mp3"},"examples":[{"en":"a top-secret code","cn":"绝密的密码"}],"oxford":{"phon":"ˌtɒp ˈsiːkrət","pos":"adjective","senses":[{"en":"that must be kept completely secret, especially from other governments","cn":"（尤指对他国政府）最高机密的，绝密的","ex":{"en":"This information has been classified top secret.","cn":"这一情报被归为绝密类别。"}}]}},"toxicology":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毒理学;毒物学","en":"Toxicology is the study of poisons."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the science and medical study of poisons and their effects","cn":"毒理学"}]},"vocab":{"pos":"n","senses":[{"en":"Toxicology is the field that studies poisons, especially how poisons work and how to treat them. If you’re writing a true crime story, you should study toxicology to know what happens when the villain poisons the victim’s tea. Mwah ha ha."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41toxicology.mp3","us":"media/ldoce/hwd/ame/0/toxicology.mp3"},"oxford":{"phon":"ˌtɒksɪˈkɒlədʒi","pos":"noun","senses":[{"en":"the scientific study of poisons","cn":"毒理学；毒物学"}]}},"tortoiseshell":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"龟甲;玳瑁壳","en":"Tortoiseshell is the hard shell of a kind of sea turtle. It is brown and yellow in colour and is often polished and used to make jewellery and ornaments."},{"pos":"ADJ 形容词","cn":"龟甲做的;仿玳瑁的","en":"Tortoiseshell means made of tortoiseshell or made of a material which resembles tortoiseshell.","ex":{"en":"He wears huge spectacles with thick tortoiseshell frames.","cn":"他戴着玳瑁粗框大眼镜。"}},{"pos":"N-COUNT 可数名词","cn":"(翅膀呈棕色和橘黄色的)蛱蝶","en":"A tortoiseshell is a butterfly with brown and orange wings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard shiny brown and white material made from the shell of a tortoise","cn":"玳瑁壳﹐龟甲"},{"en":"a cat that has yellow, brown, and black marks on its fur","cn":"玳瑁猫"},{"en":"a butterfly that has brown and orange wings 〔","cn":"翅膀呈褐色和橙色的〕蛱蝶"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tortoiseshell.mp3","us":"media/ldoce/hwd/ame/4/tortoiseshell.mp3"},"oxford":{"phon":"ˈtɔːtəsʃel","pos":"noun","senses":[{"en":"the hard shell of a turtle, especially the type with orange and brown marks, used for making combs, jewellery, etc.","cn":"龟甲；龟板；玳瑁壳","g":"[uncountable]"},{"en":"a cat with black, brown, orange and white fur","cn":"（毛色为黄褐黑白相间的）家猫","g":"[countable]","lab":"North American English also"},{"en":"a butterfly with orange and brown marks on its wings","cn":"（翅膀带黄褐色斑点的）蛱蝶","g":"[countable]"}]}},"tone-deaf":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能辨别音调的;音盲的；五音不全的","en":"If you say that someone is tone-deaf, you mean that they cannot sing in tune or recognize different tunes."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to hear the difference between different musical notes","cn":"不能辨别音调的﹐五音不全的"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who's tone-deaf has trouble telling the difference between musical notes. Being tone-deaf makes it hard to fully enjoy music."}]},"media":{"uk":"media/ldoce/hwd/bre/d/tone_deaf0205.mp3","us":"media/ldoce/hwd/ame/f/tone-deaf.mp3"},"oxford":{"phon":"ˌtəʊn ˈdef","pos":"adjective","senses":[{"en":"unable to hear the difference between musical notes","cn":"不能辨别音高的"}]}},"toccata":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"托卡塔(一种由钢琴、风琴或其他键盘乐器演奏的快节奏乐曲)","en":"A toccata is a fast piece of music for the piano, organ, or other keyboard instrument."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of music, usually for piano or organ, that is played very quickly","cn":"托卡塔〔一种用钢琴或管风琴快速演奏的乐曲〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41toccata.mp3","us":"media/ldoce/hwd/ame/b/toccata.mp3"},"oxford":{"phon":"təˈkɑːtə","pos":"noun","senses":[{"en":"a piece of music for a keyboard instrument that includes difficult passages designed to show the player’s skill","cn":"托卡塔（用键盘乐器演奏的乐曲，其中有的乐段难度很大，以显示演奏者的技艺）"}]}},"topiary":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"林木造型艺术；绿雕塑术","en":"Topiary is the art of cutting trees and bushes into different shapes, for example into the shapes of birds or animals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"trees and bushes cut into the shapes of birds, animals etc, or the art of cutting them in this way","cn":"绿色雕塑﹔林木造型术"}]},"vocab":{"pos":"n","senses":[{"en":"If you practice topiary in your yard, you'll end up with shrubs and hedges in the shapes of unicorns, lions, and giant prairie dogs, since topiary means cutting bushes into fun shapes."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41topiary.mp3","us":"media/ldoce/hwd/ame/d/topiary.mp3"},"oxford":{"phon":"ˈtəʊpiəri","pos":"noun","senses":[{"en":"the art of cutting bushes into shapes such as birds or animals","cn":"树木造型；绿雕塑"}]}},"tow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拖;拉;牵引","en":"If one vehicle tows another, it pulls it along behind it.","ex":{"en":"He had been using the vehicle to tow his work trailer","cn":"他一直用这辆车牵引他的活动工作室。"}},{"pos":"PHRASE 短语","cn":"跟随;陪伴","en":"If you have someone in tow, they are following you closely because you are looking after them or you are leading them somewhere.","ex":{"en":"There she was on my doorstep with child in tow","cn":"她站在我门口，身后跟着一个孩子。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something or someone move in the direction that your hands are moving","cn":""},{"en":"to pull something suddenly with a short quick movement, often to get someone’s attention","cn":""},{"en":"to pull something along the ground, especially because it is heavy","cn":""}]},"collocations":{"phrases":["VERB + TOW give sb A truck driver gave me a tow to the nearest garage.","TOW + NOUN bar, line, rope | plane, truck, vehicle | pilot","PREP. in ~ (usually figurative) a harassed mother with three small children in tow | under ~ The ship, whose engine had failed, is now safel"]},"media":{"uk":"media/ldoce/hwd/bre/2/toe_v0205.mp3","us":"media/ldoce/hwd/ame/c/toe1.mp3"},"examples":[{"en":"The car broke down and we had to get somebody to give us a tow.","cn":"汽车抛锚了，我们只得让人拖走。"},{"en":"She turned up with her mother in tow.","cn":"她露面了，后面紧跟着她的母亲。"}],"oxford":{"phon":"təʊ","pos":"verb","senses":[{"en":"to pull a car, boat, etc. behind another vehicle, using a rope or chain","cn":"（用绳索或链条）拖，拉，牵引，拽","ex":{"en":"Our car was towed away by the police.","cn":"我们的汽车被警察拖走了。"}},{"en":"to pull somebody along behind you","cn":"拉着，拽着（某人）","ex":{"en":"Vicky was towing Rosa along by the hand.","cn":"维姬拽着罗莎的手往前走。"}},{"en":"an act of one vehicle pulling another vehicle using a rope or chain","cn":"（车、船等的）牵引，拽引","ex":{"en":"The car broke down and we had to get somebody to give us a tow.","cn":"汽车抛锚了，我们只得让人拖走。"},"pos":"noun"}]}},"tout":{"collins":{"senses":[{"pos":"VERB 动词","cn":"兜售;吹嘘","en":"If someone touts something, they try to sell it or convince people that it is good.","ex":{"en":"It has the trappings of an election campaign in the United States, with slick television ads touting the candidates.","cn":"它具有美国竞选活动的典型特征，即通过华而不实的电视广告来吹嘘候选人。"}},{"pos":"VERB 动词","cn":"兜揽;招徕","en":"If someone touts for business or custom, they try to obtain it.","ex":{"en":"He visited Thailand and Singapore to tout for investment","cn":"他访问了泰国与新加坡，以期招揽投资。"}},{"pos":"VERB 动词","cn":"(在体育场或剧院外)倒卖(高价票)","en":"If someone touts tickets, they sell them outside a sports ground or theatre, usually for more than their original value.","ex":{"en":"...a man who made his money touting tickets","cn":"靠倒票捞钱的人"}},{"pos":"N-COUNT 可数名词","cn":"票贩子;“黄牛”","en":"A tout is someone who sells things such as tickets unofficially, usually at prices which are higher than the official ones."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to praise something or someone in order to persuade people that they are important or worth a lot","cn":"赞扬﹔吹捧"},{"en":"to try to persuade people to buy goods or services you are offering","cn":"兜售﹐推销（商品或服务）"},{"en":"to give someone information about a horse in a race （","cn":"向…）提供赛马情报"}]},"vocab":{"pos":"1 v n 2 n 3 n","senses":[{"en":"To tout means to praise, boast, or brag about. If you like to tout your skill as a skier, you tell people you can go down expert-level hills."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tout2.mp3","us":"media/ldoce/hwd/ame/9/tout1.mp3"},"examples":[{"en":"He's busy touting his client's latest book around London publishers.","cn":"他正忙于向伦敦多家出版商兜售他的委托人的一部新书。"},{"en":"the problem of unlicensed taxi drivers touting for business at airports","cn":"没有执照的出租汽车司机在机场揽生意的问题"}],"oxford":{"phon":"taʊt","pos":"verb","senses":[{"en":"to try to persuade people that somebody/something is important or valuable by praising them/it","cn":"标榜；吹捧；吹嘘","g":"[transitive, often passive]","ex":{"en":"She's being touted as the next leader of the party.","cn":"她被吹捧为该党的下一任领导人。"}},{"en":"to try to persuade people to buy your goods or services, especially by going to them and asking them directly","cn":"兜售；推销","g":"[intransitive, transitive]","lab":"especially British English","ex":{"en":"the problem of unlicensed taxi drivers touting for business at airports","cn":"没有执照的出租汽车司机在机场揽生意的问题"}},{"en":"to sell tickets for a popular event illegally, at a price that is higher than the official price, especially outside a theatre, stadium, etc.","cn":"（尤指在剧院、体育场等外以高价）倒卖（门票）","g":"[transitive]","lab":"British English"},{"en":"a person who buys tickets for concerts, sports events, etc. and then sells them to other people at a higher price","cn":"票贩子；黄牛党","pos":"noun"}]}},"tot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小孩;幼儿","en":"A tot is a very young child."},{"pos":"N-COUNT 可数名词","cn":"(杯中烈酒的)少量","en":"A tot of a strong alcoholic drink such as whisky or brandy is a small amount of it in a glass."},{"pos":"","cn":"","en":"相关词组：tot up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small child","cn":"小娃娃"},{"en":"a small amount of a strong alcoholic drink","cn":"少量烈酒"},{"en":"to add together numbers or amounts of money in order to find the total","cn":"把〔数字或钱〕加起来"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tot_v0205.mp3","us":"media/ldoce/hwd/ame/0/l2tot.mp3"},"examples":[{"en":"The waiter quickly totted up the bill.","cn":"服务生很快便把账单算好了。"},{"en":"a tot of rum","cn":"少量朗姆酒"}],"oxford":{"phon":"tɒt","pos":"noun","senses":[{"en":"a very young child","cn":"幼儿","lab":"informal","ex":{"en":"TV programmes for tiny tots","cn":"给小孩子看的电视节目"}},{"en":"a small amount of a strong alcoholic drink in a glass","cn":"小杯烈酒","lab":"especially British English","ex":{"en":"a tot of whisky","cn":"一小杯威士忌"}}]}},"tonsils":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"扁桃体","en":"Your tonsils are the two small soft lumps in your throat at the back of your mouth."}]},"collocations":{"phrases":["ADJ. swollen","VERB + TONSILS have out I had my tonsils out when I was ten."]}},"tongue-tied":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因害羞、紧张等)张口结舌的，说不出话的","en":"If someone is tongue-tied, they are unable to say anything because they feel shy or nervous.","ex":{"en":"In their presence I became self-conscious and tongue-tied.","cn":"当着他们的面，我有些难为情，说不出话来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not speaking","cn":""},{"en":"to be unable to say anything because you are very surprised or because you are not prepared for the situation that has suddenly happened","cn":""},{"en":"to be suddenly unable to say anything because you are extremely surprised or shocked and cannot believe what has happened","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/tongue_tied0205.mp3","us":"media/ldoce/hwd/ame/9/tongue-tied.mp3"},"examples":[{"en":"When adults spoke to her, she became tongue-tied and shy.","cn":"大人和她讲话时﹐她会害羞得说不出话来。"}],"oxford":{"phon":"ˈtʌŋ taɪd","pos":"adjective","senses":[{"en":"not able to speak because you are shy or nervous","cn":"（因害羞或紧张）张口结舌的，说不出话来的","ex":{"en":"I always get nervous and tongue-tied in interviews.","cn":"我在采访中总是感到紧张、结结巴巴。"}}]}},"toboggan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"平底雪橇;长橇","en":"A toboggan is a light wooden board with a curved front, used for travelling down hills on snow or ice."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light wooden board with a curved front, used for sliding down hills covered in snow","cn":"平底雪橇"},{"en":"to slide down a hill on a toboggan","cn":"坐平底雪橇滑行"}]},"vocab":{"pos":"n v","senses":[{"en":"A toboggan is a type of sled that's light and thin. When you use such a sled, you're tobogganing ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/toboggan_n0205.mp3","us":"media/ldoce/hwd/ame/a/toboggan.mp3"},"oxford":{"phon":"təˈbɒɡən","pos":"noun","senses":[{"en":"a long, light, narrow sledge (= a vehicle that slides over snow) sometimes curved up in front, used for sliding down slopes","cn":"长雪橇；平底长雪橇"},{"en":"to travel down a slope on snow or ice using a toboggan","cn":"坐长雪橇滑行","pos":"verb"}]}},"token":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"象征性的;装点门面的","en":"You use token to describe things or actions which are small or unimportant but are meant to show particular intentions or feelings which may not be sincere.","ex":{"en":"The announcement was welcomed as a step in the right direction, but was widely seen as a token gesture","cn":"该公告被认为是向正确方向迈进的一步，因而受到欢迎，但也被普遍看作是一种象征性的姿态。"}},{"pos":"N-COUNT 可数名词","cn":"礼券;代金券;购物卡","en":"A token is a piece of paper or card that can be exchanged for goods, either in a particular shop or as part of a special offer.","ex":{"en":"…£10 book tokens…","cn":"价值 10 英镑的购书券"}},{"pos":"N-COUNT 可数名词","cn":"代币;专用辅币","en":"A token is a round flat piece of metal or plastic that is sometimes used instead of money.","ex":{"en":"Some of the older telephones still only accept tokens.","cn":"一些较老式的电话机仍然只收代币。"}},{"pos":"N-COUNT 可数名词","cn":"(情感的)表示，证明","en":"If you give something to a person or do something for them as a token of your feelings, you give it or do it as a way of expressing those feelings.","ex":{"en":"He kept sending gifts and assured her that they were merely small tokens of his appreciation…","cn":"他不断送她礼物，并向她保证说这些只是为了略表谢意。"}},{"pos":"PHRASE 短语","cn":"同样地;由于同样的原因","en":"You use by the same token to introduce a statement that you think is true for the same reasons that were given for a previous statement.","ex":{"en":"If you give up exercise, your muscles shrink and fat increases. By the same token, if you expend more energy you will lose fat.","cn":"停止锻炼会使肌肉萎缩、脂肪增加。同样，如果花更多的精力锻炼，就会减掉脂肪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round piece of metal that you use instead of money in some machines 〔","cn":"在某些机器上用来代替钱的〕金属代币"},{"en":"something that represents a feeling, fact, event etc","cn":"象征﹐标志"},{"en":"a special piece of paper that you can exchange for a book, record etc in a shop 〔","cn":"商店的〕购书礼券/唱片礼券/礼品券"}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"When you give someone a flower or a friendship bracelet or something symbolic of the way you feel about them, you're giving them a token of your affection."}]},"collocations":{"phrases":["ADJ. good luck, love","PREP. in ~ of She presented them with a small gift in token of her thanks.","PHRASES (as) a token of appreciation/friendship/respect We hope you will accept this book as a small token of our appreciation."]},"media":{"uk":"media/ldoce/hwd/bre/9/token_n0205.mp3","us":"media/ldoce/hwd/ame/6/token1.mp3"},"examples":[{"en":"The penalty for failure will be high. But, by the same token, the rewards for success will be great.","cn":"失败就要付出沉重的代价，同样，成功就会获得很大的回报。"},{"en":"The government has only made a token gesture towards helping the unemployed.","cn":"政府只不过是做做样子表示了一下对失业者的帮助。"}],"oxford":{"phon":"ˈtəʊkən","pos":"noun","senses":[{"en":"a round piece of metal or plastic used instead of money to operate some machines or as a form of payment","cn":"（用以启动某些机器或用作支付方式的）代币，专用辅币","ex":{"en":"a parking token","cn":"停车专用辅币"}},{"en":"a piece of paper that you pay for and that somebody can exchange for something in a shop","cn":"代金券","lab":"British English","ex":{"en":"a £20 book/record/gift token","cn":"价值 20 英镑的书券／唱片券／礼物券"}},{"en":"a piece of paper that you can collect when you buy a particular product and then exchange for something","cn":"赠券；礼券","ex":{"en":"Collect six tokens for a free T-shirt.","cn":"收集到六张礼券可以换一件 T 恤衫。"}},{"en":"something that is a symbol of a feeling, a fact, an event, etc.","cn":"（感觉、事实、事件等的）象征，标志，表示，信物","ex":{"en":"Please accept this small gift as a token of our gratitude.","cn":"区区薄礼，以表谢忱，请笑纳。"}},{"en":"involving very little effort or feeling and intended only as a way of showing other people that you think somebody/something is important, when really you are not sincere","cn":"装样子的；装点门面的；敷衍的","ex":{"en":"The government has only made a token gesture towards helping the unemployed.","cn":"政府只不过是做做样子表示了一下对失业者的帮助。"},"pos":"adjective"},{"en":"that you pay or charge somebody only as a symbol, because a payment is expected","cn":"象征性支付（或收取）的","ex":{"en":"We charge only a token fee for use of the facilities.","cn":"我们对使用这些设施只收取象征性的费用。"},"pos":"adjective"}]}},"toecap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(鞋或靴尖起保护或加固作用的)外包头","en":"A toecap is a piece of leather or metal which is fitted over the end of a shoe or boot in order to protect or strengthen it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of metal or leather that covers the front part of a shoe 〔","cn":"鞋前部的〕外包头﹐鞋头"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41toecap.mp3","us":"media/ldoce/hwd/ame/5/laadtoecap.mp3"},"oxford":{"phon":"ˈtəʊkæp","pos":"noun","senses":[{"en":"a piece of metal or leather that covers the front part of a shoe or boot to make it stronger","cn":"（鞋或靴尖的）外包头"}]}},"toss-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(发生几率各半的)相等机会;难以定夺的事","en":"If you say that it is a toss-up whether one thing will happen or another thing will happen, you mean that either result seems equally likely.","ex":{"en":"It's a toss-up whether oil prices will go up or down over the days ahead.","cn":"油价在今后的日子里会上涨还是下跌都有可能。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you say that something such as a game or a decision could go either way , you mean that either of two results is equally possible","cn":""},{"en":"a borderline case is a situation in which the decision is not certain, for example about whether someone should pass an exam, get a job etc","cn":""},{"en":"if you say there is a fifty-fifty chance of something happening, you mean there is an equal chance of it happening or not happening","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41toss-up.mp3","us":"media/ldoce/hwd/ame/e/toss-up.mp3"},"examples":[{"en":"‘Have you decided on the colour yet?’ ‘ It's a toss-up between the blue and the green.’ “","cn":"你决定了要什么颜色没有？” “在蓝色和绿色之间实在难以割舍。”"},{"en":"I don’t know who’ll get the job – it’s a toss-up between Carl and Steve.","cn":"我不知道谁会得到这份工作——卡尔和史蒂夫都有可能。"}],"oxford":{"phon":"ˈtɒs ʌp","pos":"noun","senses":[{"en":"a situation in which either of two choices, results, etc. is equally possible","cn":"（两种选择、结果等的）同样可能，均等机会","ex":{"en":"‘Have you decided on the colour yet?’ ‘It's a toss-up between the blue and the green.’","cn":"“你决定了要什么颜色没有？”“在蓝色和绿色之间实在难以取舍。”"}}]}},"toll":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(缓慢反复地)敲(钟)，鸣(丧钟);(钟)鸣响","en":"When a bell tolls or when someone tolls it, it rings slowly and repeatedly, often as a sign that someone has died.","ex":{"en":"Church bells tolled and black flags fluttered","cn":"教堂丧钟敲响，黑色的旗帜飘动。"}},{"pos":"N-COUNT 可数名词","cn":"(桥梁、道路的)通行费","en":"A toll is a small sum of money that you have to pay in order to use a particular bridge or road."},{"pos":"N-COUNT 可数名词","cn":"(公路、桥梁的)收费","en":"A toll road or toll bridge is a road or bridge where you have to pay in order to use it."},{"pos":"N-COUNT 可数名词","cn":"(死亡、事故或灾难的)总数","en":"A toll is a total number of deaths, accidents, or disasters that occur in a particular period of time.","ex":{"en":"There are fears that the casualty toll may be higher.","cn":"有人担心伤亡总数可能会更高。"}},{"pos":"PHRASE 短语","cn":"造成恶果(或不利影响、痛苦等)","en":"If you say that something takes its toll or takes a heavy toll, you mean that it has a bad effect or causes a lot of suffering.","ex":{"en":"Winter takes its toll on your health","cn":"冬天对健康不利。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of money you need to buy or do something. Cost is usually used when talking in a general way about whether something is expensive or cheap rather than when talking about exact prices","cn":""},{"en":"the amount of money you must pay for something that is for sale","cn":""},{"en":"the amount of money that something is worth","cn":""}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"A toll is a payment made for something. To drive on some highways, drivers have to pay a toll when they exit."}]},"collocations":{"phrases":["ADJ. motorway, road","VERB + TOLL charge, collect, exact, impose, levy the possibility of imposing tolls on some motorways | pay","TOLL + NOUN bridge, motorway, road | booth | charge 2 amount of damage done/number of people killed","ADJ. great, heavy, terrible, tragic | casualty, death, injury | human","VERB + TOLL take The pressure of fame can take a terrible toll. The recession is taking its toll.","TOLL + VERB mount, rise The death toll from yesterday's crash is still rising. | reach sth The casualty toll could reach 200.","PREP. ~ on Illness has taken a heavy toll on her."]},"media":{"uk":"media/ldoce/hwd/bre/c/toll_v0205.mp3","us":"media/ldoce/hwd/ame/7/toll1.mp3"},"examples":[{"en":"The official death toll has now reached 7 000.","cn":"官方公布的死亡人数现已达 7 000 人。"},{"en":"The recession is taking its toll on the housing markets.","cn":"经济衰退使住房市场遭受着重大损失。"}],"oxford":{"phon":"təʊl","pos":"noun","senses":[{"en":"money that you pay to use a particular road or bridge","cn":"（道路、桥梁的）通行费","g":"[countable]","ex":{"en":"motorway tolls","cn":"高速公路通行费"}},{"en":"the amount of damage or the number of deaths and injuries that are caused in a particular war, disaster, etc.","cn":"（战争、灾难等造成的）损失，伤亡人数","g":"[countable, usually singular]","ex":{"en":"the war’s growing casualty toll","cn":"不断增长的战争伤亡人数"}},{"en":"the sound of a bell ringing with slow, regular sounds","cn":"（缓慢而有规律的）钟声","g":"[singular]"},{"en":"a charge for a phone call that is calculated at a higher rate than a local call","cn":"长途电话费","g":"[countable]","lab":"North American English"},{"en":"when a bell tolls or somebody tolls it, it is rung slowly many times, especially as a sign that somebody has died","cn":"（缓慢而有规律地）敲（钟）；（尤指）鸣（丧钟）","lab":"figurative","ex":{"en":"The Abbey bell tolled for those killed in the war.","cn":"大教堂为战争中的死难者鸣钟。"},"pos":"verb"}]}},"toucan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巨嘴鸟","en":"A toucan is a South American bird with a large brightly-coloured beak."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tropical American bird with bright feathers and a very large beak","cn":"巨嘴鸟﹐【妥鸟】【空鸟】〔美洲热带地区的一种鸟〕"}]},"media":{"img":["media/ldoce/img/toucan.jpg"],"uk":"media/ldoce/hwd/bre/5/toucan0205.mp3","us":"media/ldoce/hwd/ame/0/toucan.mp3"},"oxford":{"phon":"ˈtuːkæn","pos":"noun","senses":[{"en":"a tropical American bird that is black with some areas of very bright feathers, and that has a very large beak","cn":"巨嘴鸟（分布于美洲热带地区，羽毛鲜艳，喙很大）"}]}},"tote":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(赛马的)赌金计算系统","en":"The Tote is a system of betting money on horses in races."},{"pos":"VERB 动词","cn":"（可见地）携带;（尤指）佩（枪）","en":"To tote something, especially a gun, means to carry it with you in such a way that people can see it.","ex":{"en":"The demonstrators fled when soldiers toting machine guns advanced on the crowd.","cn":"当持有机枪的士兵向人群进逼时，示威者逃散了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something or someone in your hands or arms when you go somewhere","cn":""},{"en":"to carry something such as a bag or a gun","cn":""},{"en":"to carry something heavy, with difficulty","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A tote is a bag or basket used to carry things. Toting also refers to lugging things around."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tote2.mp3","us":"media/ldoce/hwd/ame/9/tote.mp3"},"examples":[{"en":"We arrived, toting our bags and suitcases.","cn":"我们背着提包拎着衣箱到了那里。"},{"en":"gun-toting soldiers","cn":"持枪的士兵"}],"oxford":{"phon":"təʊt","pos":"noun","senses":[{"en":"a system of betting on horses in which the total amount of money that is bet on each race is divided among the people who bet on the winners","cn":"（赛马的）赌金计算系统","g":"[singular]"},{"en":"a large bag for carrying things with you","cn":"大手提袋；大提包","g":"[countable]","lab":"especially North American English"},{"en":"to carry something, especially something heavy","cn":"携带，搬运（尤指重物）","lab":"especially North American English, informal，，","ex":{"en":"We arrived, toting our bags and suitcases.","cn":"我们拎着包拖着行李箱到了那里。"},"pos":"verb"},{"en":"carrying the thing mentioned","cn":"携带…的","ex":{"en":"gun-toting soldiers","cn":"持枪的士兵"},"pos":"verb"}]}},"to-do":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"骚动;喧闹;吵嚷","en":"When there is a to-do, people are very excited, confused, or angry about something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lot of unnecessary excitement or angry feelings about something","cn":"无谓的骚动[喧闹]﹔大惊小怪"}]},"media":{"uk":"media/ldoce/hwd/bre/e/to_do0205.mp3","us":"media/ldoce/hwd/ame/e/to-do.mp3"},"examples":[{"en":"What a to-do!","cn":"真是太大惊小怪了！"},{"en":"There was such a to-do when I said I didn’t want to be married in a church!","cn":"我说我不想在教堂里举行婚礼﹐就引起这么大的震动！"}],"oxford":{"phon":"tə ˈduː","pos":"noun","senses":[{"en":"unnecessary excitement or anger about something","cn":"忙乱；喧嚷；大惊小怪；吵吵嚷嚷","ex":{"en":"What a to-do!","cn":"真是太大惊小怪了！"}}]}},"toiletries":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"洗漱用品","en":"Toiletries are things that you use when washing or taking care of your body, for example soap and toothpaste."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things such as soap and toothpaste that are used for cleaning yourself","cn":"洗漱用品﹔盥洗用品"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdetoiletries.mp3","us":"media/ldoce/hwd/ame/b/toiletries.mp3"},"oxford":{"phon":"ˈtɔɪlətriz","pos":"noun","senses":[{"en":"things such as soap or toothpaste that you use for washing, cleaning your teeth, etc.","cn":"（香皂、牙膏等）洗漱用品"}]}}});
